SET DEFINE OFF;
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('please give', 87, 'Nicole Holofcener''s newest might seem slight in places, but its rendering of complex characters in a conflicted economic landscape is varied, natural, and touching all the same.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the matador', 75, 'This humorously amoral, oddball comic thriller features strong performances by Pierce Brosnan and Greg Kinnear as a flamboyant, aging hit-man and an out of work suburban businessman, respectively.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the alamo', 52, 'John Wayne proves to be less compelling behind the camera than he is before it in The Alamo, a blustery dramatization of the fort''s last stand that feels more like a first draft.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('g', 24, 'Race and class struggles come to the Hamptons in this reworking of The Great Gatsby with a hip-hop flavor. Unfortunately, too many subplots and a lack of believable characters spoil an otherwise novel concept.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('aliens', 97, 'While Alien was a marvel of slow-building, atmospheric tension, Aliens packs a much more visceral punch, and features a typically strong performance from Sigourney Weaver.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('all the kings men', 95, 'Broderick Crawford is spellbinding as politician Willie Stark in director Robert Rossen''s adaptation of the Robert Penn Warren novel about the corrosive effects of power on the human soul.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the motel', 88, 'A coming-of-age dramedy whose familiar outline is filled in with rewarding empathy and character detail, The Motel marks an impressive feature debut for writer-director Michael Kang.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('disneys a christmas carol', 52, 'Robert Zemeckis'' 3-D animated take on the Dickens classic tries hard, but its dazzling special effects distract from an array of fine performances from Jim Carrey and Gary Oldman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the freshman', 94, 'Buoyed by the charm of Matthew Broderick in the title role and Marlon Brando as a caricature of his Godfather persona, The Freshman benefits from solid casting, a clever premise, and sweet humor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('land of the lost', 26, 'Only loosely based on the original TV series, Land of the Lost is decidedly less kid-friendly and feels more like a series of inconsistent sketches than a cohesive adventure comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rec', 89, 'Plunging viewers into the nightmarish hellscape of an apartment complex under siege, [Rec] proves that found footage can still be used as an effective delivery mechanism for sparse, economic horror.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the road', 73, 'The Road''s commitment to Cormac McCarthy''s dark vision may prove too unyielding for some, but the film benefits from hauntingly powerful performances from Viggo Mortensen and Kodi McPhee.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the duchess', 62, 'While The Duchess treads the now-familiar terrain of the corset-ripper, the costumes look great and Keira Knightley''s performance is stellar in this subtly feminist, period drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('public enemies', 68, 'Michael Mann''s latest is a competent and technically impressive gangster flick with charismatic lead performances, but some may find the film lacks truly compelling drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('notorious', 52, 'A biopic that lacks the luster of its subject, Notorious is generic rise-and-fall fare that still functions as a primer for those less familiar with the work and life of the hip hop icon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('igor', 39, 'With an animation style that apes Tim Burton, and a slew of cultural references that aren''t clear enough to reach the crowds, Igor''s patched together antics make it hard to see who the film is trying to please.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my sisters keeper', 48, 'My Sister''s Keeper gets fine performances from its adult and child actors, but the director''s heavy-handed approach turns a worthy emotional subject into an overly melodramatic tearjerker.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the red baron der rote baron', 20, 'It doesn''t lack ambition, and it boasts undeniably thrilling source material, but The Red Baron is brought down by its overly sentimental script and a number of historical inaccuracies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('outrage', 77, 'Outrage walks a difficult moral and ethical line -- and not always successfully -- but despite its flaws, it''s a fascinating, provocative look at homosexuality in American politics.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('skin', 84, 'Sophie Okonedo, Sam Neill, and Alice Krige do wonderful work in Skin, delivering performances whose strength is underlined by the incredible real-life events upon which the movie is based.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shrink', 27, 'Kevin Spacey''s performance is almost sharp enough to save this Hollywood dramedy from itself, but in the end, he''s dragged down by a cliched script and indifferent direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ong bak 2', 48, 'It suffers from comparisons to its predecessor -- not to mention Tony Jaa''s less-than-nimble direction -- but Ong Bak 2 has all the extravagant violence and playful style that fans of the original will expect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('high life', 80, 'High Life is as visually arresting as it is challenging, confounding, and ultimately rewarding - which is to say it''s everything film fans expect from director Claire Denis.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('around the world in 80 days', 69, 'It''s undeniably shallow, but its cheerful lack of pretense -- as well as its grand scale and star-stuffed cast -- help make Around the World in 80 Days charmingly light-hearted entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wonderful world', 42, 'Matthew Broderick gives an appealing performance and director Joshua Goldin''s script contains unexpected bursts of honest emotion, but Wonderful World''s good intentions can''t make up for its lack of originality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('going the distance', 54, 'It''s timelier and a little more honest than most romantic comedies, but Drew Barrymore and Justin Long''s screen chemistry doesn''t make up for Going the Distance''s overall flatness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('life as we know it', 29, 'Katherine Heigl and Josh Duhamel make a charming couple with plenty of chemistry, but that isn''t enough to make up for Life as We Know It''s formulaic plot and poorly written script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('frozen', 63, 'Writer/director Adam Green has the beginnings of an inventive, frightening yarn in Frozen, but neither the script nor the cast are quite strong enough to truly do it justice.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('prodigal sons', 87, 'Fascinating and heartbreakingly honest, Kimberly Reed''s family documentary uses its stranger-than-fiction story to speak near-universal truths about family bonds and human identity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the ghost writer', 84, 'While it may lack the revelatory punch of Polanski''s finest films, Ghost Writer benefits from stylish direction, a tense screenplay, and a strong central performance from Ewan McGregor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('winters bone', 94, 'Bleak, haunting, and yet still somehow hopeful, Winter''s Bone is writer-director Debra Granik''s best work yet -- and it boasts an incredible, starmaking performance from Jennifer Lawrence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beauty and the beast la belle et la bête', 95, 'With its magical optical effects and enchanting performances, Jean Cocteau''s Beauty and the Beast remains the most surreal -- and soulful -- of the fairy tale''s film adaptations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('brians song', 92, 'Buoyed by standout performances from James Caan and Billy Dee Williams, Brian''s Song is a touching tale of friendship whose central relationship transcends its standard sports movie moments.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('brief encounter', 91, 'Brief Encounter adds a small but valuable gem to the Lean filmography, depicting a doomed couple''s illicit connection with affecting sensitivity and a pair of powerful performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('butch cassidy and the sundance kid', 90, 'With its iconic pairing of Paul Newman and Robert Redford, jaunty screenplay and Burt Bacharach score, Butch Cassidy and the Sundance Kid has gone down as among the defining moments in late-''60s American cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('carrie', 93, 'Carrie is a horrifying look at supernatural powers, high school cruelty, and teen angst -- and it brings us one of the most memorable and disturbing prom scenes in history.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('casablanca', 99, 'An undisputed masterpiece and perhaps Hollywood''s quintessential statement on love and romance, Casablanca has only improved with age, boasting career-defining performances from Humphrey Bogart and Ingrid Bergman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cat on a hot tin roof', 97, 'Paul Newman and Elizabeth Taylor are at the height of their glamor and performing prowess in this feverish adaptation of Tennessee Williams'' play, with a subtext of sexual repression providing an electric undercurrent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cat people', 61, 'Paul Schrader''s kinky reimagining of Cat People may prove too grisly and lurid for some audiences, but its provocative style and Natassja Kinski''s hypnotic performance should please viewers who like a little gasoline with their fire.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('charade', 94, 'A globetrotting caper that prizes its idiosyncratic pieces over the general puzzle, Charade is a delightful romp with Cary Grant and Audrey Hepburn''s sparkling chemistry at the center of some perfectly orchestrated mayhem.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('day of the dead', 81, 'Day of the Dead may arguably be the least haunting entry in George A. Romero''s undead trilogy, but it will give audiences'' plenty to chew on with its shocking gore and scathing view of society.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('how the grinch stole christmas', 100, 'How the Grinch Stole Christmas brings an impressive array of talent to bear on an adaptation that honors a classic holiday story -- and has rightfully become a yuletide tradition of its own.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the elephant man', 92, 'David Lynch''s relatively straight second feature finds an admirable synthesis of compassion and restraint in treating its subject, and features outstanding performances by John Hurt and Anthony Hopkins.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('father of the bride', 90, 'With a terrific script, great performances from Spencer Tracy and Elizabeth Taylor, and assured direction from Vincent Minnelli, Father of the Bride endures as a sparkling comedy of its era.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flash gordon', 83, 'Campy charm and a knowing sense of humor help to overcome a silly plot involving a spacefaring ex-football player, his adoring bevy of groupies, and a supervillain named Ming the Merciless.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('from here to eternity', 92, 'It has perhaps aged poorly, but this languidly paced WWII romance remains an iconic, well-acted film, featuring particularly strong performances from Burt Lancaster and Montgomery Clift.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('frosty the snowman', 73, 'Frosty the Snowman is a jolly, happy sing-along that will delight children with its crisp animation and affable title character, who makes an indelible impression with his corncob pipe, button nose, and eyes made out of coal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gallipoli', 91, 'Peter Weir''s devastating anti-war film features a low-key but emotionally wrenching performance from Mel Gibson as a young soldier fighting in one of World War I''s most deadly and horrifying battles.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gloria', 93, 'A comparatively commercial entry from director John Cassavetes, Gloria''s pulpy pleasures are elevated by his observant touch and Gena Rowlands'' galvanizing star performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('glory', 93, 'Bolstered by exceptional cinematography, powerful storytelling, and an Oscar-winning performance by Denzel Washington, Glory remains one of the finest Civil War movies ever made.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hamlet', 95, 'A well-executed labor of love from star and director Laurence Olivier, Hamlet not only proved that Shakespeare could be successfully adapted to the big screen, it paved the way for further cinematic interpretations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hardcore', 76, 'Director Paul Schrader''s preoccupations with alienation and faith are given a compelling avatar in George C. Scott''s superb performance, although some audiences may find Hardcore too soft to live up to its provocative promise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heaven can wait', 88, 'A throwback to the high-gloss screwball comedies of the 1940s, Heaven Can Wait beguiles with seamless production values and great comic relief from Charles Grodin and Dianne Cannon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('house on haunted hill', 88, 'Campy by modern standards but spooky and atmospheric, House on Haunted Hill is a fun, well-executed cult classic featuring a memorable performance from genre icon Vincent Price.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hud', 82, 'A Western that swaps out the Hollywood glamor for shades of moral gray, Hud is a sobering showcase for a sterling ensemble of actors at the top of their respective games.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('invasion of the body snatchers', 93, 'Employing gritty camerawork and evocative sound effects, Invasion of the Body Snatchers is a powerful remake that expands upon themes and ideas only lightly explored in the original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the island of dr moreau', 56, 'The Island of Dr. Moreau takes a reasonably entertaining pass at adapting its classic source material, although key scenes are let down by struggles with special effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the king of comedy', 89, 'Largely misunderstood upon its release, The King of Comedy today looks eerily prescient, and features a fine performance by Robert DeNiro as a strangely sympathetic psychopath.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('legend', 38, 'Not even Ridley Scott''s gorgeously realized set pieces can save Legend from its own tawdry tale -- though it may be serviceable for those simply looking for fantasy eye candy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lion in winter', 90, 'Sharper and wittier than your average period piece, The Lion in Winter is a tale of palace intrigue bolstered by fantastic performances from Peter O''Toole, Katharine Hepburn, and Anthony Hopkins in his big-screen debut.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the little drummer boy', 75, 'The Little Drummer Boy is a mature addition to the Rankin-Bass catalogue, with a powerful conclusion that compensates for the special''s dour storytelling and unpolished animation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little shop of horrors', 90, 'Remixing Roger Corman''s B-movie by way of the Off-Broadway musical, Little Shop of Horrors offers camp, horror and catchy tunes in equal measure -- plus some inspired cameos by the likes of Steve Martin and Bill Murray.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lolita', 91, 'Kubrick''s Lolita adapts its seemingly unadaptable source material with a sly comedic touch and a sterling performance by James Mason that transforms the controversial novel into something refreshingly new without sacrificing its essential edge.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the longest yard', 79, 'Equal parts tough and funny, and led by a perfectly cast Burt Reynolds, The Longest Yard has an interesting political subtext and an excellent climax -- even if it takes too long to get there.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('manhunter', 93, 'Michael Mann introduces audiences to Hannibal Lecter for the first time in Manhunter, a modish thriller that fleshes out Thomas Harris'' heinous creations with an elegant, chilling detachment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mannequin', 21, 'Mannequin is a real dummy, outfitted with a ludicrous concept and a painfully earnest script that never springs to life, despite the best efforts of an impossibly charming Kim Cattrall.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the mission', 64, 'The Mission is a well-meaning epic given delicate heft by its sumptuous visuals and a standout score by Ennio Morricone, but its staid presentation never stirs an emotional investment in its characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mutiny on the bounty', 93, 'The historical inaccuracies in this high-seas adventure are more than offset by its timeless themes, larger-than-life performances from Clark Gable and Charles Laughton, and Frank Lloyd''s superb direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('no way out', 91, 'Roger Donaldson''s modern spin on the dense, stylish suspense films of the 1940s features fine work from Gene Hackman and Sean Young, as well as the career-making performance that made Kevin Costner a star.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('obsession', 73, 'Obsession suffers in comparison to the Alfred Hitchcock masterpiece that it mirrors, but director Brian De Palma''s unique preoccupations give this thriller its own compulsive, twisted fingerprint.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('point blank', 95, 'Shot with hard-hitting inventiveness and performed with pitiless cool by Lee Marvin, Point Blank is a revenge thriller that exemplifies that exemplifies the genre''s strengths with extreme prejudice.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the poseidon adventure', 80, 'The Poseidon Adventure exemplifies the disaster film done right, going down smoothly with ratcheting tension and a terrific ensemble to give the peril a distressingly human dimension.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the producers', 90, 'A hilarious satire of the business side of Hollywood, The Producers is one of Mel Brooks'' finest, as well as funniest films, featuring standout performances by Gene Wilder and Zero Mostel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('red dawn', 46, 'An appealing ensemble of young stars will have some audiences rooting for the Wolverines, but Red Dawn''s self-seriousness can never conceal the silliness of its alarmist concept.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('return to oz', 53, 'Return to Oz taps into the darker side of L. Frank Baum''s book series with an intermittently dazzling adventure that never quite recaptures the magic of its classic predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('short circuit', 59, 'Amiable and good-natured but also shallow and predictable, Short Circuit is hardly as deep or emotionally resonant as E.T. -- though Johnny Five makes for a charming robot protagonist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stagecoach', 100, 'Typifying the best that the Western genre has to offer, Stagecoach is a rip-roaring adventure given dramatic heft by John Ford''s dynamic direction and John Wayne''s mesmerizing star turn.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a streetcar named desire', 98, 'A feverish rendition of a heart-rending story, A Streetcar Named Desire gives Tennessee Williams'' stage play explosive power on the screen thanks to Elia Kazan''s searing direction and a sterling ensemble at the peak of their craft.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('suspicion', 97, 'Not even notorious studio meddling can diminish the craft and tantalizing suspense of Suspicion, a sly showcase for Joan Fontaine''s nervy prowess and Alfred Hitchcock''s flair for disquiet.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('them', 100, 'One of the best creature features of the early atomic age, Them! features effectively menacing special effects and avoids the self-parody that would taint later monster movies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shivers they came from within the parasite murders', 84, 'Shivers uses elementally effective basic ingredients to brilliant effect - and lays the profoundly unsettling foundation for director David Cronenberg''s career to follow.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('three amigos', 45, 'Three Amigos! stars a trio of gifted comedians and has an agreeably silly sense of humor, but they''re often adrift in a dawdling story with too few laugh-out-loud moments.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the time machine', 76, 'Its campy flourishes tend to subdue its dramatic stakes, but The Time Machine brings H.G. Wells'' story to life with plenty of sci-fi charm and a colorful sense of visual design.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tommy', 70, 'Tommy is as erratic and propulsive as a game of pinball, incorporating The Who''s songs into an irreverent odyssey with the visual imagination that only director Ken Russell can conjure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('le procès the trial', 83, 'Orson Welles may take big liberties in his adaptation of The Trial, but the auteur constructs an absurd nightmare that is unmistakably Kafkaesque -- grounded by an excellent Anthony Perkins as the befuddled Josef K.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('weird science', 57, 'Hardly in the same league as John Hughes'' other teen movies, the resolutely goofy Weird Science nonetheless gets some laughs via its ridiculous premise and enjoyable performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('102 dalmatians', 31, 'This sequel to the live-action 101 Dalmatians is simply more of the same. Critics say it also drags in parts, potentially boring children, and that it''s too violent for a G-rated movie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('white fang', 65, 'This glossy edition of White Fang shaves off the rough-hewn edges that made Jack London''s epic story so distinct, but gorgeous photography and heartfelt performances make this an appealing adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('come and see idi i smotri', 97, 'As effectively anti-war as movies can be, Come and See is a harrowing odyssey through the worst that humanity is capable of, directed with bravura intensity by Elem Klimov.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jfk', 84, 'As history, Oliver Stone''s JFK is dubious, but as filmmaking it''s electric, cramming a ton of information and excitement into its three-hour runtime and making great use of its outstanding cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man in the moon', 90, 'It''s sentimental, and some viewers may feel manipulated by the melodramatic final act, but The Man in the Moon offers a finely drawn coming-of-age story with an excellent cast -- including Reese Witherspoon in her film debut.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('father of the bride', 70, 'While it doesn''t quite hit the heights of the original, this remake of the 1950 classic is pleasantly enjoyable, thanks in large part to winning performances from Steve Martin and Martin Short.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('unforgiven', 96, 'As both director and star, Clint Eastwood strips away decades of Hollywood varnish applied to the Wild West, and emerges with a series of harshly eloquent statements about the nature of violence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('malcolm x', 88, 'Anchored by a powerful performance from Denzel Washington, Spike Lee''s biopic of legendary civil rights leader Malcolm X brings his autobiography to life with an epic sweep and a nuanced message.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('scent of a woman', 89, 'It might soar on Al Pacino''s performance more than the drama itself, but what a performance it is -- big, bold, occasionally over-the-top, and finally giving the Academy pause to award the star his first Oscar.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the vanishing', 49, 'The Vanishing copies the form of its pulse-pounding predecessor but loses much of its thrilling function along the way, leaving American audiences with one more rote remake.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('born yesterday', 23, 'Not even Melanie Griffith''s charisma can inject fresh energy into this ill-conceived remake, which awkwardly retreads through the classic original''s story without any of its charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cliffhanger', 69, 'While it can''t escape comparisons to the movies it borrows from, Cliffhanger is a tense, action-packed thriller and a showcase for the talents that made Sylvester Stallone a star.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gettysburg', 77, 'Gettysburg''s reverent approach to history is balanced with the committed work of a talented cast - and the hard-hitting dramatization of a bloody turning point in the Civil War.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('high noon', 97, 'A classic of the Western genre that broke with many of the traditions at the time, High Noon endures -- in no small part thanks to Gary Cooper''s defiant, Oscar-winning performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heaven earth', 40, 'Heaven & Earth is a well-intentioned glimpse into an underrepresented perspective on Vietnam, but Oliver Stone''s solemn storytelling keeps audiences at a fatal distance from Hiep Thi Le''s enigmatic heroine.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the kid', 100, 'Charles Chaplin'' irascible Tramp is given able support from Jackie Coogan as The Kid in this slapstick masterpiece, balancing the guffaws with moments of disarming poignancy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rudyard kiplings the jungle book', 80, 'Rudyard Kipling''s The Jungle Book may not hew as closely to the book as its title suggests, but it still offers an entertaining live-action take on a story best known in animated form.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('street fighter', 10, 'Though it offers mild entertainment through campy one-liners and the overacting of the late Raul Julia, Street Fighter''s nonstop action sequences are not enough to make up for a predictable, uneven storyline.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little women', 92, 'Thanks to a powerhouse lineup of talented actresses, Gillian Armstrong''s take on Louisa May Alcott''s Little Women proves that a timeless story can succeed no matter how many times it''s told.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nobodys fool', 91, 'It''s solidly directed by Robert Benton and stacked with fine performances from an impressive cast, but above all, Nobody''s Fool is a showcase for some of Paul Newman''s best late-period work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad boys', 42, 'Bad Boys stars Will Smith and Martin Lawrence have enjoyable chemistry; unfortunately, director Michael Bay too often drowns it out with set pieces and explosions in place of an actual story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('braveheart', 78, 'Distractingly violent and historically dodgy, Mel Gibson''s Braveheart justifies its epic length by delivering enough sweeping action, drama, and romance to match its ambition.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the scarlet letter', 13, 'The Scarlet Letter strays far from its classic source material to tell a story that strains for steamy sensuality and leaves the audience red with unintentional laughter.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('casino', 80, 'Impressive ambition and bravura performances from an outstanding cast help Casino pay off in spite of a familiar narrative that may strike some viewers as a safe bet for director Martin Scorsese.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('richard iii', 94, 'This re-imagining of Shakespeare''s Crookback King relocates the story in 1930 and features an indelible star turn for Ian McKellen as the monstrous and magnetic King Richard.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heat', 87, 'Though Al Pacino and Robert De Niro share but a handful of screen minutes together, Heat is an engrossing crime drama that draws compelling performances from its stars -- and confirms Michael Mann''s mastery of the genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the addiction', 75, 'Abel Ferrara''s 1995 horror/suspense experiment blends urban vampire adventure with philosophical analysis to create a smart, idiosyncratic, and undeniably odd take on the genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dead man walking', 95, 'A powerful, thought-provoking film that covers different angles of its topic without resorting to preaching, Dead Man Walking will cause the viewer to reflect regardless of their political viewpoint.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('broken arrow', 52, 'John Woo adds pyrotechnic glaze to John Travolta''s hammy performance, but fans may find Broken Arrow to be a dispiritingly disposable English-language entry for the action auteur.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('restoration', 70, 'Restoration spins an engaging period yarn out of its bestselling source material, brought to life through the efforts of an eclectic ensemble cast led by Robert Downey Jr.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('diabolique', 18, 'This seedy remake of a classic French chiller goes through the motions in recreating the original''s diabolical plot, but without the genuine suspense or stylistic finesse.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last supper', 63, 'It struggles to find a balance between its humor and its message, but The Last Supper''s sharp script and well-chosen cast offer just enough nourishment for fans of black comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the fan', 37, 'Tony Scott''s visceral flash proves to be an ill fit for The Fan, a queasy tale of obsession that succeeds at making audiences uncomfortable, but strikes out when it comes to delivering the thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('house arrest', 10, 'Constructed out of cliches, thinly written characters, and fundamental misunderstandings of human nature, House Arrest is a dull (and borderline irresponsible) waste of a talented cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hunchback of notre dame', 71, 'Disney''s take on the Victor Hugo classic is dramatically uneven, but its strong visuals, dark themes, and message of tolerance make for a more-sophisticated-than-average children''s film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('emma', 85, 'Emma marks an auspicious debut for writer-director Douglas McGrath, making the most of its Jane Austen source material -- and a charming performance from Gwyneth Paltrow.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('scream', 78, 'Horror icon Wes Craven''s subversive deconstruction of the genre is sly, witty, and surprisingly effective as a slasher film itself, even if it''s a little too cheeky for some.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in love and war', 11, 'Formulaic and trite, In Love and War unconvincingly recreates Ernest Hemingway''s early life with all the stuffy tropes that the author would have excised in a second draft.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the crucible', 68, 'This staid adaptation of The Crucible dutifully renders Arthur Miller''s landmark play on the screen with handsome production design and sturdy performances, if not with the political anger and thematic depth that earned the drama its reputation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hamlet', 95, 'Kenneth Branagh''s sprawling, finely textured adaptation of Shakespeare''s masterpiece lives up to its source material, using strong performances and a sharp cinematic focus to create a powerfully resonant film that wastes none of its 246 minutes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('traveller', 79, 'Though it may not explore its core issues as deeply as some may like, Traveller is nevertheless a smart and funny portrait of a relatively unfamiliar subculture with some strong performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('contact', 66, 'Contact elucidates stirring scientific concepts and theological inquiry at the expense of satisfying storytelling, making for a brainy blockbuster that engages with its ideas, if not its characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the rainmaker', 82, 'Invigorated by its talented cast and Francis Ford Coppola''s strong direction, The Rainmaker is a satisfying legal drama -- and arguably the best of Hollywood''s many John Grisham adaptations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man in the iron mask', 32, 'Leonardo DiCaprio plays dual roles with diminishing returns in The Man in the Iron Mask, a cheesy rendition of the Musketeers'' epilogue that bears all the pageantry of Alexandre Dumas'' text, but none of its romantic panache.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('twilight', 60, 'It suffers from a frustratingly deliberate pace, but with nuanced performances from Paul Newman, Gene Hackman, Susan Sarandon, and Reese Witherspoon to fall back on, Twilight can''t help but be compelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the parent trap', 86, 'Writer-director Nancy Meyers takes the winning formula of the 1961 original and gives it an amiable modern spin, while young star Lindsay Lohan shines in her breakout role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the negotiator', 74, 'The Negotiator''s battle of wits doesn''t wholly justify its excessive length, but confident direction by F. Gary Gray and formidable performances makes this a situation audiences won''t mind being hostage to.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('elizabeth', 82, 'No mere historical drama, Elizabeth is a rich, suspenseful journey into the heart of British Royal politics, and features a typically outstanding performance from Cate Blanchett.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('happiness', 81, 'Happiness is far from a cheerful viewing experience, but its grimly humorous script and fearless performances produce a perversely moving search for humanity within everyday depravity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lolita', 68, 'If it can''t quite live up to Nabokov''s words, Adrian Lyne''s Lolita manages to find new emotional notes in this complicated story, thanks in large part to its solid performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the impostors', 62, 'The Impostors might have benefited from a more consistently witty script, but writer-director Stanley Tucci acquits himself nicely as an orchestrator of screwball comedy in this uneven debut.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dick', 71, 'A clever, funny slice of alternate history, Dick farcically re-imagines the Watergate era and largely succeeds, thanks to quirky, winning performances from Michelle Williams, Kirsten Dunst and Will Ferrell.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the best man', 72, 'With a strong cast and a host of well-defined characters, The Best Man is an intelligent, funny romantic comedy that marks an impressive debut for writer/director Malcolm D. Lee.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hurricane', 83, 'Thanks in large part to one of Denzel Washington''s most powerful on-screen performances, The Hurricane is a moving, inspirational sports drama, even if it takes few risks in telling its story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('committed', 43, 'Critics say Committed is one of those films that shows promise -- some sort of vision -- of what the movie could have been. The key word is "could." As it is, the script is predictable, the story becomes tedious, and it''s simply not funny. Heather Graham shows she can play a central character, but she''s not enough to make Committed successful.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gone in 60 seconds gone in sixty seconds', 25, 'Even though Oscar-bearers Nicolas Cage, Angelina Jolie, and Robert Duval came aboard for this project, the quality of Gone in 60 Seconds is disappointingly low. The plot line is nonsensical, and even the promised car-chase scenes are boring.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('10 cloverfield lane', 90, 'Smart, solidly crafted, and palpably tense, 10 Cloverfield Lane makes the most of its confined setting and outstanding cast -- and suggests a new frontier for franchise filmmaking.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beautiful', 16, 'Sally Field''s directing debut suffers from an inconsistent tone, implausible script, and a protagonist that critics say is one of the most loathsome to come around in a long time.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the contender', 76, 'The Contender wears its political heart on its sleeve, but strong performances and a solid screenplay help the end result add up to a gripping drama from either side of the aisle.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lost souls', 8, 'Though Kaminski''s film is visually stylish, Lost Souls is just another derivative entry in the Apocalypse genre, with lackluster direction, unengaging characters, and no scares.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('malena', 54, 'Malena ends up objectifying the character of the movie''s title. Also, the young boy''s emotional investment with Malena is never convincing, as she doesn''t feel like a three-dimensional person.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the gift', 57, 'With a reported budget of around 10 million, The Gift is obviously a labor of love for those involved. Unfortunately, the A-list cast can''t prevent the movie from becoming a by-the-numbers whodunit with an ending that''s all but unsatisfactory.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('traffic', 93, 'Soderbergh successfully pulls off the highly ambitious Traffic, a movie with three different stories and a very large cast. The issues of ethics are gray rather than black-and-white, with no clear-cut good guys. Terrific acting all around.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heartbreakers', 53, 'Though the actors pour a lot of energy into their roles, Heartbreakers is too drawn out, and the romantic subplot doesn''t blend well. Also, the con women aren''t particularly sympathetic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ace in the hole the big carnival', 92, 'Spearheaded by an excellent Kirk Douglas, Ace in the Hole is an incisive and sardonic satire that, much like its opportunistic hero, never lets moral compunction get in the way of a good story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pearl harbor', 24, 'Pearl Harbor tries to be the Titanic of war movies, but it''s just a tedious romance filled with laughably bad dialogue. The 40 minute action sequence is spectacular though.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the time machine', 29, 'This Machine has all the razzle-dazzles of modern special effects, but the movie takes a turn for the worst when it switches from a story about lost love to a confusing action-thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('carrie', 20, 'This made-for-TV adaptation of Stephen King''s classic fails to impress or bring anything new to the table, - or to the prom - paling even more in comparison to the 1970''s memorable version.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hide and seek', 13, 'Robert De Niro and especially Dakota Fanning have earned some praise for their work in Hide and Seek, but critics have called the rest of the film derivative, illogical and somewhat silly.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('venom', 11, 'A voodoo horror flick without the mojo, Venom is chock full of gory impalings of interchangeable teenage girls and hunky guys by an unstoppable zombie whose unimaginative rampage quickly lulls us to sleep.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('good night and good luck', 93, 'A passionate and concise cinematic civics lesson, Good Night, And Good Luck has plenty to say about today''s political and cultural climate, and its ensemble cast is stellar.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rent', 46, 'Fans of the stage musical may forgive Rent its flaws, but weak direction, inescapable staginess and an irritating faux-boho pretension prevent the film from connecting on screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the new world', 63, 'Despite arresting visuals and strong lead performances, The New World suffers from an unfocused narrative that will challenge viewers'' attention spans over its 2 1/2 hours.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pride and prejudice', 86, 'Sure, it''s another adaptation of cinema''s fave Jane Austen novel, but key performances and a modern filmmaking sensibility make this familiar period piece fresh and enjoyable.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('on a clear day', 68, 'Another blue-collar inspirational feel-good British dramedy, On A Clear Day succeeds on the strength of lead actor Peter Mullan''s performance and Gaby Dellal''s competent direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('london', 14, 'Hampered by pretension and undermined by unlikable characters, London proves that the novelty of seeing actors play against type isn''t enough to rescue a deeply flawed film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little fish', 90, 'Fueled by powerful work from a strong cast led by Cate Blanchett, Little Fish is a hard-hitting story worth watching -- and a major step forward for director Rowan Woods.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the devil and daniel johnston', 88, 'Whether you think this mentally ill cult musician is worthy of being called a "genius," this document of his life is crafted with sincere respect and is fascinating to watch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('marie antoinette', 57, 'Lavish imagery and a daring soundtrack set this film apart from most period dramas; in fact, style completely takes precedence over plot and character development in Coppola''s vision of the doomed queen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bobby', 47, 'Despite best intentions from director Emilio Estevez and his ensemble cast, they succumb to a script filled with pointless subplots and awkward moments working too hard to parallel contemporary times.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('coastlines', 48, 'Coastlines features solid lead performances, but is hindered by an unconvincing love triangle and scattered direction. Not up to the standard of Victor Nunez''s previous directorial efforts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ballets russes', 92, 'Even if you know little about ballet, there is much to love about this documentary''s captivating archival footage and its interviews with elderly former dancers who have much to share.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the bridge', 68, 'Tactlessly morbid or remarkably sensitive? Deeply disturbing or viscerally fascinating? Critics are divided on Eric Steele''s unique documentary on the Golden Gate Bridge, wonder of the modern world and notorious suicide destination.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('perfect stranger', 10, 'Despite the presence of Halle Berry and Bruce Willis, Perfect Stranger is too convoluted to work, and features a twist ending that''s irritating and superfluous. It''s a techno-thriller without thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wanted', 71, 'Wanted is stylish, energetic popcorn fare with witty performances from Angelina Jolie (playing an expert assassin), James McAvoy, and Morgan Freeman that help to distract from its absurdly over-the-top plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the jane austen book club', 66, 'Though at times formulaic and sentimental, Jane Austen Book Club succeeds on the strength of its likable ensemble cast. Even those not familiar with Jane Austen''s work may find much to enjoy this lighthearted romance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('billy the kid', 81, 'Jennifer Venditti''s doc Billy the Kid turns "special" into a double edged sword, forging a sharply honest film around a strangely enigmatic -- if awkward -- kid named Billy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('angels demons', 37, 'Angels and Demons is a fast-paced thrill ride, and an improvement on the last Dan Brown adaptation, but the storyline too often wavers between implausible and ridiculous, and does not translate effectively to the big screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghost town', 85, 'Ricky Gervais'' consistently sharp performance and beautifully dry execution transform this otherwise mainstream comedy into an endearing, funny, and altogether snappy romantic comedy. With ghosts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('step brothers', 55, 'Step Brothers indulges in a cheerfully relentless immaturity that will quickly turn off viewers unamused by Ferrell and Reilly -- and delight those who find their antics hilarious.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the perfect game', 57, 'It''s bogged down with an unfocused script and countless sports movie cliches, but The Perfect Game still manages to charm with its unabashed sweetness and a stirring final act.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the wrecking crew', 94, 'The Wrecking Crew may not achieve the greatness of the many classic songs its subjects helped bring to life, but it remains a heartfelt, overdue tribute to overshadowed brilliance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the tooth fairy', 17, 'Dwayne Johnson brings the full force of his charm (and his appropriately pale chompers) to the title role, but flat direction and a committee-written script render The Tooth Fairy unacceptably dull.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('green zone', 53, 'Matt Damon and Paul Greengrass return to the propulsive action and visceral editing of the Bourne films -- but a cliched script and stock characters keep those methods from being as effective this time around.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('9', 57, 'Although its story is perhaps too familiar and less complex than some might wish, 9 is visually spectacular, and director Shane Acker''s attention to detail succeeds in drawing viewers into the film''s universe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the twilight saga eclipse', 48, 'Stuffed with characters and overly reliant on uninspired dialogue, Eclipse won''t win The Twilight Saga many new converts, despite an improved blend of romance and action fantasy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('did you hear about the morgans', 11, 'It gets a certain amount of mileage out of the inherent likability of its stars, but with an unfunny script and a lack of onscreen chemistry, Did You Hear About the Morgans? falls flat.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('death in love', 45, 'Death in Love has the depth of its convictions, but not even the game efforts of a talented cast are enough to overcome this drama''s stilted story and unlikable characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('x games 3d the movie', 38, 'Though fans of the event will likely enjoy X-Games 3D: The Movie, most will find it a poorly put together, skin deep, extended advertisement for the extreme sports competition.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('brothers', 64, 'It plays more like a traditional melodrama than the Susanne Bier film that inspired it, but Jim Sheridan''s Brothers benefits from rock-solid performances by its three leads.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('anita oday the life of a jazz singer', 100, 'This rich documentary chronicles the highs and lows of one of the medium''s finest singers, utilizing remarkable archive footage and insightful interviews with O''Day herself.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('earth days', 82, 'This engaging and well-organized eco-doc maps the successes and failures of the American environmental movement, thanks to sharp interviews and remarkable archive footage.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('franklyn', 57, 'Gerald McMorrow''s bold debut is a complex and ambitious film that highlights the director''s potential, but its multi-layered story takes time to develop and might be frustrating for some.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('we live in public', 82, 'This documentary about Josh Harris'' surveillance-as-art project exposes the problems of privacy in the internet age and asks provocative questions about the power of ego in a place where everything is on display.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blind date', 33, 'Despite the chemistry of stars Patricia Clarkson and Stanely Tucci, Blind Date''s stagey direction and underdeveloped story make it feel more like a rehearsal than a performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a single man', 85, 'Though the costumes are beautiful and the art direction impeccable, what stands out most from this debut by fashion designer Tom Ford is the leading performance by Colin Firth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('127 hours', 93, 'As gut-wrenching as it is inspirational, 127 Hours unites one of Danny Boyle''s most beautifully exuberant directorial efforts with a terrific performance from James Franco.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('12 strong', 50, '12 Strong has a solid cast, honorable intentions, and a thrilling, fact-based story - all of which are occasionally enough to balance a disappointing lack of depth or nuance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('13 going on 30', 65, 'Although the plot leaves a lot to be desired, 13 Going on 30 will tug at your inner teenager''s heartstrings thanks in large part to a dazzling performance from Jennifer Garner.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('13 hours the secret soldiers of benghazi', 51, '13 Hours: The Secret Soldiers of Benghazi is a comparatively mature and restrained effort from Michael Bay, albeit one that can''t quite boast the impact its fact-based story deserves.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('2001 a space odyssey', 92, 'One of the most influential of all sci-fi films -- and one of the most controversial -- Stanley Kubrick''s 2001 is a delicate, poetic meditation on the ingenuity -- and folly -- of mankind.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('22 july', 80, '22 July offers a hard-hitting close-up look at the aftereffects of terrorism, telling a story with a thriller''s visceral impact and the lingering emotional resonance of a drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('22 jump street', 85, 'Boasting even more of the bromantic chemistry between its stars -- and even more of the goofy, good-natured humor that made its predecessor so much fun -- 22 Jump Street is the rare sequel that improves upon the original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('300 rise of an empire', 45, 'It''s bound to hit some viewers as an empty exercise in stylish gore, and despite a gonzo starring performance from Eva Green, 300: Rise of an Empire is a step down from its predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('30 minutes or less', 45, 'It''s sporadically funny and it benefits from a talented cast, but 30 Minutes or Less suffers from a disjointed narrative, and too often mistakes crude gags for true lowbrow humor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('310 to yuma', 89, 'This remake of a classic Western improves on the original, thanks to fiery performances from Russell Crowe and Christian Bale as well as sharp direction from James Mangold.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('48 hrs', 93, 'Marking an auspicious feature film debut for Eddie Murphy, 48 Hrs. is a briskly paced action comedy that succeeds largely due to the outstanding chemistry between its two leads.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('50 first dates', 45, 'Gross-out humor overwhelms the easy chemistry between Adam Sandler and Drew Barrymore, who bring some energy and yucks to this tale of a girl with short-term memory loss and the guy who tries to get her to love him.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('56 up', 99, 'Director Michael Apted continues to utilize cinema as a window into the lives of everyday people, and in the reflection of this documentary we can glimpse our own aging humanity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('6 souls', 4, 'The most mind-bending aspect of 6 Souls is Julianne Moore''s participation, the overqualified star wasted on a goofy horror premise that generates more guffaws than scares.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('6 underground', 36, '6 Underground is loud, frenetic, and finally preposterous -- which is either bad news or a hearty recommendation, depending how one feels about the movies of Michael Bay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('99 homes', 93, 'Fueled by powerful acting and a taut, patiently constructed narrative, 99 Homes is a modern economic parable whose righteous fury is matched by its intelligence and compassion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a bad moms christmas', 32, 'Featuring twice the moms but roughly half the laughs, A Bad Moms Christmas is a slapdash holiday sequel that falls short of the original with a disappointing dearth of good cheer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a bigger splash', 90, 'Absorbing, visually arresting, and powerfully acted by an immensely talented cast, A Bigger Splash offers sumptuously soapy delights for fans of psychological adult drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a bread factory part one for the sake of gold', 100, 'Epic yet intimate, A Bread Factory, Part One: For the Sake of Gold delivers the sprawling storytelling and nourishing drama audiences might expect from its imposing title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a brighter summer day', 100, 'A fantastic cinematic and artistic achievement, Edward Yang''s A Brighter Summer Day depicts youth, ideals, violence and politics in a melancholic, tender light, culminating in a complex portrait of Taiwanese identity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a cure for wellness', 42, 'A Cure for Wellness boasts a surfeit of visual style, but it''s wasted on a derivative and predictable story whose twists, turns, and frights have all been more effectively dealt before.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a dangerous method', 78, 'A provocative historical fiction about the early days of psychoanalysis, A Dangerous Method is buoyed by terrific performances by Michael Fassbender, Keira Knightley, and Viggo Mortensen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a girl walks home alone at night', 96, 'A Girl Walks Home Alone at Night blends conventional elements into something brilliantly original -- and serves as a striking calling card for writer-director Ana Lily Amirpour.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a haunted house 2', 8, 'Sloppy, vulgar, and manic, A Haunted House 2 might be worth a chuckle or two, but mostly it''s a string of pop culture references and crude gags that fail to hit their intended targets.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a nightmare on elm street 2 freddys revenge', 41, 'An intriguing subtext of repressed sexuality gives Freddy''s Revenge some texture, but the Nightmare loses its edge in a sequel that lacks convincing performances or memorable scares.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a nightmare on elm street 5 the dream child', 31, 'A Nightmare on Elm Street feels exhausted by this cheesy fifth entry, bogged down by a convoluted mythology while showing none of the chilling technique that kicked off the franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a quiet passion', 91, 'A Quiet Passion offers a finely detailed portrait of a life whose placid passage may not have been inherently cinematic, but is made more affecting by Cynthia Nixon''s strong performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a quiet place', 96, 'A Quiet Place artfully plays on elemental fears with a ruthlessly intelligent creature feature that''s as original as it is scary -- and establishes director John Krasinski as a rising talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a screaming man', 88, 'A Screaming Man deftly uses its personal look at a family dynamic to offer pointed political observations, confirming writer-director Mahamat-Saleh Haroun as a major talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a star is born', 90, 'With appealing leads, deft direction, and an affecting love story, A Star Is Born is a remake done right -- and a reminder that some stories can be just as effective in the retelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a street cat named bob', 77, 'A Street Cat Named Bob uses a fact-based feelgood tale as the inspiration for an unapologetically heartwarming movie that should move all but the most cynical of viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a touch of sin', 94, 'Its screenplay isn''t as graceful as the choreography of its action sequences, but A Touch of Sin offers enough stylishly satisfying violence to muscle past its rough spots.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a walk among the tombstones', 68, 'A Walk Among the Tombstones doesn''t entirely transcend its genre clichés, but it does offer Liam Neeson one of his more compelling roles in recent memory, and that''s often enough.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a walk into the sea danny williams and the warhol factory', 79, 'A portrait piece of Danny Williams, set amongst New Yorks Factory, home of Andy Warhol, provides insight and flavour of the time and the setting, with an unresolved mystery at its heart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a woman a gun and a noodle shop san qiang pai an jing qi a simple noodle story the first gun', 34, 'Zhang Yimou''s broad reinterpretation of the Coen Brothers'' Blood Simple struggles to bring anything new to the twisty murder mystery and instead ladles on an excess of stilted comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a wrinkle in time', 42, 'A Wrinkle in Time is visually gorgeous, big-hearted, and occasionally quite moving; unfortunately, it''s also wildly ambitious to a fault, and often less than the sum of its classic parts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('about alex', 45, 'About Alex pointedly provokes comparisons to The Big Chill, but the script doesn''t have enough substance to support them -- or give its talented cast enough to work with.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('about last night', 61, 'About Last Night will perturb fans of the original stage play by sanding down its pricklier edges, but an amiable cast and sexual frankness make this a pleasantly grounded romantic comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('about last night', 69, 'About Last Night wanders even further from the David Mamet play that inspired the original, but it benefits from an engaging cast and a screenplay that smartly balances romance and comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('abraham lincoln vampire hunter', 34, 'Abraham Lincoln: Vampire Hunter has visual style to spare, but its overly serious tone doesn''t jibe with its decidedly silly central premise, leaving filmgoers with an unfulfilling blend of clashing ingredients.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('absolutely anything', 18, 'Given the impressive array of talent involved in Absolutely Anything -- and the near-total lack of laughs it provokes -- this Monty Python reunion can only be regarded as a disappointment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('absolutely fabulous the movie', 58, 'Absolutely Fabulous: The Movie picks up pretty much where its source material left off, delivering an adaptation that, as fans of this British export might say, does what it says on the tin.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ace ventura pet detective', 49, 'Jim Carrey''s twitchy antics and gross-out humor are on full, bombastic display in Ace Ventura: Pet Detective, which is great news for fans of his particular brand of comedy but likely unsatisfying for anyone else.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('act of valor', 27, 'It''s undeniably reverent of the real-life heroes in its cast, but Act of Valor lets them down with a clichéd script, stilted acting, and a jingoistic attitude that ignores the complexities of war.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the adventures of baron munchausen', 92, 'Bursting with Terry Gilliam''s typically imaginative flourishes, this story of a possibly deranged Baron recounting his storied life is a flamboyant and witty visual treat.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the adventures of priscilla queen of the desert', 96, 'While its premise is ripe for comedy -- and it certainly delivers its fair share of laughs -- Priscilla is also a surprisingly tender and thoughtful road movie with some outstanding performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('after love léconomie du couple', 90, 'After Love isn''t easy viewing, but its brutally honest examination of a crumbling family offers powerful performances and penetrating insights that make it well worth the effort.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('aftershock', 38, 'Aftershock hints at an inventive twist on horror tropes, but ultimately settles for another round of mind-numbing depravity that may alternately bore and revolt all but the most ardent gore enthusiasts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('aint them bodies saints', 77, 'While conventional in plot, Ain''t Them Bodies Saints is a visually poetic film that pays homage to the New Hollywood directors of the 1970s and promises big things from director David Lowery.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i saw the devil', 81, 'Never flinching during its descent into depravity, I Saw the Devil is a pulverizing thriller that will give bloody satisfaction to audiences who like their revenge served with fiery rage.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alexander and the terrible horrible no good very bad day', 61, 'Affably pleasant without ever trying to be anything more, Alexander and the Terrible, Horrible, No Good, Very Bad Day is a fine -- albeit forgettable -- family diversion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alfie', 48, 'This unnecessary remake wants Alfie to have his cake and eat it, too, but a lack of sexual fizz and a sour performance by Jude Law conspire to deliver audiences a romantic comedy that isn''t romantic or funny.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ali', 68, 'Though perhaps no film could fully do justice to the fascinating life and personality of Muhammad Ali, Mann''s direction and Smith''s performance combine to pack a solid punch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ali wong hard knock wife', 100, 'Ali Wong emerges a mother still perturbed in Hard Knock Wife, a hilariously honest hour of comedy that highlights the joys and oh boys of motherhood with fearless energy and just the right amount of squirmy detail.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alice through the looking glass', 29, 'Alice Through the Looking Glass is just as visually impressive as its predecessor, but that isn''t enough to cover for an underwhelming story that fails to live up to its classic characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alien3', 43, 'Alien3 takes admirable risks with franchise mythology, but far too few pay off in a thinly scripted sequel whose stylish visuals aren''t enough to enliven a lack of genuine thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alien nation', 53, 'Alien Nation takes the interesting premise of extraterrestrials living among us and doesn''t do enough with it, emphasizing a police procedural plotline over the more intriguing sci-fi elements.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alien resurrection', 54, 'Alien Resurrection marks a slight improvement over its predecessor, but still lacks the emotional stakes that helped make the franchise''s first two entries sci-fi/horror classics.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alita battle angel', 61, 'Alita: Battle Angel''s story struggles to keep up with its special effects, but fans of futuristic sci-fi action may still find themselves more than sufficiently entertained.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('all about my mother todo sobre mi madre', 98, 'Almodovar weaves together a magnificent tapestry of femininity with an affectionate wink to classics of theater and cinema in this poignant story of love, loss and compassion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('all good things', 35, 'It''s well-acted, and the true story that inspired it offers plenty of drama -- which is why it''s so frustrating that All Good Things is so clichéd and frustratingly ambiguous.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('all is lost', 94, 'Anchored by another tremendous performance in a career full of them, All Is Lost offers a moving, eminently worthwhile testament to Robert Redford''s ability to hold the screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('all is well alles ist gut', 100, 'Eva Trobisch''s debut film is a painful study of female trauma that extends a compassionate, while uncomfortable look to its main character, fiercely impersonated by the excellent Aenne Schwarz.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('all the bright places', 66, 'Though it at times buckles under the emotional weight of its source material, All The Bright Place succeeds on the strength of Elle Fanning and Justice Smith''s charming and tender performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('all the pretty horses', 32, 'This adaptation of Cormac McCarthy''s novel comes off as rather flat and uninvolving. Scenes feel rushed and done in shorthand, and the romance between Damon and Cruz has no sparks.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('allied', 60, 'Allied has its moments, but doesn''t quite achieve epic wartime romance status -- a disappointment made more profound by the dazzling talent assembled on either side of the camera.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('almost christmas', 49, 'While far from the worst holiday dramedy audiences could hope for, Almost Christmas isn''t distinctive enough to prompt a visit to the theater -- or annual yuletide viewings.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('alpha dog', 54, 'A glossy yet unflinching portrait of violent, hedonistic teenagers. Bruce Willis and Sharon Stone chew the scenery, while Justin Timberlake gives a noteworthy performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('always', 67, 'Its central romance takes occasional dives into excessive sentimentality, but Always otherwise flies high thanks to director Steven Spielberg''s rousing feel for adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('always be my maybe', 89, 'Carried by the infectious charms of Ali Wong and Randall Park, Always Be My Maybe takes familiar rom-com beats and cleverly layers in smart social commentary to find its own sweet groove.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('amanda knox', 82, 'Amanda Knox honors its subject with an absorbing -- if slightly incomplete -- look at the details and troubling implications of her arrest and subsequent fight for freedom.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('amelia', 20, 'Amelia takes the compelling raw materials of its subject''s life and does little with them, conventionally ticking off Earhart''s accomplishments without exploring the soul of the woman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('america the beautiful', 72, 'This doc doesn''t expose any new territory about our unattainable standards of beauty, but does manage to entertain with an effective and accessible tone by filmmaker/subject Darryl Roberts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american assassin', 34, 'American Assassin hits a few easy targets, but without enough style or wit to truly bring its characters to life -- or stand out in a crowded field of more compelling spy thrillers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american buffalo', 74, 'It lacks the dynamism of other adaptations of his work, but American Buffalo still offers the tenacious characterizations and hard-hitting dialogue that are hallmarks of David Mamet''s writing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american graffiti', 96, 'One of the most influential of all teen films, American Graffiti is a funny, nostalgic, and bittersweet look at a group of recent high school grads'' last days of innocence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american honey', 79, 'American Honey offers a refreshingly unconventional take on the coming-of-age drama whose narrative risks add up to a rewarding experience even if they don''t all pay off.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('an american in paris', 96, 'The plot may be problematic, but such concerns are rendered superfluous by Gene Kelly and Leslie Caron''s star power, the Gershwins'' classic songs, and Vincente Minnelli''s colorful, sympathetic direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american mary', 60, 'It suffers a bit from some uneven acting and an underwhelming climax, but American Mary utilizes pitch black humor and striking visuals to deliver gory, freaky thrills for body horror enthusiasts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american pastoral', 23, 'American Pastoral finds debuting director Ewan McGregor''s reach exceeding its grasp with a well-intentioned Philip Roth adaptation that retains the form, but little of the function, of its source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the american president', 91, 'A charming romantic comedy with political bite, Rob Reiner''s American President features strong lead performances and some poignant observations of politics and media in the 1990s.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american psycho', 69, 'If it falls short of the deadly satire of Bret Easton Ellis''s novel, American Psycho still finds its own blend of horror and humor, thanks in part to a fittingly creepy performance by Christian Bale.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american reunion', 45, 'It''ll provide sweetly nostalgic comfort food for fans of the franchise, but American Reunion fails to do anything truly new or interesting -- or even very funny -- with the characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american sniper', 72, 'Powered by Clint Eastwood''s sure-handed direction and a gripping central performance from Bradley Cooper, American Sniper delivers a tense, vivid tribute to its real-life subject.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('american son', 48, 'Kerry Washington capably anchors American Son with her nervy turn as a concerned mother, but the staginess of the production ill-serves its heavy-handed social commentary.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('americas heart and soul', 50, 'Louis Schwartzberg''s sprawling tour across America highlights the heartland''s visual beauty, but this resolutely uncritical inquiry in the nation''s soul is frustratingly shallow.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('amy schumer growing', 79, 'Amy Schumer''s standup matures in an hour filled with concise insights into aging and matrimony, marked with only slight Growing pains as the comedian refreshes her comedic voice.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('an education', 94, 'Though the latter part of the film may not appeal to all, An Education is a charming coming-of-age tale powered by the strength of relative newcomer Carey Mulligan''s standout performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('an evening with beverly luff linn', 52, 'An Evening with Beverly Luff Linn unites an intriguing array of comedic talents for a thoroughly unusual outing that proves itself disappointingly difficult to recommend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('an inconvenient sequel truth to power', 79, 'An Inconvenient Sequel: Truth to Power makes a plea for environmental responsibility that adds a persuasive -- albeit arguably less impactful -- coda to its acclaimed predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('anatomy of a murder', 100, 'One of cinema''s greatest courtroom dramas, Anatomy of a Murder is tense, thought-provoking, and brilliantly acted, with great performances from James Stewart and George C. Scott.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('anchorman the legend of ron burgundy', 67, 'Filled with inspired silliness and quotable lines, Anchorman isn''t the most consistent comedy in the world, but Will Ferrell''s buffoonish central performance helps keep this portrait of a clueless newsman from going off the rails.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('anchorman 2 the legend continues', 74, 'It''s just as uneven and loosely structured as the first Anchorman -- and while Anchorman 2: The Legend Continues may not be quite as quotable, it''s nearly as funny as its predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('and everything is going fine', 91, 'Even if And Everything Is Going Fine isn''t one of Soderbergh''s more commercial efforts, this collection of judiciously edited performance footage of the late monologist Spalding Gray gave the director a chance to show a rarely-seen side of his artistry.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the andromeda strain', 67, 'Although its urgent subject matter warrants less a deliberate pace, The Andromeda Strain brings Michael Crichton''s techno-thriller to the big screen with striking intelligence and an engrossing sense of paranoia.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('angus thongs and perfect snogging', 72, 'Based on two of British writer Louise Rennison''s popular books, Angus, Thongs and Perfect Snogging is a pleasant and funny tween comedy, comfortable for UK audiences as well as stateside crowds.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('animals', 85, 'Animals'' drug-fueled storyline is undeniably grim, but its sensitive approach to its difficult themes -- and its talented cast -- make watching it well worth the discomfort.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('annihilation', 88, 'Annihilation backs up its sci-fi visual wonders and visceral genre thrills with an impressively ambitious -- and surprisingly strange -- exploration of challenging themes that should leave audiences pondering long after the end credits roll.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('anon', 37, 'Lacking enough depth to fulfill its evident ambitions or enough excitement to work as a sci-fi action thriller, Anon lives down to its title in the most glumly predictable ways.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('anonymous', 45, 'Roland Emmerich delivers his trademark visual and emotional bombast, but the more Anonymous stops and tries to convince the audience of its half-baked theory, the less convincing it becomes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('another year', 93, 'Characterized by strong performances and the director''s trademark feel for the nuances of everyday life, Another Year marks another solid entry in Mike Leigh''s career of kitchen-sink English drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the answer man arlen faber', 30, 'The Answer Man takes an interesting premise and overloads it with implausible scenarios, indie comedy cliches, and an all-too-familiar story arc that only occasionally benefits from its typically capable actors.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('antman', 83, 'Led by a charming performance from Paul Rudd, Ant-Man offers Marvel thrills on an appropriately smaller scale -- albeit not as smoothly as its most successful predecessors.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('anywhere but here', 64, 'The strong chemistry between Susan Sarandon and Natalie Portman as a mother and daughter trying to make a fresh start in L.A. helps to elevate Anywhere But Here above its occasional forays into melodrama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('apollo 13', 96, 'In recreating the troubled space mission, Apollo 13 pulls no punches: it''s a masterfully told drama from director Ron Howard, bolstered by an ensemble of solid performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('april and the extraordinary world avril et le monde truqué', 96, 'Bursting with a colorful imagination befitting its promise-packed title, April and the Extraordinary World offers spectacular delights for animation fans willing to venture off the beaten path.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('armageddon', 38, 'Lovely to look at but about as intelligent as the asteroid that serves as the movie''s antagonist, Armageddon slickly sums up the cinematic legacies of producer Jerry Bruckheimer and director Michael Bay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('army of darkness', 73, 'Army of Darkness is a madcap adventure worth taking thanks to Bruce Campbell''s hammy charm and Sam Raimi''s acrobatic direction, although an intentional lack of shocks make this a discordant capper to the Evil Dead franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('arrival', 94, 'Arrival delivers a must-see experience for fans of thinking person''s sci-fi that anchors its heady themes with genuinely affecting emotion and a terrific performance from Amy Adams.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('art and craft', 91, 'The spotlight it shines on an apparently troubled mind may strike some viewers as exploitative, but Art and Craft remains a thoroughly gripping glimpse into the life of a legendary art forger.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('arthur miller writer', 91, 'Director Rebecca Miller delivers a homespun documentary about one of America''s most iconic playwrights, utilizing intimate footage and personal insight to craft a warm retrospective of her father''s life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('as good as it gets', 85, 'James L. Brooks and Jack Nicholson, doing what they do best, combine smart dialogue and flawless acting to squeeze fresh entertainment value out of the romantic-comedy genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('assassins creed', 18, 'Assassin''s Creed is arguably better made (and certainly better cast) than most video game adaptations; unfortunately, the CGI-fueled end result still is still a joylessly overplotted slog.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('astro boy astroboy', 50, 'While it isn''t terribly original, and it seems to have a political agenda that may rankle some viewers, Astro Boy boasts enough visual thrills to please its target demographic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('at any price', 51, 'At Any Price features a terrific performance from Dennis Quaid, and it offers further evidence of Ramin Bahrani''s unique eye for detail, but film is weighted down by an overly melodramatic story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('atlantic city', 100, 'Bittersweet and reflective, Atlantic City is a modest romance given raw power by Burt Lancaster and Susan Sarandon''s heartfelt performances along with director Louis Malle''s eccentric eye for detail.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('atomic blonde', 78, 'Atomic Blonde gets enough mileage out of its stylish action sequences -- and ever-magnetic star -- to make up for a narrative that''s somewhat less hard-hitting than its protagonist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('atonement', 83, 'Atonement features strong performances, brilliant cinematography, and a unique score. Featuring deft performances from James MacAvoy and Keira Knightley, it''s a successful adaptation of Ian McEwan''s novel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('august osage county', 67, 'The sheer amount of acting going on in August: Osage County threatens to overwhelm, but when the actors involved are as talented as Meryl Streep and Julia Roberts, it''s difficult to complain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('autumn in new york', 19, 'Although the film isn''t as bad as feared (it wasn''t pre-screened for reviews), it''s not that good, either. Most noticable flaws are the sappy romantic cliches and lack of chemistry between Gere and Ryder.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('avatar', 82, 'It might be more impressive on a technical level than as a piece of storytelling, but Avatar reaffirms James Cameron''s singular gift for imaginative, absorbing filmmaking.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('avengement', 84, 'Avengement compensates for a lack of narrative originality with thrilling sequences of violent, bone-crunching action, elevated by Scott Adkins'' brutally intense performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('avengers age of ultron', 76, 'Exuberant and eye-popping, Avengers: Age of Ultron serves as an overstuffed but mostly satisfying sequel, reuniting its predecessor''s unwieldy cast with a few new additions and a worthy foe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('avengers infinity war', 85, 'Avengers: Infinity War ably juggles a dizzying array of MCU heroes in the fight against their gravest threat yet, and the result is a thrilling, emotionally resonant blockbuster that (mostly) realizes its gargantuan ambitions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the aviator', 86, 'With a rich sense of period detail, The Aviator succeeds thanks to typically assured direction from Martin Scorsese and a strong performance from Leonardo DiCaprio, who charts Howard Hughes'' descent from eccentric billionaire to reclusive madman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('await further instructions', 80, 'A yuletide nightmare full of familial angst and slithering scares, Await Further Instructions is a genre treat that pretty much any horror fan will want in their stocking.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('away from her', 94, 'An accomplished directorial debut by Sarah Polley, Away From Her is a touching exploration of the effects of Alzheimer''s, in which the tender wisdom of Polley''s script is beautifully complemented by a wonderful performance from Julie Christie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('aziz ansari right now', 84, 'Aziz Ansari balances sharp social commentary with just enough earnest introspection to craft a special that, while not without its baggage, shows how far the comedian has come - and how far he may still have to go.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('babel', 69, 'In Babel, there are no villains, only victims of fate and circumstance. Director Alejandro Gonzalez Iñarritu weaves four of their woeful stories into this mature and multidimensional film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('babettes feast babettes gæstebud', 97, 'Charming and melancholy, Babette''s Feast is a timeless Scandinavian treat that explores the complex relationships between people, beliefs, and what it means to be an artist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('baby driver', 92, 'Stylish, exciting, and fueled by a killer soundtrack, Baby Driver hits the road and it''s gone -- proving fast-paced action movies can be smartly written without sacrificing thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bachelorette', 56, 'It has its moments, but Bachelorette ultimately plays it too safe with its trio of unlikable leads, betraying them with a predictably sentimental final act that undermines the bracingly honest humor preceding it.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('back to school', 86, 'Back to School gives Rodney Dangerfield plenty of room to riff -- and supports the freewheeling funnyman with enough of a story to keep things interesting between punchlines.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad lieutenant port of call new orleans', 85, 'Befitting its unorthodox origins, this Bad Lieutenant benefits from Werner Herzog''s typically fearless direction and a delightfully unhinged Nicolas Cage in the title role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad moms', 58, 'Bad Moms boasts a terrific cast and a welcome twist on domestic comedy -- and they''re often enough to compensate for the movie''s unfortunate inability to take full advantage of its assets.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad news bears', 48, 'This too-faithful remake aims low for laughs, turning off the easily offendable; despite another lovably irascible contribution by Thornton, it lacks the ensemble strength and originality of the 1976 version.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad reputation', 79, 'Bad Reputation offers fans and novices a solidly entertaining overview of Joan Jett''s trailblazing career, albeit one that might leave some viewers craving a deeper look.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad samaritan', 53, 'Bad Samaritan delivers a handful of genre thrills -- and a stellar central performance by David Tennant -- that help offset iffy direction and a disappointingly mundane story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad santa 2', 24, 'Loaded up with the same scatological and misanthropic humor as its predecessor but precious little of its heart or genuine wit, Bad Santa 2 presents a foulmouthed shadow of Christmas past.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bad taste', 68, 'Peter Jackson''s early low-budget shocker boasts a disgusting premise - aliens harvesting humans for fast food - that gives the budding auteur plenty of room for gross-out visuals and absurd cleverness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('balto', 54, 'Balto is a well-meaning adventure with spirited animation, but mushy sentimentality and bland characterization keeps it at paw''s length from more sophisticated family fare.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('band aid', 87, 'Band Aid tells a solidly affecting story of a relationship on the rocks -- and marks star Zoe Lister-Jones, who also wrote and directed, as a tremendous triple threat worth watching.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('barton fink', 90, 'Twisty and unsettling, the Coen brothers'' satirical tale of a 1940s playwright struggling with writer''s block is packed with their trademark sense of humor and terrific performances from its cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('baseketball', 42, 'Baseketball isn''t just a succession of fouls thanks to the comedic zip of David Zucker''s direction, but sophomoric gags and a lack of performance hustle by Trey Parker and Matt Stone makes this satire a clumsy bunt.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('basic instinct', 53, 'Unevenly echoing the work of Alfred Hitchcock, Basic Instinct contains a star-making performance from Sharon Stone but is ultimately undone by its problematic, overly lurid plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('baskin', 79, 'Baskin complements its gory thrills with heavy atmosphere and deliberate pacing, adding up to a horror outing that plays with the mind as enthusiastically as it ruins the appetite.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('batman beyond return of the joker', 91, 'This feature length entry in the Batman Beyond mythos sends off the Mark Hamill-voiced Joker in thrilling fashion, hitting the same caped crusading peaks of the original series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('batman return of the caped crusaders', 94, 'Adam West''s groovy interpretation of the The Caped Crusader returns in a new medium, popping in the realm of animation with the irascible energy of an exclamation-accented onomatopoeia.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('batman returns', 80, 'Director Tim Burton''s dark, brooding atmosphere, Michael Keaton''s work as the tormented hero, and the flawless casting of Danny DeVito as The Penguin and Christopher Walken as, well, Christopher Walken make the sequel better than the first.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('batman the killing joke', 40, 'This stilted retelling of the Joker''s origin adds little to its iconic source material, further diminished by some questionable story additions that will have fans demanding justice for Barbara Gordon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('batman v superman dawn of justice', 28, 'Batman v Superman: Dawn of Justice smothers a potentially powerful story -- and some of America''s most iconic superheroes -- in a grim whirlwind of effects-driven action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('battleship', 34, 'It may offer energetic escapism for less demanding filmgoers, but Battleship is too loud, poorly written, and formulaic to justify its expense -- and a lot less fun than its source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beauty and the beast', 71, 'With an enchanting cast, beautifully crafted songs, and a painterly eye for detail, Beauty and the Beast offers a faithful yet fresh retelling that honors its beloved source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('becoming jane', 58, 'Although Becoming Jane is a well-crafted period piece, it lacks fresh insight into the life and works of Jane Austen. The film focuses too much on wardrobe and not enough on Austen''s achievements.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bedknobs and broomsticks', 66, 'Bedknobs and Broomsticks often feels like a pale imitation of a certain magical guardian and her wards, but a spoonful of Angela Lansbury''s witty star power helps the derivativeness go down.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('before midnight', 98, 'Building on the first two installments in Richard Linklater''s well-crafted Before trilogy, Before Midnight offers intelligent, powerfully acted perspectives on love, marriage, and long-term commitment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('before night falls', 73, 'An impressionistic, fragmented look at Reinaldo Arenas, Before Night Falls'' imagery manages to evoke a sense of the writer''s artistry, and Bardem''s strong performance holds the film together. Finally, a biopic done well.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('before sunrise', 100, 'Thought-provoking and beautifully filmed, Before Sunrise is an intelligent, unabashedly romantic look at modern love, led by marvelously natural performances from Ethan Hawke and Julie Delpy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('before we go', 27, 'Chris Evans'' directorial debut is modest to a fault, with a threadbare story and minimal style leaving his and Alice Eve''s likable performances adrift in New York City with nowhere to go.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('begin again', 83, 'Writer-director John Carney''s return to musical drama isn''t quite as potent as it was with Once, but thanks to charming work from its well-matched leads, Begin Again is difficult to resist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('behind the candelabra', 95, 'Affectionate without sacrificing honesty, Behind the Candelabra couples award-worthy performances from Michael Douglas and Matt Damon with some typically sharp direction from Steven Soderbergh.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('belle', 84, 'It boasts all the surface beauty that fans of period pictures have come to expect, but Belle also benefits from its stirring performances and subtle social consciousness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beneath the planet of the apes', 38, 'Beneath the Planet of the Apes delivers more action than its predecessor -- unfortunately, at the expense of the social subtext that elevates the franchise''s best entries.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('benji off the leash', 33, 'Benji: Off the Leash! features an adorable dog and a solid message about how to treat animals, but is too dull and amateurish a viewing experience to recommend for all but the youngest viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beowulf', 71, 'Featuring groundbreaking animation, stunning visuals, and a talented cast, Beowulf has in spades what more faithful book adaptations forget to bring: pure cinematic entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('berberian sound studio', 85, 'Its reach may exceed its grasp, but with Berberian Sound Studio, director Peter Strickland assembles a suitably twisted, creepy tribute to the Italian Giallo horror movies of the ''70s that benefits from a strong central performance by Toby Jones.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('berlin syndrome', 75, 'Berlin Syndrome offers thriller fans an uncommonly well-written descent into dangerous obsession, enlivened by taut direction and a committed performance from Teresa Palmer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the best years of our lives', 97, 'An engrossing look at the triumphs and travails of war veterans, The Best Years of Our Lives is concerned specifically with the aftermath of World War II, but its messages speak to the overall American experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beverly hills cop iii', 9, 'Despite being set at an amusement park, Beverly Hills Cop III forgets to have any fun as it churns out uninspired violence and witless gags, with an uncharacteristically lethargic Eddie Murphy not helping matters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beware of mr baker', 98, 'Free of the hagiographic overtones that dog many documentary profiles, Beware of Mr. Baker presents a clear-eyed, thoroughly gripping look at one of rock''s greatest -- and most personally problematic -- musicians.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beyond the hills', 91, 'Although some viewers may mistake its deliberate pace for passionless filmmaking, Beyond the Hills offers an intelligent, powerfully acted examination of the tension between secular life and religious faith.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beyond the lights', 84, 'Thanks to smart direction and a powerhouse performance from Gugu Mbatha-Raw, Beyond the Lights transcends its formulaic storyline to deliver thoroughly entertaining drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beyond the mat', 82, 'Even if you aren''t a fan, Beyond the Mat provides a riveting, perceptive look into the world of professional wrestling by taking a closer look at the people beneath the personas.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('beyond the reach', 37, 'Beyond the Reach promises goofy genre pleasures, but fails to deliver, losing the viewer -- and a villainous turn from Michael Douglas -- in a misguided story that stumbles to the finish.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('big ass spider', 78, 'Big Ass Spider! delivers on the promise of its outlandish title with a tongue-in-cheek creature feature that embraces its B-movie silliness with utterly entertaining results.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the big bounce', 16, 'Lazily crafted and light on substance, The Big Bounce takes few chances and strands its promising cast in a subpar adaptation that fails to do its source material justice.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the big easy', 89, 'Loaded with atmosphere and drenched in the sizzling chemistry between Dennis Quaid and Ellen Barkin, The Big Easy remains one of the strongest -- and steamiest -- thrillers of the 1980s.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('big game', 78, 'Big Game''s enthusiastic throwback vibe will appeal to fans of low-budget ''80s action movies, but co-writer/director Jalmari Helander adds a level of smarts and skill that make it more than just an homage.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the big picture', 87, 'The Big Picture aims at targets that might not be familiar to viewers who aren''t well-versed in movie-biz chicanery, but hits most of them so solidly that laughter is the only option.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('big star nothing can hurt me', 92, 'Big Star: Nothing Can Hurt Me offers a persuasive argument for its subjects'' cult classic oeuvre -- and presents a painfully passionate lament for their untapped potential.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bikram yogi guru predator', 96, 'By exposing the corrupt systems which enabled him, Bikram: Yogi, Guru, Predator paints a disturbing -- and necessary -- portrait of the cycles of abuse endured by countless followers of the charlatan at its center.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bill teds bogus journey', 57, 'Bill and Ted''s Bogus Journey has the same stars -- and cheerfully wacky sense of humor -- as its predecessor, but they prove a far less effective combination the second time around.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bill cunningham new york', 99, 'Suffused with happiness and modest charm, Bill Cunningham New York offers a touching, gently humorous portrait of its subject without invading his jealously guarded privacy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('billy madison', 40, 'Audiences who enjoy Adam Sandler''s belligerent comic energy may find him in joyously obnoxious form as Billy Madison, but this thinly-plotted starring vehicle surrounds its star with an aggressively pedestrian movie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bird', 83, 'Forest Whitaker inhabits Charlie Parker with aplomb in this moving love letter to the music icon, told by director Clint Eastwood with a moody style that visually evokes the wistful rhythm of jazz.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('luccello dalle piume di cristallo the bird with the crystal plumage', 93, 'Combining a deadly thriller plot with the stylized violence that would become his trademark, The Bird with the Crystal Plumage marked an impressive horror debut for Dario Argento.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the birdcage', 80, 'Mike Nichols wrangles agreeably amusing performances from Robin Williams and Nathan Lane in this fun, if not quite essential, remake of the French comedy La Cage aux Folles.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('birdman', 91, 'A thrilling leap forward for director Alejandro González Iñárritu, Birdman is an ambitious technical showcase powered by a layered story and outstanding performances from Michael Keaton and Edward Norton.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('biutiful', 66, 'Javier Bardem''s searing performance helps to elevate Biutiful, as does Alejandro González Iñárritu''s craftsmanship, but the film often lapses into contrivance and grimness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the black dahlia', 32, 'Though this ambitious noir crime-drama captures the atmosphere of its era, it suffers from subpar performances, a convoluted story, and the inevitable comparisons to other, more successful films of its genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('black hawk down', 76, 'Though it''s light on character development and cultural empathy, Black Hawk Down is a visceral, pulse-pounding portrait of war, elevated by Ridley Scott''s superb technical skill.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('black panther', 96, 'Black Panther elevates superhero cinema to thrilling new heights while telling one of the MCU''s most absorbing stories -- and introducing some of its most fully realized characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('black sea', 80, 'Black Sea may not be particularly deep, but thanks to Kevin Macdonald''s judicious direction and a magnetic performance from Jude Law, it remains an efficiently well-crafted thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blade of the immortal mugen no jûnin', 86, 'Blade of the Immortal highlights Takashi Miike''s flair for balletic violence, making up what it lacks in strict originality with rich characterizations and kinetic thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blade runner', 90, 'Misunderstood when it first hit theaters, the influence of Ridley Scott''s mysterious, neo-noir Blade Runner has deepened with time. A visually remarkable, achingly human sci-fi masterpiece.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blade runner 2049', 88, 'Visually stunning and narratively satisfying, Blade Runner 2049 deepens and expands its predecessor''s story while standing as an impressive filmmaking achievement in its own right.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blades of glory', 70, 'Thanks to the spirited performances of a talented cast - particularly Will Ferrell and Jon Heder as rivals-turned-teammates -- Blades of Glory successfully spoofs inspirational sports dramas with inspired abandon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blair witch', 37, 'Blair Witch doles out a handful of effective scares, but aside from a few new twists, it mainly offers a belated rehash of the original -- and far more memorable -- first film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the blair witch project', 86, 'Full of creepy campfire scares, mock-doc The Blair Witch Project keeps audiences in the dark about its titular villain, proving once more that imagination can be as scary as anything onscreen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blame it on rio', 8, 'It isn''t clear who is most culpable for this creepy comedy''s sheer wrongness, but its smarmy laughs and uncomfortable romance will leave audiences feeling guilty long afterward.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bleed for this', 70, 'Bleed for This rises on the strength of Miles Teller''s starring performance to deliver a solid fact-based boxing drama that takes a few genre clichés on the chin but keeps on coming.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blinded by the light', 89, 'Like a life-affirming rock anthem, Blinded by the Light hits familiar chords with confidence and flair, building to a conclusion that leaves audiences cheering for an encore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blood done sign my name', 52, 'Even among civil rights movies, Blood Done Sign My Name is remarkably earnest, but its big heart can''t cover for the bland acting and TV-style melodrama that blunts the movie''s impact.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blood father', 89, 'Blood Father meets every expectation a film fan could have for a latter-day Mel Gibson action thriller with its title -- and even, in some respects, handily exceeds them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bloodsport', 40, 'This is where it all began for the Muscles from Brussels, but beyond Van Damme''s athleticism, Bloodsport is a cliched, virtually plotless exercise in action movie recycling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blow', 55, 'With elements that seem borrowed from movies like Goodfellas and Boogie Nights, Blow is pretty much been-there-done-that despite another excellent performance from Johnny Depp. It, also, becomes too sentimental at the end.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blow out', 83, 'With a story inspired by Antonioni''s Blow Up and a style informed by the high-gloss suspense of Hitchcock, DePalma''s Blow Out is raw, politically informed, and littered with film references.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blowup', 88, 'Exquisitely shot and simmering with unease, Michelangelo Antonio''s Blow-Up is an enigma that invites audiences to luxuriate in the sensual atmosphere of 1960s London chic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blue valentine', 87, 'This emotionally gripping examination of a marriage on the rocks isn''t always easy to watch, but Michelle Williams and Ryan Gosling give performances of unusual depth and power.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('blue velvet', 94, 'If audiences walk away from this subversive, surreal shocker not fully understanding the story, they might also walk away with a deeper perception of the potential of film storytelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('body of war', 80, 'Unapologetically political, this intimate and heart wrenching profile of an Iraq veteran may be rough around the edges but takes a potent stance with determination and compassion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the bonfire of the vanities', 16, 'The Bonfire of the Vanities is a vapid adaptation of a thoughtful book, fatally miscast and shorn of the source material''s crucial sense of irony. Add it to the pyre of Hollywood''s ambitious failures.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('book club', 54, 'Book Club only intermittently rises to the level of its impressive veteran cast; fortunately, they''re more than enough to bring pedestrian material entertainingly to life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('born on the fourth of july', 85, 'Led by an unforgettable performance from Tom Cruise, Born on the Fourth of July finds director Oliver Stone tackling thought-provoking subject matter with ambitious élan.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bound', 89, 'Bound''s more titillating elements attracted attention, but it''s the stylish direction, solid performances, and entertaining neo-noir caper plot that make it worth a watch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the bourne ultimatum', 92, 'The Bourne Ultimatum is an intelligent, finely tuned non-stop thrill ride. Another strong performance from Matt Damon and sharp camerawork from Paul Greengrass make this the finest installment of the Bourne trilogy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('boxcar bertha', 52, 'Too derivative of other Roger Corman crime pictures to stand out, Boxcar Bertha feels more like a training exercise for a fledgling Martin Scorsese than a fully formed picture in its own right.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('boy a', 88, 'Small in scale but large in impact, Boy A''s career making performances (particularly that by star Andrew Garfield) and carefully crafted characters defy judgment and aggressively provoke debate.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('boy and the world o menino e o mundo', 93, 'Boy and the World''s distinctive animation is visually thrilling -- and it''s backed up with a daring, refreshingly different storyline that should enthrall younger viewers while resonating deeply with adults.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bra boys', 59, 'While it looks like shameless publicity for the semi-notorious Aussie surfing gang, the film packs a raw energy into this look at a culture of athleticism and male loyalty.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bride of chucky', 46, 'Bride of Chucky is devoid of any fright and the franchise has become tiresomely self-parodic, although horror fans may find some pleasure in this fourth entry''s camp factor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bridget joness diary', 80, 'Though there was controversy over the choice of casting, Zellweger''s Bridget Jones is a sympathetic, likable, funny character, giving this romantic comedy a lot of charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bright lights starring carrie fisher and debbie reynolds', 100, 'Bright Lights: Starring Carrie Fisher and Debbie Reynolds is a touching, bittersweet, and ultimately charming love story that serves as a poignantly effective tribute to the strangely complicated, uniquely resilient mother/daughter duo.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bright young things', 65, 'Colored with witty performances and a camp sense of satire, Stephen Fry''s version of Evelyn Waugh''s novel may only be fitfully successful but it does mark a promising debut for the British comic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('brighton rock', 51, 'Brighton Rock is a lean noir boasting an appealing trio of stars, but its old-fashioned presentation only reinforces how little it distinguishes itself from the superior original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bring it on', 63, 'Despite the formulaic, fluffy storyline, this movie is surprisingly fun to watch, mostly due to its high energy and how it humorously spoofs cheerleading instead of taking itself too seriously.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('broken embraces', 81, 'Pedro Almodovar''s fourth film with Penélope Cruz isn''t his finest work, but he brings his signature visual brilliance to this noirish tale, and the cast turns in some first-class performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('brooklyn', 97, 'Brooklyn buttresses outstanding performances from Saoirse Ronan and Emory Cohen with a rich period drama that tugs at the heartstrings as deftly as it satisfies the mind.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('brooklyns finest', 45, 'It''s appropriately gritty, and soaked in the kind of palpable tension Antoine Fuqua delivers so well, but Brooklyn''s Finest suffers from the comparisons its cliched script provokes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('buffalo 66', 76, 'Self-indulgent yet intriguing, Buffalo ''66 marks an auspicious feature debut for writer-director-star Vincent Gallo while showcasing a terrific performance from Christina Ricci.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('buffy the vampire slayer', 35, 'Buffy the Vampire Slayer''s supernatural coming of age tale is let down by poor directing and even poorer plotting -- though Kristy Swanson and Paul Reubens'' game performances still manage to slay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bullet to the head', 45, 'Bullet to the Head''s unapologetically trashy thrills evoke memories of its star and director''s proud cinematic pasts -- but sadly, those memories are just about all it has to offer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bulworth', 76, 'Star and director Beatty''s ambitious take on race and politics in 20th-century America isn''t perfect, but manages to provide more than its share of thought-provoking laughs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('burlesque', 37, 'Campy and clichéd, Burlesque wastes its talented cast (including a better-than-expected Christina Aguilera) on a movie that wavers uncertainly between "bad" and "so bad it''s good."');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('bushwick', 48, 'Bushwick''s sociopolitical subtext gives it more heft than the average action thriller, but those ideas are given short shrift in what amounts to a disappointing shoot-''em-up.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('but im a cheerleader', 40, 'Too broad to make any real statements, But I''m a Cheerleader isn''t as sharp as it should be, but a charming cast and surprisingly emotional center may bring enough pep for viewers looking for a light social satire.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('byzantium', 66, 'Director Neil Jordan remains as expert as ever when it comes to setting a chilling mood, but Byzantium struggles to match its creepily alluring atmosphere with a suitably compelling story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('caddyshack ii', 4, 'Handicapped by a family friendly PG rating, even the talents of Caddyshack II''s all-star comic cast can''t save it from its lazy, laughless script and uninspired direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cake', 48, 'Cake finds Jennifer Aniston making the most of an overdue opportunity to test her dramatic chops, but it lacks sufficient depth or warmth to recommend for all but her most ardent fans.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('california suite', 54, 'Maggie Smith''s acidic turn is the standout in this stacked ensemble, but broad characterizations and an unsure tone make for a disappointingly uneven adaptation of Neil Simon''s episodic play.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cam', 93, 'Smart and suspenseful, CAM is a techno-thriller that''s far more than the sum of its salacious parts -- and an outstanding showcase for Madeline Brewer in the leading role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cameraperson', 99, 'Fresh and inventive yet immediately accessible, Cameraperson distills its subject''s life and career into an experience that should prove immediately absorbing even for those unfamiliar with her work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the candidate', 87, 'The Candidate may not get all the details right when it comes to modern campaigning, but it captures political absurdity perfectly -- and boasts typically stellar work from Robert Redford to boot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('candyman', 75, 'Though it ultimately sacrifices some mystery in the name of gory thrills, Candyman is a nuanced, effectively chilling tale that benefits from an interesting premise and some fine performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('captain america civil war', 91, 'Captain America: Civil War begins the next wave of Marvel movies with an action-packed superhero blockbuster boasting a decidedly non-cartoonish plot and the courage to explore thought-provoking themes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('captain corellis mandolin', 28, 'The cinematography is gorgeous, but the movie plays it fast and loose with history and the novel it was adapted from. Mostly, the movie fails because the romance between the leads strains credulity and the story is largely uninvolving.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('captain marvel', 79, 'Packed with action, humor, and visual thrills, Captain Marvel introduces the MCU''s latest hero with an origin story that makes effective use of the franchise''s signature formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('captain phillips', 93, 'Smart, powerfully acted, and incredibly intense, Captain Phillips offers filmgoers a Hollywood biopic done right -- and offers Tom Hanks a showcase for yet another brilliant performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('captain underpants the first epic movie captain underpants', 87, 'With a tidy plot, clean animation, and humor that fits its source material snugly, Captain Underpants: The First Epic Movie is entertainment that won''t drive a wedge between family members.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('captive', 27, 'Captive undermines committed performances from Kate Mara and David Oyelowo -- and the real-life story they''re dramatizing -- with a thin script doubling as an ad for a self-help book.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('careful what you wish for', 17, 'Audiences yearning for a modern update on the erotic thriller formula will be sorely disappointed by this turgid incarnation, hobbled by stale plotting and a curious lack of sensuality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cargo', 88, 'Cargo takes a refreshingly character-driven approach to the zombie genre that''s further distinguished by its Australian setting and Martin Freeman''s terrific lead performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('carlitos way', 81, 'Carlito''s Way reunites De Palma and Pacino for a more wistful take on the crime epic, delivering a stylish thriller with a beating heart beneath its pyrotechnic performances and set pieces.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('carnage', 70, 'It isn''t as compelling on the screen as it was on the stage, but Carnage makes up for its flaws with Polanski''s smooth direction and assured performances from Winslet and Foster.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('carrie', 50, 'It boasts a talented cast, but Kimberly Peirce''s "reimagining" of Brian De Palma''s horror classic finds little new in the Stephen King novel -- and feels woefully unnecessary.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cars 3', 70, 'Cars 3 has an unexpectedly poignant story to go with its dazzling animation, suggesting Pixar''s most middle-of-the-road franchise may have a surprising amount of tread left.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('casa de mi padre', 42, 'Thinly written and not as funny as it needs to be, Casa de mi Padre would have worked better as a fake trailer or short film; stretched to feature length, it wears out its welcome far too quickly.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('casino royale', 95, 'Casino Royale disposes of the silliness and gadgetry that plagued recent James Bond outings, and Daniel Craig delivers what fans and critics have been waiting for: a caustic, haunted, intense reinvention of 007.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('catch a fire', 75, 'No stranger to the political thriller, director Phillip Noyce tackles apartheid and terrorism with experienced gusto, while Derek Luke and Tim Robbins hand in nuanced performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('catch me if you can', 96, 'With help from a strong performance by Leonardo DiCaprio as real-life wunderkind con artist Frank Abagnale, Steven Spielberg crafts a film that''s stylish, breezily entertaining, and surprisingly sweet.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('catfish', 80, 'Catfish may tread the line between real-life drama and crass exploitation a little too unsteadily for some viewers'' tastes, but its timely premise and tightly wound mystery make for a gripping documentary.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cecil b demented', 53, 'The idea behind John Waters'' latest has much potential, but the movie ends up being too sloppy and underdeveloped in terms of script and direction. Also, by today''s standards, it fails to shock.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('celeste and jesse forever', 71, 'While it doesn''t subvert the genre as incisively as it thinks it does, Celeste and Jesse Forever is a shrewd rom-com that benefits from its likable cast and trumpets the arrival of Rashida Jones as a bona fide big screen talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cemetery junction', 55, 'It fails to challenge the well-established conventions of its storyline, but Cemetery Junction benefits from the genuine warmth of its script, as well as its refusal to give in to cheap nostalgia.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('centurion', 61, 'It''s a bloody geyser of Neil Marshall''s typically stylish B-movie action, but Centurion is too focused on hacking and slashing to deliver original dialogue or interesting characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chaplin', 59, 'Chaplin boasts a terrific performance from Robert Downey, Jr. in the title role, but it isn''t enough to overcome a formulaic biopic that pales in comparison to its subject''s classic films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chappaquiddick', 81, 'Chappaquidick can''t help leaving some of this true story''s most intriguing questions unanswered, but it''s bolstered by outstanding work from Jason Clarke in the central role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chariots of fire', 82, 'Decidedly slower and less limber than the Olympic runners at the center of its story, the film nevertheless manages to make effectively stirring use of its spiritual and patriotic themes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('charlie and the chocolate factory', 83, 'Closer to the source material than 1971''s Willy Wonka & the Chocolate Factory, Charlie and the Chocolate Factory is for people who like their Chocolate visually appealing and dark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('charlottes web', 78, 'Kids will be entertained by the straightforward plot and cute animals, and adults will be charmed by how quiet and humble the production is, a fine translation of E.B. White''s genteel prose.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chasing amy', 87, 'Although Chasing Amy''s depiction of queer sexuality is frustratingly clumsy, it handles an array of thorny themes with a mixture of sensitivity, raw honesty, and writer-director Kevin Smith''s signature raunchy humor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chasing coral', 100, 'Chasing Coral offers a breathtakingly beautiful look at some of the Earth''s most incredible natural wonders while delivering a sobering warning about their uncertain future.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chasing madoff', 46, 'Chasing Madoff admirably highlights Harry Markopolos'' perilous crusade against one of history''s biggest frauds, but the documentary''s disinterest in Madoff himself makes it feel like only half the story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chasing trane the john coltrane documentary', 76, 'Chasing Trane: The John Coltrane Documentary can''t hope to truly capture its subject''s freewheeling creative spirit, but it''s still an engaging overview for fans as well as the uninitiated.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chavela', 95, 'Chavela pays affecting tribute to its subject with an absorbing documentary that outlines her remarkable life while effectively communicating the power and lingering impact of her art.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chef flynn', 75, 'Chef Flynn might have cut a little deeper into its subject''s story, but this entertaining overview of a precocious talent''s rise to acclaim still has enough flavor to satisfy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chelsea on the rocks', 71, 'Abel Ferrara''s loving portrait of New York''s Chelsea Hotel is less interested in telling the story of its famous residents than in exploring the magic of the place that housed so many moments in rock history.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cherry 2000', 38, 'While Cherry 2000 has a certain low-budget appeal, all but the most ardent genre enthusiasts are likely to find its silly story and uneven performances unintentionally amusing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chiraq', 82, 'Chi-Raq is as urgently topical and satisfyingly ambitious as it is wildly uneven -- and it contains some of Spike Lee''s smartest, sharpest, and all-around entertaining late-period work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chicken run', 97, 'Chicken Run has all the charm of Nick Park''s Wallace & Gromit, and something for everybody. The voice acting is fabulous, the slapstick is brilliant, and the action sequences are spectacular.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('child 44', 27, 'There''s a gripping story at the heart of Child 44 and a solid performance from Tom Hardy in the lead, but it all still adds up to a would-be thriller that lacks sufficient thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('child of god', 42, 'An obviously reverent adaptation that fails to make a case for the source material being turned into a movie, Child of God finds director James Franco outmatched by Cormac McCarthy''s novel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('childs play', 71, 'Child''s Play occasionally stumbles across its tonal tightrope of comedy and horror, but its genuinely creepy monster and some deft direction by Tom Holland makes this chiller stand out on the shelf.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chinatown', 99, 'As bruised and cynical as the decade that produced it, this noir classic benefits from Robert Towne''s brilliant screenplay, director Roman Polanski''s steady hand, and wonderful performances from Jack Nicholson and Faye Dunaway.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chips', 18, 'CHiPS abandons the endearing innocence of its source material, using the titular cop show''s premise as a setup for aggressively lowbrow gags that prove only mildly arresting at best.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a chorus line', 40, 'On stage, A Chorus Line pulled back the curtain to reveal the hopes and fears of showbiz strivers, but that energy and urgency is lost in the transition to the big screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('chris rock tamborine', 100, 'Chris Rock reasserts his credentials as one of comedy''s preeminent figures in Tamborine, an introspective standup act delivered with fresh sensitivity and trademark exuberance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('christopher robin', 73, 'Christopher Robin may not equal A.A. Milne''s stories -- or their animated Disney adaptations -- but it should prove sweet enough for audiences seeking a little childhood magic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the chronicles of narnia the voyage of the dawn treader', 50, 'Its leisurely, businesslike pace won''t win the franchise many new fans, but Voyage of the Dawn Treader restores some of the Narnia franchise''s lost luster with strong performances and impressive special effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('churchill', 49, 'Churchill gets sterling work out of Brian Cox in the leading role, but it isn''t enough to overcome a muddled and ultimately unsuccessful approach to an incredible real-life story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cinema verite', 61, 'Cinema Verite is a disappointingly incurious dive into the birth of reality television, but terrific performances and the inherent intrigue behind the making of An American Family keep this drama compelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cirque du soleil worlds away', 45, 'Cirque Du Soleil loses its sense of wonder when bottled for the screen, with Worlds Away''s shapeless story and relentless spectacle feeling hollow when divorced from the theatrical experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('citizen jane battle for the city', 95, 'Citizen Jane: Battle for the City offers a compelling overview of an influential activist''s importance -- and underscores why the spirit of her work remains crucial today.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('citizen kane', 100, 'Orson Welles''s epic tale of a publishing tycoon''s rise and fall is entertaining, poignant, and inventive in its storytelling, earning its reputation as a landmark achievement in film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('city of gold', 90, 'Even for viewers who''ve never read or heard of food critic Jonathan Gold, City of Gold offers a thoroughly entertaining introduction to a talented writer and brilliant career.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('clash of the titans', 68, 'A goofy, old-school sword-and-sandal epic, Clash of the Titans mines Greek mythology for its story and fleshes it out with Ray Harryhausen''s charmingly archaic stop-motion animation techniques.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wrath of the titans', 27, 'Its 3D effects are an improvement over its predecessor''s, but in nearly every other respect, Wrath of the Titans fails to improve upon the stilted acting, wooden dialogue, and chaos-driven plot of the franchise''s first installment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('clash of the titans', 27, 'An obviously affectionate remake of the 1981 original, Louis Leterrier''s Clash of the Titans doesn''t offer enough visual thrills to offset the deficiencies of its script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('click', 34, 'This latest Adam Sandler vehicle borrows shamelessly from It''s A Wonderful Life and Back To The Future, and fails to produce the necessary laughs that would forgive such imitation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the client', 78, 'The Client may not reinvent the tenets of the legal drama, but Joel Schumacher''s sturdy directorial hand and a high-caliber cast bring John Grisham''s page-turner to life with engrossing suspense.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cloud atlas', 67, 'Its sprawling, ambitious blend of thought-provoking narrative and eye-catching visuals will prove too unwieldy for some, but the sheer size and scope of Cloud Atlas are all but impossible to ignore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('clue', 65, 'A robust ensemble of game actors elevate Clue above its schematic source material, but this farce''s reliance on novelty over organic wit makes its entertainment value a roll of the dice.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('coach carter', 64, 'Even though it''s based on a true story, Coach Carter is pretty formulaic stuff, but it''s effective and energetic, thanks to a strong central performance from Samuel L. Jackson.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('coco', 97, 'Coco''s rich visual pleasures are matched by a thoughtful narrative that takes a family-friendly -- and deeply affecting -- approach to questions of culture, family, life, and death.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cold pursuit', 69, 'Cold Pursuit delivers the action audiences expect from a Liam Neeson thriller -- along with humor and a sophisticated streak that make this an uncommonly effective remake.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the color purple', 81, 'It might have been better served by a filmmaker with a deeper connection to the source material, but The Color Purple remains a worthy, well-acted adaptation of Alice Walker''s classic novel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('colossal', 81, 'Colossal''s singular strangeness can be disorienting, but viewers who hang on may find that its genre-defying execution -- and Anne Hathaway''s performance -- is well worth the ride.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('computer chess', 88, 'With its delightfully retro production design, Computer Chess is an inventive, intelligent, and humorous comedy that celebrates the eccentricity and uniqueness of its subject.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('con air', 56, 'Con Air won''t win any awards for believability - and all involved seem cheerfully aware of it, making some of this blockbuster action outing''s biggest flaws fairly easy to forgive.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('conan the barbarian', 64, 'Though Conan may take itself too seriously for some, this adventure film about a former slave seeking vengeance is full of quotable Schwarzenegger lines and gritty action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('conan the barbarian', 25, 'While its relentless, gory violence is more faithful to the Robert E. Howard books, Conan the Barbarian forsakes three-dimensional characters, dialogue, and acting in favor of unnecessary 3D effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('concerning violence', 90, 'As confrontational as it is ultimately rewarding, Concerning Violence is a scathing indictment of past misdeeds -- and a sobering reminder of how far we still have to go.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('concussion', 59, 'Concussion lands a solid, well-acted hit on its impressively timely subject matter, even if its traditional sports drama structure is a little too safe to deserve a full-on dance in the end zone.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('confessions of a teenage drama queen', 14, 'Confessions of a Teenage Drama Queen''s superficial tendencies are unlikely to appeal to older viewers -- though its colorful candor is decidedly not intended for them in the first place.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('congo', 22, 'Mired in campy visual effects and charmless characters, Congo is a suspenseless adventure that betrays little curiosity about the scientific concepts it purports to care about.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('conquest of the planet of the apes', 50, 'Conquest of the Planet of the Apes is as angry and relevant as any of its predecessors, but budget constraints and a stale script rob this revolution of the scope it requires.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('control', 88, 'Control is a work of art, thanks to its evocative black and white cinematography and sensational performances from Sam Riley and Samantha Morton. Even those not familiar with Joy Division can still appreciate the beauty of the film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the conversation', 96, 'This tense, paranoid thriller presents Francis Ford Coppola at his finest -- and makes some remarkably advanced arguments about technology''s role in society that still resonate today.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('conviction', 67, 'Less compelling -- and more manipulative -- than it should be, Conviction benefits from its compelling true story and a pair of solid performances from Swank and Rockwell.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cookies fortune', 86, 'Robert Altman''s gift for diffuse storytelling is employed to breezily enjoyable effect in Cookie''s Fortune, a mirthful caper that layers on a generous helping of Southern charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cop land', 75, 'Cop Land matches its star-studded cast with richly imagined characters while throttling the audience with carefully ratcheted suspense, although it lacks the moral complexity of classic crime thrillers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cosmopolis', 65, 'Though some may find it cold and didactic, Cosmopolis benefits from David Cronenberg''s precise direction, resulting in a psychologically complex adaptation of Don DeLillo''s novel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('courage under fire', 85, 'An emotional and intriguing tale of a military officer who must review the merits of a fallen officer while confronting his own war demons. Effectively depicts the terrors of war as well as its heartbreaking aftermath.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cowboys aliens', 44, 'Daniel Craig and Harrison Ford are as dependably appealing as ever, but they''re let down by director Jon Favreau''s inability to smooth Cowboys & Aliens'' jarring tonal shifts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crank', 61, 'Crank''s assaultive style and gleeful depravity may turn off casual action fans, but audiences seeking a strong dose of adrenaline will be thrilled by Jason Statham''s raucous race against mortality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crawl', 83, 'An action-packed creature feature that''s fast, terrifying, and benefits greatly from a completely game Kaya Scodelario, Crawl is a fun throw-back with just enough self-awareness to work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crazy rich asians', 91, 'With a terrific cast and a surfeit of visual razzle dazzle, Crazy Rich Asians takes a satisfying step forward for screen representation while deftly drawing inspiration from the classic -- and still effective -- rom-com formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('creed', 95, 'Creed brings the Rocky franchise off the mat for a surprisingly effective seventh round that extends the boxer''s saga in interesting new directions while staying true to its classic predecessors'' roots.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('creepshow 2', 30, 'Not even the melding of Stephen King and George A. Romero''s writing sensibilities can elevate this spineless anthology, which is too simple in its storytelling and too skimpy on the genuine scares.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crimson peak', 72, 'Crimson Peak offers an engaging -- albeit somewhat slight -- diversion driven by a delightfully creepy atmosphere and director Guillermo del Toro''s brilliant knack for unforgettable visuals.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crimson tide', 88, 'Boasting taut, high energy thrills and some cracking dialogue courtesy of an uncredited Quentin Tarantino, Crimson Tide finds director Tony Scott near the top of his action game.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crossing over', 16, 'Crossing Over is flagrant and heavy-handed about a situation that deserves more deliberate treatment, and joins its characters with coincidences that strain believability.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crossing the line', 90, 'An engrossing look at the aftermath of largely forgotten events during the Cold War, Crossing the Line raises questions that will haunt the viewer after the credits roll.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crouching tiger hidden dragon', 97, 'The movie that catapulted Ang Lee into the ranks of upper echelon Hollywood filmmakers, Crouching Tiger, Hidden Dragon features a deft mix of amazing martial arts battles, beautiful scenery, and tasteful drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cruising', 50, 'Cruising glides along confidently thanks to filmmaking craft and Al Pacino''s committed performance, but this hot-button thriller struggles to engage its subject matter sensitively or justify its brutality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crumb', 95, 'Crumb is a frank and surreal chronicle of artistic expression and family trauma, offering an unblinking gaze into the mind and work of cartoonist Robert Crumb that will endear as much as it unsettles.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crybaby', 73, 'John Waters'' musical ode to the teen rebel genre is infectious and gleefully camp, providing star Johnny Depp with the perfect vehicle in which to lampoon his pin-up image.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('crystal fairy', 83, 'Slight and unpolished, The Crystal Fairy is held together with Sebastian Silva''s assured direction and a pair of strong, committed performances from Michael Cera and Gaby Hoffman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('csa the confederate states of america', 80, 'Through the eyes of a British "documentary", this film takes a satirically humorous, and sometimes frightening, look at the history of an America where the South won the Civil War.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the curse of the cat people', 87, 'Foregoing the horror thrills of its predecessor in favor of childhood fantasy, Curse of the Cat People is a touching and psychologically complex family film couched in a ghost story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('curse of the golden flower', 65, 'Melodrama, swordplay, and CG armies -- fans of martial arts epic will get what they bargain for, though the baroque art direction can be both mesmerizing and exhaustively excessive.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cutters way', 91, 'A suitably cynical neo-noir that echoes the disillusionment of its era, Cutter''s Way relies on character-driven drama further elevated by the work of an outstanding cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('cutthroat island', 38, 'Cutthroat Island may aspire towards the earnest thrills of classic swashbucklers, but a distinct lack of charm and stilted script make this adventure a joyless hodgepodge of the pirate genre''s flotsam and jetsam.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('daddys home', 31, 'Will Ferrell and Mark Wahlberg have proven comedic chemistry, but Daddy''s Home suffers from a dearth of genuinely funny ideas - and lacks enough guts or imagination to explore the satirical possibilities of its premise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('damsel', 67, 'The beautifully filmed Damsel injects the western genre with a welcome dose of humor and some unexpected twists, although its stately pace may frustrate impatient viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('damsels in distress', 75, 'Damsels in Distress can sometimes feel mannered and outlandish, but it''s redeemed by director Whit Stillman''s oddball cleverness and Greta Gerwig''s dryly funny performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the dancer upstairs', 64, 'The Dancer Upstairs benefits from a talented cast and alluring intelligence, although pacing problems prevent this John Malkovich-directed mystery from reaching its full potential.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dances with wolves', 83, 'Dances with Wolves suffers from a simplistic view of the culture it attempts to honor, but the end result remains a stirring western whose noble intentions are often matched by its epic grandeur.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('danny collins', 77, 'Thanks to Al Pacino''s stirring central performance - and excellent work from an esteemed supporting cast -- Danny Collins manages to overcome its more predictable and heavy-handed moments to deliver a heartfelt tale of redemption.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('danny deckchair', 55, 'Danny Deckchair mines some earnest pleasure from a concept with its head in the clouds and two stars whose chemistry is grounded, but the comedy quickly runs out of air when the premise comes back down to the earth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('daredevil', 44, 'While Ben Affleck fits the role and the story is sporadically interesting, Daredevil is ultimately a dull, brooding origin story that fails to bring anything new to the genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dark shadows', 36, 'The visuals are top notch but Tim Burton never finds a consistent rhythm, mixing campy jokes and gothic spookiness with less success than other Johnny Depp collaborations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the dark crystal', 79, 'The Dark Crystal''s narrative never quite lives up to the movie''s visual splendor, but it remains an admirably inventive and uniquely intense entry in the Jim Henson canon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dark skies', 41, 'Dark Skies writer director Scott Stewart has a solid cast, an interesting premise, and some admirable ambitions, but he can''t figure out what to do with any of them, and the result is a dull, muddled effort that will bore all but the most devoted horror buffs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('darkman', 84, 'Gruesome and deliciously broad, Sam Raimi''s Darkman bears the haunted soulfulness of gothic tragedy while packing the stylistic verve of onomatopoeia springing off a comic strip page.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('date night', 66, 'An uneasy blend of action and comedy, Date Night doesn''t quite live up to the talents of its two leads, but Steve Carell and Tina Fey still manage to shine through most of the movie''s flaws.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('daughters of the dust', 98, 'Daughters of the Dust addresses its weighty themes with lovely visuals and a light, poetic touch, offering an original, absorbing look at a largely unexplored corner of American culture.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dawn of the planet of the apes', 90, 'With intelligence and emotional resonance to match its stunning special effects, Dawn of the Planet of the Apes expands on its predecessor with an exciting and ambitious burst of sci-fi achievement.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('daybreakers', 69, 'Though it arrives during an unfortunate glut of vampire movies, Daybreakers offers enough dark sci-fi thrills -- and enough of a unique twist on the genre -- to satisfy filmgoers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('daylight', 27, 'The opening''s got a great fiery explosion and Stallone puts in another earnest, sympathetic performance, but all else in Daylight feels designed to annoy the audience into submission.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('days of thunder', 38, 'Days of Thunder has Tom Cruise and plenty of flash going for it, but they aren''t enough to compensate for the stock plot, two-dimensional characters, and poorly written dialogue.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the daytrippers', 73, 'Its modest scale and scabrous sense of humor may feel more punishing than funny for some, but an excellent cast and authentic sense of place make The Daytrippers a smooth ride.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dazed and confused', 92, 'Featuring an excellent ensemble cast, a precise feel for the 1970s, and a killer soundtrack, Dazed and Confused is a funny, affectionate, and clear-eyed look at high school life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dead man running', 14, 'Poor performances, stiff dialogue, flat characters, and an unimaginative stab at the mood of the Guy Ritchie crime caper make Dead Man Running into a hooligan tale with little to offer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dead alive', 88, 'The delightfully gonzo tale of a lovestruck teen and his zombified mother, Dead Alive is extremely gory and exceedingly good fun, thanks to Peter Jackson''s affection for the tastelessly sublime.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dead man', 71, 'While decidedly not for all tastes, Dead Man marks an alluring change of pace for writer-director Jim Jarmusch that demonstrates an assured command of challenging material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dead men dont wear plaid', 79, 'Dead Men Don''t Wear Plaid is more eleaborate pastiche than uproarious comedy, but the farce works thanks to the sly lampooning of Hollywood noir and Steve Martin''s performance as a goofy gumshoe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('deadpool', 85, 'Fast, funny, and gleefully profane, the fourth-wall-busting Deadpool subverts superhero film formula with wildly entertaining -- and decidedly non-family-friendly -- results.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dear john', 29, 'Built from many of the same ingredients as other Nicholas Sparks tearjerkers, Dear John suffers from its cliched framework, as well as Lasse Hallstrom''s curiously detached directing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dear wendy', 36, 'A film with numerous ideas but little grasp of how to effectively communicate them, Dear Wendy lacks the intelligence or insight that its difficult subject matter demands.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dear white people', 91, 'Dear White People adds a welcome new voice to cinema''s oft-neglected discussion of race, tackling its timely themes with intelligence, honesty, and gratifyingly sharp wit.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('death proof', 64, 'Death Proof may feel somewhat minor in the context of Tarantino''s larger filmography, but on its own merits, it packs just enough of a wallop to deliver sufficiently high-octane grindhouse goods.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('deep red profondo rosso', 96, 'The kinetic camerawork and brutal over-the-top gore that made Dario Argento famous is on full display, but the addition of a compelling, complex story makes Deep Red a masterpiece.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('déjà vu', 56, 'Tony Scott tries to combine action, science fiction, romance, and explosions into one movie, but the time travel conceit might be too preposterous and the action falls apart under scrutiny.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('deliver us from evil', 100, 'Deliver Us From Evil is a superb documentary and a searing look at an institution protecting its leaders at the expense of its followers. A profoundly disturbing chronicle of a wolf in sheep''s clothing, the film builds a clear-eyed case against pedophile priest Oliver O''Grady, and the Catholic bureaucracy that protected him. The recollections of O''Grady''s victims are nothing short of shocking and heartbreaking.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('deliver us from evil', 29, 'Director Scott Derrickson continues to have a reliably firm grasp on creepy atmosphere, but Deliver Us from Evil''s lack of original scares is reflected in its shopworn title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('delivery man', 39, 'It has an undeniably sweet charm, and Vince Vaughn is eminently likable in the lead role, but The Delivery Man suffers in comparison to Starbuck, the hit Canadian comedy that inspired it.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('demolition', 53, 'Demolition benefits from a stellar cast, even if their solid work isn''t always enough to prop up a confused story that aims for profundity but too often settles for clichés.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('demolition man', 60, 'A better-than-average sci-fi shoot-em-up with a satirical undercurrent, Demolition Man is bolstered by strong performances by Sylvester Stallone, Wesley Snipes, and Sandra Bullock.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('denial', 82, 'If Denial doesn''t quite do its incredible story complete justice, it comes close enough to offer a satisfying, impactful drama -- and another powerful performance from Rachel Weisz.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the departed', 91, 'Featuring outstanding work from an excellent cast, The Departed is a thoroughly engrossing gangster drama with the gritty authenticity and soupy morality we come to expect from Martin Scorsese.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('detention', 41, 'Director Joseph Kahn''s relentlessly kinetic style gives Detention a rebellious kick, but the overload of ideas keeps this genre mashup from ever cohering into a satisfying whole.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('devil', 50, 'It''s better than many of the other films M. Night Shyamalan has been associated with, but Devil never gets more than a few low-budget thrills out of its fiendishly promising premise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dial m for murder', 89, 'Dial M for Murder may be slightly off-peak Hitchcock, but by any other standard, it''s a sophisticated, chillingly sinister thriller -- and one that boasts an unforgettable performance from Grace Kelly to boot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('diamonds are forever', 64, 'Diamonds are Forever is a largely derivative affair, but it''s still pretty entertaining nonetheless, thanks to great stunts, witty dialogue, and the presence of Sean Connery.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('diary of a wimpy kid', 54, 'Unlike its bestselling source material, Diary of a Wimpy Kid fails to place a likable protagonist at the center of its middle-school humor -- and its underlying message is drowned out as a result.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('diary of a wimpy kid dog days', 52, 'Overly familiar and a bit too reliant on slapstick, the sitcom-like Dog Days fails to improve upon previous installments and will likely appeal to few outside its target audience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('die another day', 57, 'Its action may be bit too over-the-top for some, but Die Another Day is lavishly crafted and succeeds in evoking classic Bond themes from the franchise''s earlier installments.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('die hard 2', 69, 'It lacks the fresh thrills of its predecessor, but Die Hard 2 still works as an over-the-top -- and reasonably taut -- big-budget sequel, with plenty of set pieces to paper over the plot deficiencies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('die hard with a vengeance', 59, 'Die Hard with a Vengeance benefits from Bruce Willis and Samuel L. Jackson''s barbed interplay, but clatters to a bombastic finish in a vain effort to cover for an overall lack of fresh ideas.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('die wand the wall', 78, 'Die Wand (The Wall) preserves its source material''s thought-provoking themes -- and serves as a brilliant showcase for Martina Gedeck, whose performance carries the film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dig', 89, 'So you wanna be a rock ''n'' roll star? Dig! compellingly chronicles the ups and downs of the Dandy Warhols and the Brian Jonestown Massacre, two ambitious bands whose love/hate relationship embodies many of the potential pratfalls of the music business.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('diner', 93, 'Diner transports audiences back to the 1950s with a refreshing lack of sentimentality, evoking the thrill of everyday life with its ensemble''s potent chemistry and an authentic sense of spontaneity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a dirty shame', 53, 'John Waters casts his provocative eye toward libido in a sex satire that won''t leave audiences feeling too Dirty, but this sophomoric farce doesn''t strike a nerve like his best work -- a real Shame.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dirty wars', 85, 'Some viewers may find fault with director Rick Rowley''s filmmaking methods, but they aren''t distracting enough to keep Dirty Wars from serving as a terribly compelling argument against elements of American foreign policy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('disaster movie', 1, 'Returning to their seemingly bottomless well of flatulence humor, racial stereotypes, and stale pop culture gags, Jason Friedberg and Aaron Seltzer have produced what is arguably their worst Movie yet.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('disorder maryland', 72, 'Well-acted and solidly crafted, Disorder (Maryland) relies on patiently established slow-burning tension to set the stage for an intelligent, intimate psychological thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('william kunstler disturbing the universe', 79, 'It doesn''t even feign impartiality, but this family-made documentary about the famously rabble-rousing attorney shines a light on the life and times of a divisive public figure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dixie chicks shut up and sing', 89, 'Though ostensibly an intimate look at the Dixie Chicks after their 2003 anti-Bush remark, the film achieves broader relevance by exploring how media, politics, and celebrities intertwine.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('do the right thing', 93, 'Smart, vibrant, and urgent without being didactic, Do the Right Thing is one of Spike Lee''s most fully realized efforts -- and one of the most important films of the 1980s.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('doc hollywood', 68, 'Doc Hollywood isn''t particularly graceful in its attempt to put a ''90s spin on its Capraesque formula, but a light touch and a charming cast make its flaws easy to forgive.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('doctor strange', 89, 'Doctor Strange artfully balances its outré source material against the blockbuster constraints of the MCU, delivering a thoroughly entertaining superhero origin story in the bargain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dog day afternoon', 96, 'Framed by great work from director Sidney Lumet and fueled by a gripping performance from Al Pacino, Dog Day Afternoon offers a finely detailed snapshot of people in crisis with tension-soaked drama shaded in black humor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dog days', 63, 'Dog Days is frivolous but frothy, sporting a forgettable cast of human characters but a lovable troupe of pooches that ought to delight viewers looking for a gentle affirmation of humanity''s bond with their furry friends.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dog soldiers', 79, 'Frightening, funny, and packed with action, Dog Soldiers is well worth checking out for genre fans -- and marks writer-director Neil Marshall as a talent to keep an eye on.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dom hemingway', 56, 'Jude Law is clearly having fun in Dom Hemingway''s title role, but viewers may find this purposely abrasive gangster dramedy isn''t quite as enjoyable from the other side of the screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dominion prequel to the exorcist', 30, 'While director Schrader''s attempt at a literate, internal exposition on evil temptations and human sin is admirable, this prequel suffers from hit-and-miss psychological tension, poor visual effects, and weak writing -- an overambitious failure of a horror movie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('don mckay', 38, 'Thomas Haden Church and Elisabeth Shue do their best with what they''re given, but Don McKay is too confused and far-fetched to be taken seriously as a noir, and too inconsistent to work as a black comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('donnie darko', 86, 'Richard Kelly''s debut feature Donnie Darko is a daring, original vision, packed with jarring ideas and intelligence and featuring a remarkable performance from Jake Gyllenhaal as the troubled title character.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dont breathe', 88, 'Don''t Breathe smartly twists its sturdy premise to offer a satisfyingly tense, chilling addition to the home invasion genre that''s all the more effective for its simplicity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dont think twice', 98, 'Don''t Think Twice offers a bittersweet look at the comedian''s life that''s as genuinely moving as it is laugh-out-loud funny -- and a brilliant calling card for writer-director Mike Birbiglia.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dont worry he wont get far on foot', 76, 'Don''t Worry, He Won''t Get Far on Foot avoids inspirational biopic clichés thanks to sensitive work from writer-director Gus Van Sant and the admirable efforts of a well-chosen cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the doors', 57, 'Val Kilmer delivers a powerhouse performance as one of rock''s most incendiary figures, but unfortunately, Oliver Stone is unable to shed much light on the circus surrounding the star.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dope', 89, 'Featuring a starmaking performance from Shameik Moore and a refreshingly original point of view from writer-director Rick Famuyiwa, Dope is smart, insightful entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dormant beauty', 80, 'As complex and compelling a work as its ripped-from-the-headlines storyline deserves, Dormant Beauty serves as a delightfully thorny testament to director Marco Bellocchio and his talented cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('double indemnity', 97, 'A dark, tautly constructed adaptation of James M. Cain''s novel -- penned by Billy Wilder and Raymond Chandler -- Double Indemnity continues to set the standard for the best in Hollywood film noir.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('la double vie de véronique the double life of veronique', 82, 'Operating on confounding dream logic with Irene Jacob''s beautiful performance as a guide, The Double Life of Veronique offers a moving meditation on perception for audiences willing to indulge its inscrutability.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('down and out in beverly hills', 79, 'An enjoyable farce that relocates Jean Renoir''s Boudu Saved From Drowning to ''80s California, offering fine comedic performances from Nick Nolte, Richard Dreyfuss and Bette Midler.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('down in the valley', 52, 'The premise of Old West clashing with modern suburbia is fresh and initially intriguing, but the second act degenerates into a clumsy jumble of events which strain credibility.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('downsizing', 46, 'Downsizing assembles a talented cast in pursuit of some truly interesting ideas -- which may be enough for some audiences to forgive the final product''s frustrating shortcomings.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dr dolittle', 42, 'Doctor Dolittle finds some mirth in the novelty of wisecracking critters, but this family feature''s treacly tone is made queasy by a reliance on scatological gags that undercut the intended warmth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dr t and the women', 57, 'In terms of quality, Dr. T and the Women is one of Altman''s good-but-not-great films. In typical Altman style, it features some great ensemble acting, including a wonderful performance by Richard Gere.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('draft day', 59, 'It''s perfectly pleasant for sports buffs and Costner fans, but overall, Draft Day lives down to its title by relying too heavily on the sort of by-the-numbers storytelling that only a statistician could love.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dragon the bruce lee story', 71, 'While its impact is blunted by an overly reverential approach to its subject, Dragon: The Bruce Lee Story remains a reasonably entertaining biopic of the martial arts legend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dragonheart', 50, 'Dragonheart gives us medieval action, a splendidly mulleted Dennis Quaid, and Sean Connery as a talking dragon -- and, unfortunately, a story that largely fails to engage.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dreams', 65, 'This late-career anthology by Akira Kurosawa often confirms that Dreams are more interesting to the dreamer than their audience, but the directorial master still delivers opulent visions with a generous dose of heart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dredd', 79, 'Fueled by bombastic violence and impressive special effects, rooted in self-satire and deadpan humor, Dredd 3D does a remarkable job of capturing its source material''s gritty spirit.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('drowning mona', 29, 'A whodunnit that stacks its lists of suspects with wasted character actors, Drowning Mona is a twee farce that will prompt audiences to tune out before the mystery is solved.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('drunk stoned brilliant dead the story of the national lampoon', 88, 'Drunk Stoned Brilliant Dead might not be the definitive doc National Lampoon fans are waiting for, but it''s still almost as transgressively funny as the magazine in its heyday.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('duck you sucker a fistful of dynamite giù la testa', 92, 'Duck, You Sucker is a saucy helping of spaghetti western, with James Coburn and Rod Steiger''s chemistry igniting the screen and Sergio Leone''s bravura style on full display.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the duellists', 92, 'Rich, stylized visuals work with effective performances in Ridley Scott''s take on Joseph Conrad''s Napoleonic story, resulting in an impressive feature film debut for the director.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dumb and dumber to', 30, 'Dumb and Dumber To does have its moments, but not enough of them -- and the Farrelly brothers'' brand of humor is nowhere near as refreshingly transgressive as it once seemed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dungeons dragons', 10, 'Critics say this movie has a cheap look and is badly directed. Despite the presence of talented actors, the performances are really bad, and additionally, some people are offended at Marlon Wayans'' character, calling it a racist throwback to black stereotypes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('dunkirk', 92, 'Dunkirk serves up emotionally satisfying spectacle, delivered by a writer-director in full command of his craft and brought to life by a gifted ensemble cast that honors the fact-based story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('early man', 80, 'Early Man isn''t quite as evolved as Aardman''s best work, but still retains the unique visuals and sweet humor that have made the studio a favorite among animation enthusiasts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('easier with practice', 88, 'This promising debut from writer-director Kyle Patrick Alvarez is anchored by a startlingly honest and tender performance from Brian Geraghty that helps make Easier with Practice more than just another road trip drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('eastern boys', 89, 'Thoughtful, unpredictable, and overall gripping, Eastern Boys fills its sprawling running time with compelling themes and sharply drawn characters brought to life by powerful performances and deft direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('eastern promises', 89, 'David Cronenberg triumphs again, showcasing the Viggo Mortensen''s onscreen prowess in a daring performance. Bearing the trademarks of psychological drama and gritty violence, Eastern Promises is a very compelling crime story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('eat drink man woman yin shi nan nu', 88, 'A richly layered look at the complex interactions between a widowed chef and his daughters, Ang Lee''s generational comedy Eat Drink Man Woman offers filmgoers a tasty cinematic treat.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('eat pray love', 36, 'The scenery is nice to look at, and Julia Roberts is as luminous as ever, but without the spiritual and emotional weight of the book that inspired it, Eat Pray Love is too shallow to resonate.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('edtv', 64, 'If it''s not as ambitious as The Truman Show in satirizing the voyeuristic nature of television, EdTV is an amiable, witty comedy with fine performances from Matthew McConaughey and Woody Harrelson.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('eighth grade', 99, 'Eighth Grade takes a look at its titular time period that offers a rare and resounding ring of truth while heralding breakthroughs for writer-director Bo Burnham and captivating star Elsie Fisher.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('elaine stritch shoot me', 99, 'Brutally honest and utterly compelling, Elaine Stritch: Shoot Me offers a riveting, vanity-free portrait of its legendary subject while offering a few essential truths about the human condition.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('electric boogaloo the wild untold story of cannon films', 91, 'Electric Boogaloo: The Wild, Untold Story of Cannon Films pays tribute to the titular studio with an affectionate look back that''s arguably more entertaining than much of Cannon''s own B-movie product.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('elevator to the gallows ascenseur pour léchafaud', 93, 'Louis Malle''s hypnotic debut is a noir with genuine soul, infusing its tale of best laid plans gone awry with wistful performances, swooning cinematography, and a sultry soundtrack.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('elf', 84, 'A movie full of Yuletide cheer, Elf is a spirited, good-natured family comedy, and it benefits greatly from Will Ferrell''s funny and charming performance as one of Santa''s biggest helpers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ellie parker', 51, 'Despite some poignant commentary about struggling actors and Naomi Watts'' inspired performance, Ellie Parker stutters in making the transition from short to feature length.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('emma', 87, 'Other adaptations may do a better job of consistently capturing the spirit of the classic source material, but Jane Austen fans should still find a solid match in this Emma.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('emperor', 32, 'Despite a typically strong performance from Tommy Lee Jones, Emperor does little with its fascinating historical palate, and is instead bogged down in a cliched romantic subplot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star wars episode v the empire strikes back', 94, 'Dark, sinister, but ultimately even more involving than A New Hope, The Empire Strikes Back defies viewer expectations and takes the series to heightened emotional levels.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('enchanted april', 84, 'Mike Newell''s adaptation of Elizabeth von Arnim''s moves at a more generous pace than the 1935 version, allowing excellent performances from Miranda Richardson and Joan Plowright to flourish.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('encino man', 15, 'Encino Man isn''t the first unabashedly silly comedy to embrace its stupidity and amass a cult following, but whether or not it works for you will largely be determined by your tolerance for Pauly Shore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('end of the century the story of the ramones', 95, 'Gabba gabba hey! With its focus on the groundbreaking work of the 1970s punk band The Ramones End of the Century makes a solid entry into the growing canon of documentaries that capture Punkology.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('enduring love', 59, 'While it strains credibility and isn''t ultimately as profound as it might first appear, Enduring Love is still an intriguing thriller fueled by strong performances from Rhys Ifans and Daniel Craig.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('enemy mine', 63, 'Enemy Mine extracts thrilling sci-fi pulp from Dennis Quaid and Louis Gossett Jr.''s chemistry and inventive production design, but an overextended story diminishes the power of its central duo''s relationship.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('enter the void soudain le vide', 72, 'Grimy and psychedelic, Enter the Void ushers audiences through an out-of-body experience with the eye for extremity and technical wizardry that Gaspar Noé fans have come to expect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('entertainment', 83, 'As brilliantly and uncomfortably confrontational as its protagonist, Entertainment is a boundary-blurring exercise in cinematic misanthropy that more than lives up to its title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('equalizer 2', 52, 'The Equalizer 2 delivers the visceral charge of a standard vigilante thriller, but this reunion of trusted talents ultimately proves a disappointing case study in diminishing returns.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('erin brockovich', 84, 'Taking full advantage of Julia Roberts''s considerable talent and appeal, Erin Brockovich overcomes a few character and plot issues to deliver a smart, thoughtful, and funny legal drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('escape plan', 50, 'As much fun as it is to see Sylvester Stallone and Arnold Schwarzenegger team up onscreen, Escape Plan fails to offer much more than a pale imitation of 1980s popcorn thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('et the extraterrestrial', 98, 'Playing as both an exciting sci-fi adventure and a remarkable portrait of childhood, Steven Spielberg''s touching tale of a homesick alien remains a piece of movie magic for young and old.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('eternal sunshine of the spotless mind', 93, 'Propelled by Charlie Kaufman''s smart, imaginative script and Michel Gondry''s equally daring directorial touch, Eternal Sunshine is a twisty yet heartfelt look at relationships and heartache.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('event horizon', 28, 'Despite a strong opening that promises sci-fi thrills, Event Horizon quickly devolves into an exercise of style over substance whose flashy effects and gratuitous gore fail to mask its overreliance on horror clichés.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('everest', 73, 'Everest boasts all the dizzying cinematography a person could hope to get out a movie about mountain climbers, even if it''s content to tread less challenging narrative terrain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('every which way but loose', 37, 'The inexplicable pairing of Clint Eastwood with an orangutan is the least of Every Which Way But Loose''s problems -- a slack action-comedy with a haphazardly assembled story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('everybody wants some', 87, 'Nostalgic in the best sense, Everybody Wants Some!! finds Richard Linklater ambling through the past with a talented cast, a sweetly meandering story, and a killer classic rock soundtrack.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('everybodys famous', 55, 'Though some critics consider Everybody Famous too lightweight to have deserved a slot among the Academy Awards foreign film nominations, this whacky satire of the cult of celebrity makes for loopy, cheerful fun.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('everyday', 74, 'It suffers from pacing problems and an uneven screenplay, but Michael Winterbottom''s Everyday is also a refreshingly unorthodox and admirably naturalistic take on one family''s struggle to stay together.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('everyones hero', 42, 'Everyone''s Hero is such a predictable and bland tale that it''ll appeal mostly to little kids; others seeking something in Pixar''s league are looking in the wrong ballpark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('everything must go', 73, 'It may not improve on the Raymond Carver short story that inspired it, but Everything Must Go resists cliche and boasts a pair of magnetic performances from the perfectly cast Ferrell and Wallace.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('eves bayou', 82, 'Eve''s Bayou marks a striking feature debut for director Kasi Lemmons, layering terrific performances and Southern mysticism into a measured meditation on disillusionment and forgiveness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('exhibition', 84, 'Exhibition flouts convention with its untrained stars and impressionistic narrative; thankfully, writer-director Joanna Hogg ties it all together into an intimate, beautifully shot drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fong juk exiled', 80, 'Exiled has non-stop action, tension and style -- making it an excellent summer action movie. Johnnie To brings beautiful scenery and camerawork to the film, enhancing the action even more.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the exploding girl', 76, 'Its languid pace and willfully understated narrative may test the patience of some viewers, but Bradley Rust Gray''s gentle direction and a gripping performance from Zoe Kazan lend The Exploding Girl an appealing, melancholy beauty.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('explorers', 77, 'With a terrific young cast (including Ethan Hawke and River Phoenix) and some typically energetic work from director Joe Dante, Explorers soars past its ''80s kiddie flick competitors with wit, good-looking effects, and tons of charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('exposed', 8, 'Exposed lays its flaws fittingly bare for all but the least discerning viewers to see, starting with a dull yet convoluted plot that utterly overpowers the efforts of an intriguing cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('faceoff', 92, 'John Travolta and Nicolas Cage play cat-and-mouse (and literally play each other) against a beautifully stylized backdrop of typically elegant, over-the-top John Woo violence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('faces', 83, 'Director John Cassavetes forgoes conventional style in this hard-bitten examination of a marriage, letting his actors tell the story through dialogue and their Faces to refreshing effect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('facing windows', 63, 'Polished and sensitively performed, Facing Windows is an unwieldy melodrama that is carried off with style even as its dueling storylines struggle to cohere into a satisfying whole.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fair game', 79, 'It struggles with the balance between fact-based biopic and taut political thriller, but Fair Game brims with righteous anger -- and benefits from superb performances by Naomi Watts and Sean Penn.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('falling down', 73, 'Falling Down''s popcorn-friendly take on its complex themes proves disquieting -- and ultimately fitting for a bleakly entertaining picture of one man''s angry break with reality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the family man', 53, 'Despite good performances by Cage and especially by Leoni, The Family Man is too predictable and derivative to add anything new to the Christmas genre. Also, it sinks under its sentimentality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fanny alexander', 100, 'Ingmar Bergman conveys the sweep of childhood with a fastidious attention to detail and sumptuous insight into human frailty in Fanny & Alexander, a masterwork that crystalizes many of the directors'' preoccupations into a familial epic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fantastic four', 9, 'Dull and downbeat, this Fantastic Four proves a woefully misguided attempt to translate a classic comic series without the humor, joy, or colorful thrills that made it great.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fantastic four rise of the silver surfer', 37, 'While an improvement on its predecessor, Fantastic Four: Rise of the Silver Surfer is nevertheless a juvenile, simplistic picture that has little benefit beyond its special effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('far from the madding crowd', 84, 'Far from the Madding Crowd invites tough comparisons to Thomas Hardy''s classic novel -- and its previous adaptation -- but stands on its own thanks to strong direction and a talented cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fast cheap out of control', 91, 'Made with a care and patience that belies its title, Errol Morris'' Fast, Cheap & Out of Control combines the disparate sensibilities of four idiosyncratic subjects to present a fresh, cogent perspective on life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fast food nation', 50, 'Despite some fine performances and memorable scenes, Fast Food Nation is more effective as Eric Schlosser''s eye-opening non-fiction book than as Richard Linklater''s fictionalized, mostly punchless movie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fast times at ridgemont high', 76, 'While Fast Times at Ridgemont High features Sean Penn''s legendary performance, the film endures because it accurately captured the small details of school, work, and teenage life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('favela rising', 67, 'Frustratingly flawed yet ultimately uplifting, Favela Rising offers an engrossing -- and sobering -- glimpse of a culture that''s far more complex than many viewers might realize.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('angst essen seele auf ali fear eats the soul', 100, 'Regarded as one of the high-water marks in German New Wave cinema of the 1970s, Ali: Fear Eats the Soul is at once an intense portrayal of a relationship and a tribute to one of Rainer Werner Fassbinder''s film heroes, Douglas Sirk.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fear strikes out', 83, 'Based on the true story of troubled baseball star Jimmy Piersall, Fear Strikes Out is an emotionally compelling drama featuring excellent performances from Anthony Perkins and Karl Malden.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fear x', 58, 'As hazy, unsettling, and fleetingly insubstantial as a dream, Fear X will lose many viewers in its ambiguities, but is partly propped up by strong work from John Turturro.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fences', 92, 'From its reunited Broadway stars to its screenplay, the solidly crafted Fences finds its Pulitzer-winning source material fundamentally unchanged -- and still just as powerful.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ferdinand', 72, 'Ferdinand''s colorful update on a classic tale doesn''t go anywhere unexpected, but its timeless themes -- and John Cena''s engaging voice work in the title role -- make for family-friendly fun.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('festival express', 96, 'Festival Express is a spellbinding documentary that nostalgically chronicles five days in the summer of 1970, when a train full of now- legendary rock perfomers jammed its way across Canada.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a few good men', 83, 'An old-fashioned courtroom drama with a contemporary edge, A Few Good Men succeeds on the strength of its stars, with Tom Cruise, Demi Moore, and especially Jack Nicholson delivering powerful performances that more than compensate for the predictable plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fierce people', 24, 'Fierce People''s premise of a teenager studying rich people like animals is grating and self-satisfied, and Anton Yelchin''s smug performance makes the film even harder to agree with.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fifty shades of black', 7, 'Wildly erratic even for a spoof movie, Fifty Shades of Black bears the unfortunate distinction of offering fewer laughs than the unintentionally funny film it''s trying to lampoon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a film unfinished', 97, 'A heartbreaking, haunting historical document, A Film Unfinished excavates particularly horrible chapter of Holocaust history, and in doing so, the film provides a glimpse into the Nazi propaganda machine.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('final portrait', 73, 'Final Portrait finds writer-director Stanley Tucci patiently telling a quietly absorbing story, brought to life by a talented ensemble led by Geoffrey Rush and Armie Hammer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('finding forrester', 74, 'Despite the predictability of its plot and its similarity to Good Will Hunting, Finding Forrester has an honest, solid feel to it and good rapport between Connery and Brown.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('finding neverland', 83, 'It won''t pass muster for those looking for historical accuracy, but Finding Neverland is a warm, heartfelt drama with a charm all its own -- and Johnny Depp gives a graceful performance as Peter Pan creator J.M. Barrie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('first blood', 85, 'Much darker and more sensitive than the sequels it spawned, First Blood is a thrilling survival adventure that takes full advantage of Sylvester Stallone''s acting skills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('first knight', 43, 'This unimaginative reimagining of Arthurian legend dispenses with the magic without achieving a convincing realism in the bargain, suffering from fatal miscasting and a lack of romance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('first love hatsukoi', 97, 'First Love''s blend of violence, comedy, and romance might seem disparate -- but for director Takashi Miike, it''s just another wildly entertaining entry in a filmography full of them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('first reformed', 93, 'Brought to life by delicate work from writer-director Paul Schrader and elevated by a standout performance by Ethan Hawke, First Reformed takes a sensitive and suspenseful look at weighty themes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('first they killed my father', 87, 'First They Killed My Father tackles its subject matter with grace, skill, and empathy, offering a ground-level look at historic atrocities that resonates beyond its story''s borders.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the fisher king', 84, 'An odd but affecting mixture of drama, comedy and fantasy, The Fisher King manages to balance moving performances from Robin Williams and Jeff Bridges with director Terry Gilliam''s typically askew universe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a fistful of dollars per un pugno di dollari', 98, 'With Akira Kurosawa''s Yojimbo as his template, Sergio Leone''s A Fistful of Dollars helped define a new era for the Western and usher in its most iconic star, Clint Eastwood.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fitzcarraldo', 78, 'With a production as audacious as the feat it''s depicting, Fitzcarraldo comes by its awe-inspiring spectacle honestly, even when it declines to examine the darker implications of its hero''s dream.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flash of genius', 61, 'The touching underdog story of a single guy against a massive corporation, Flash of Genius is a well-paced and well-written tale with a standout performance by star Greg Kinnear.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flashdance', 36, 'All style and very little substance, Flashdance boasts eye-catching dance sequences -- and benefits from an appealing performance from Jennifer Beals -- but its narrative is flat-footed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flawless', 41, 'Robert De Niro and Philip Seymour Hoffman''s Flawless performances live up to this dramedy''s title; unfortunately, they''re outweighed by the misguided picture surrounding them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fletch', 77, 'Quotably funny -- and fast-paced enough to smooth over the jokes that don''t land -- Fletch is one of the best big-screen vehicles for Chevy Chase''s brand of smug silliness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fletch lives', 37, 'Chevy Chase remains ideally suited for the role, but Fletch Lives lacks its predecessor''s wit, relying instead on silly disguises, cheap stereotypes, and largely unfunny gags.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flicka', 53, 'The rebellious protagonist will rally girls and children, but adults may find Flicka saddled with thin characters, over-the-top dialogue, and a plot that wanders into the countryside and never comes back.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flight', 78, 'Robert Zemeckis makes a triumphant return to live-action cinema with Flight, a thoughtful and provocative character study propelled by a compelling performance from Denzel Washington.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flight of the navigator', 84, 'Bolstered by impressive special effects and a charming performance from its young star, Flight of the Navigator holds up as a solidly entertaining bit of family-friendly sci-fi.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the flintstones in viva rock vegas', 25, 'The prequel to the first full-length feature set in Bedrock, Viva Rock Vegas is a surprising improvement over The Flintstones. Aimed towards an audience of adults and children alike, critics feel Viva will appeal to a broad range of viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flipped', 54, 'While not without its nostalgic charms, Rob Reiner''s sometimes awkward adaptation of Wendelin Van Draanen''s childhood novel doesn''t reach the heights of the director''s earlier work like Stand By Me.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('florence foster jenkins', 87, 'Florence Foster Jenkins makes poignant, crowd-pleasing dramedy out of its stranger-than-fiction tale -- and does its subject justice with a reliably terrific turn from star Meryl Streep.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('reaching for the moon', 65, 'Reaching for the Moon''s uptight sensibilities sometimes play more pretentious than poetic, but solid performances and sumptuous photography leave a lingering longing for love in the tropics.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('flower', 50, 'Flower proves Zoey Deutch can bring even the most preposterously written characters vividly to life -- and that she isn''t quite enough to carry a fundamentally flawed film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('for colored girls', 32, 'Tyler Perry has assembled a fine cast for this adaptation of the 1975 play, and his heart is obviously in the right place, but his fondness for melodrama cheapens a meaningful story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('for a good time call', 57, 'Brisk, funny, and sweetly raunchy, For a Good Time, Call... adds to the recent string of R-rated female comedies while serving as an overdue coming out party for the charming Ari Graynor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('for greater glory', 20, 'It has laudable aspirations, but For Greater Glory ultimately fails to fulfill its goals due to an overstuffed script, thinly written characters, and an overly simplified dramatization of historical events.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('for your eyes only', 71, 'For Your Eyes Only trades in some of the outlandish Bond staples for a more sober outing, and the result is a satisfying adventure, albeit without some of the bombastic thrills fans may be looking for.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('forces of nature', 45, 'A distinct lack of chemistry between Ben Affleck and Sandra Bullock, coupled with a screwball sensibility that''s a touch too screwy, scupper Forces of Nature''s modest ambition to serve up romantic charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('foreign correspondent', 95, 'Alfred Hitchcock''s Foreign Correspondent features a winning combination of international intrigue, comic relief, and some of the legendary director''s most memorable set pieces.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fort tilden', 88, 'Difficult to watch but ultimately all the more rewarding for it, Fort Tilden offers an intriguing calling card for writer-directors Sarah-Violet Bliss and Charles Rogers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('four brothers', 52, 'Despite striking a believable rapport among its principal actors, Four Brothers overwhelms with ultra-violent, vigilante-glorifying action and devolves into too many fractured, insubstantial thematic directions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('four rooms', 13, 'Four Rooms comes stocked with a ton of talent on both sides of the camera, yet only manages to add up to a particularly uneven -- and dismayingly uninspired -- anthology effort.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('foxy brown', 60, 'Rampant amorality and sensationalist flourishes give this crime thriller a rich coat of grime, but Foxy Brown''s powerful center lies in Pam Grier''s commanding performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('frances', 66, 'This sordid biopic emphasizes the indignities visited upon Frances Farmer to the detriment of fleshing her out as a person, but Jessica Lange''s towering performance invests the tragic figure with a humanity that the script lacks.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('frances ha', 92, 'Audiences will need to tolerate a certain amount of narrative drift, but thanks to sensitive direction from Noah Baumbach and an endearing performance from Greta Gerwig, Frances Ha makes it easy to forgive.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('francofonia', 87, 'Francofonia may test the patience of the uninitiated, but viewers willing to delve into a beautifully filmed look at the intersection of art and war will be richly rewarded.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('frankensteins monsters monster frankenstein', 88, 'While Frankenstein''s Monster''s Monster, Frankenstein''s offbeat sense of humor might be too strange for some, those looking for a kooky new comedy will find much to like in its spooky spoofs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('freak show', 52, 'Freak Show relies on engaging performances and obviously good intentions to cover for its clichéd story and uneven direction -- and for some viewers, it may well be enough.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('freddy got fingered', 10, 'Unfavorably comparing it with such infamously bad titles as Battlefield Earth, a significant number of critics are calling Tom Green''s extreme gross-out comedy the worst movie they have ever seen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the french connection', 98, 'Realistic, fast-paced and uncommonly smart, The French Connection is bolstered by stellar performances by Gene Hackman and Roy Scheider, not to mention William Friedkin''s thrilling production.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('frenzy', 90, 'Marking Alfred Hitchcock''s return to England and first foray into viscerally explicit carnage, Frenzy finds the master of horror regaining his grip on the audience''s pulse -- and making their blood run cold.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('friday', 78, 'What Friday might lack in taut construction or directorial flair, it more than makes up with its vibrant (albeit consistently crass) humor and the charming, energetic performances of its leads.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('friday the 13th part vii the new blood', 35, 'As lumbering and bereft of conscious thought as its unstoppable star, Friday the 13th Part VII - The New Blood finds the franchise in desperate need of the title ingredient.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fried green tomatoes', 74, 'Fried Green Tomatoes'' tearjerking drama is undeniably manipulative, but in the hands of a skilled cast that includes Jessica Tandy and Kathy Bates, it''s also powerfully effective.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('friends with benefits', 69, 'Friends with Benefits adds nothing new to its well-worn rom-com formula, but the chemistry between Justin Timberlake and Mila Kunis is almost enough to carry the movie by itself.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fright night', 72, 'It may not have been necessary to remake the 1985 cult classic, but the new Fright Night benefits from terrific performances by Colin Farrell and David Tennant -- and it''s smart, funny, and stylishly gory to boot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fritz the cat', 57, 'Fritz the Cat''s gleeful embrace of bad taste can make for a queasy viewing experience, but Ralph Bakshi''s idiosyncratic animation brings the satire and style of Robert Crumb''s creation to vivid life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('from the land of the moon mal de pierres', 32, 'From the Land of the Moon benefits from striking visuals and strong work from Marion Cotillard, but they''re both ultimately overcome by a story that drifts into wan melodrama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('from up on poppy hill', 86, 'Gentle and nostalgic, From Up on Poppy Hill is one of Studio Ghibli''s sweeter efforts -- and if it doesn''t push the boundaries of the genre, it remains as engagingly lovely as Ghibli fans have come to expect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('full metal jacket', 92, 'Intense, tightly constructed, and darkly comic at times, Stanley Kubrick''s Full Metal Jacket may not boast the most original of themes, but it is exceedingly effective at communicating them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('fun size', 25, 'It occasionally shows surprising flashes of wit, but Fun Size is too safe and formulaic -- not to mention unfunny -- to survive comparisons to the ''80s teen movies it eagerly imitates.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gainsbourg a heroic life', 73, 'It might be thinly written and messily made, but Gainsbourg: A Heroic Life is also appropriately glamorous and intense -- and powerfully led by a gripping performance from Erik Elmosnino.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('game night', 85, 'With a talented cast turned loose on a loaded premise -- and a sharp script loaded with dark comedy and unexpected twists -- Game Night might be more fun than the real thing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('game 6', 61, 'Though packed with Don DeLillo''s witty dialogue and bolstered by strong performances, particularly by lead Michael Keaton, Game 6 also suffers from uneven direction and overwrought symbolism.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gandhi', 85, 'Director Richard Attenborough is typically sympathetic and sure-handed, but it''s Ben Kingsley''s magnetic performance that acts as the linchpin for this sprawling, lengthy biopic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('garden state', 86, 'Delivering a quirky spin on familiar twentysomething tropes -- with a cannily-placed soundtrack -- Garden State has enough charm to mark a winning debut for first-time director Zach Braff.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gauguin voyage to tahiti', 42, 'Gaugin: Voyage to Tahiti is beautifully filmed biopic that benefits from a well-chosen lead, but neither are enough to counter the story''s surface treatment and narrative drift.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gentlemans agreement', 76, 'It occasionally fails to live up to its subject matter -- and is perhaps an ''important'' film more than a ''great'' one -- but the performances from Gregory Peck and Dorothy McGuire are superb.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('george harrison living in the material world', 86, 'Clocking in at nearly three and a half hours, George Harrison: Living in the Material World is a moving portrait of the so-called Quiet Beatle''s spirituality and troubled existence that highlights the best of Scorsese''s sensibilities.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('get a job', 5, 'Inauthentic and unfunny, Get a Job is paltry to the point that its long-delayed release feels purely the result of its wasted cast having been promoted to greater fame all these years later.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('get on the bus', 89, 'Get on the Bus finds Spike Lee pulling a page from history with fervor and flair, offering a strong, stirring fact-based drama further elevated by an array of solid performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('get shorty', 88, 'With a perfect cast and a sly twist on the usual Hollywood gangster dynamic, Get Shorty delivers a sharp satire that doubles as an entertaining comedy-thriller in its own right.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('getaway', 3, 'Monotonously fast-paced to the point of exhaustion, Getaway offers a reminder of the dangers in attempting to speed past coherent editing, character development, sensible dialogue, and an interesting plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('getting even with dad', 3, 'Overly formulaic and tonally inconsistent, Getting Even with Dad tries for a sentimental conclusion it doesn''t earn and winds up a slapsticky cash grab aimed at fans of Home Alone.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghost dad', 6, 'A startlingly misconceived effort from director Sidney Poitier and star Bill Cosby, Ghost Dad is a listless, glacially-paced comedy that''s alternately schmaltzy and incomprehensible.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghost in the shell', 96, 'A stunning feat of modern animation, Ghost in the Shell offers a thoughtful, complex treat for anime fans, as well as a perfect introduction for viewers new to the medium.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghost in the shell', 43, 'Ghost in the Shell boasts cool visuals and a compelling central performance from Scarlett Johansson, but the end result lacks the magic of the movie''s classic source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghost rider spirit of vengeance', 18, 'With a weak script, uneven CG work, and a Nic Cage performance so predictably loony it''s no longer amusing, Ghost Rider: Spirit of Vengeance aims to be trashy fun but ends up as plain trash.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghostbusters', 74, 'Ghostbusters does an impressive job of standing on its own as a freewheeling, marvelously cast supernatural comedy -- even if it can''t help but pale somewhat in comparison with the classic original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghosts of girlfriends past', 27, 'A retread of A Christmas Carol, featuring Matthew McConaughey in a retread of his Dazed and Confused role, Ghosts of Girlfriends Past lacks originality, humor, and any semblance of charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ghosts of mississippi', 43, 'James Woods is convincing as a white supremacist, but everything else rings false in this courtroom drama, which examines a weighty subject from the least interesting perspective.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gi joe the rise of cobra', 34, 'While fans of the Hasbro toy franchise may revel in a bit of nostalgia, G.I. Joe: The Rise of Cobra is largely a cartoonish, over-the-top action fest propelled by silly writing, inconsistent visual effects, and merely passable performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gimme danger', 94, 'Its infectious enthusiasm for its subjects - and Iggy Pop''s ingratiating presence - more than make up for the effortlessly entertaining Gimme Danger''s relative lack of context or depth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('girl interrupted', 53, 'Angelina Jolie gives an intense performance, but overall Girl, Interrupted suffers from thin, predictable plotting that fails to capture the power of its source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the girl who played with fire flickan som lekte med elden', 69, 'Noomi Rapace and Michael Nyqvist remain extraordinarily well-suited to their roles, but the second installment in Stieg Larsson''s Millennium Trilogy doesn''t pack quite as much punch as the first.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('girls trip', 91, 'Girls Trip is the rare R-rated comedy that pushes boundaries to truly comedic effect -- and anchors its laughs in compelling characters brought to life by a brilliantly assembled cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('glass', 37, 'Glass displays a few glimmers of M. Night Shyamalan at his twisty world-building best, but ultimately disappoints as the conclusion to the writer-director''s long-gestating trilogy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('glassland', 84, 'Glassland''s grim setting is leavened by writer-director Gerard Barrett''s compassionate treatment of his characters -- and bolstered by a strong cast led by Toni Collette and Jack Reynor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gleason', 96, 'Gleason stands out among sports-themed documentaries by offering a clear-eyed look at its subject''s physical deterioration -- and an intimate portrait of the family affected by his ordeal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('glengarry glen ross', 95, 'This adaptation of David Mamet''s play is every bit as compelling and witty as its source material, thanks in large part to a clever script and a bevy of powerhouse actors.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gloria', 99, 'Marvelously directed by Sebastian Lelio and beautifully led by a powerful performance from Paulina Garcia, Gloria takes an honest, sweetly poignant look at a type of character that''s all too often neglected in Hollywood.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('god said ha', 86, 'God Said, Ha! plumbs poignant depths, but Julia Sweeney''s sharp, graceful wit makes this one-woman monologue a wise, big-hearted burst of uplifting -- and perhaps therapeutic -- entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the godfather', 98, 'One of Hollywood''s greatest critical and commercial successes, The Godfather gets everything right; not only did the movie transcend expectations, it established new benchmarks for American cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the godfather part ii', 98, 'Drawing on strong performances by Al Pacino and Robert De Niro, Francis Ford Coppola''s continuation of Mario Puzo''s Mafia saga set new standards for sequels that have yet to be matched or broken.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the godfather part iii', 68, 'The final installment of The Godfather saga recalls its predecessors'' power when it''s strictly business, but underwhelming performances and confused tonality brings less closure to the Corleone story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gods not dead', 12, 'Deploying sledgehammer theatrics instead of delivering its message with a dose of good faith, God''s Not Dead makes for bad drama and an unconvincing argument to the unconverted.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gods of egypt', 16, 'Look on Gods of Egypt, ye filmgoers, and despair! Nothing beside remains. Round the decay of this colossal wreck, boundless and bare. The lone and level sands stretch far away. (Apologies to Shelley.)');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('godzilla', 76, 'With just enough human drama to anchor the sweeping spectacle of giant monsters smashing everything in sight, Gareth Edwards'' Godzilla satisfyingly restores the franchise''s fire-breathing glory.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the golden bowl', 53, 'Coming from the Merchant-Ivory team, The Golden Bowl is visually stunning, but the filmmakers have difficulty in transporting the characterizations of the Henry James novel to the screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('goldeneye', 78, 'The first and best Pierce Brosnan Bond film, GoldenEye brings the series into a more modern context, and the result is a 007 entry that''s high-tech, action-packed, and urbane.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('goldfinger', 99, 'Goldfinger is where James Bond as we know him comes into focus - it features one of 007''s most famous lines ("A martini. Shaken, not stirred") and a wide range of gadgets that would become the series'' trademark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gone baby gone', 94, 'Ben Affleck proves his directing credentials in this gripping dramatic thriller, drawing strong performances from the excellent cast and bringing working-class Boston to the screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gone with the wind', 91, 'Gone with the Wind''s epic grandeur and romantic allure encapsulate an era of Hollywood filmmaking -- but that can''t excuse a blinkered perspective that stands on the wrong side of history.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gonzo the life and work of hunter s thompson', 87, 'While not the comprehensive profile of the man that his die-hard fans might have hoped for, Gonzo remains an insightful introduction to the life of rebellious writer Hunter S. Thompson and his influences.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('good burger', 32, 'Good Burger might please hardcore fans of the 1990s Nickelodeon TV series that launched leads Kenan and Kel to stardom, but for all others, it will likely prove a comedy that is neither satisfyingly rare nor well done.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the good german', 34, 'Though Steven Soderbergh succeeds in emulating the glossy look of 1940s noirs, The Good German ultimately ends up as a self-conscious exercise in style that forgets to develop compelling characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('good time', 92, 'A visual treat filled out by consistently stellar work from Robert Pattinson, Good Time is a singularly distinctive crime drama offering far more than the usual genre thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('good will hunting', 97, 'It follows a predictable narrative arc, but Good Will Hunting adds enough quirks to the journey -- and is loaded with enough powerful performances -- that it remains an entertaining, emotionally rich drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('goodbye christopher robin', 63, 'Goodbye Christopher Robin struggles to balance wartime tension and childlike wonder, but offers valuable insight into the darkness shadowing the creation of a classic children''s tale.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('goon last of the enforcers', 43, 'Seann William Scott remains as watchable as ever in the title role, but Goon: Last of the Enforcers repeats its predecessor''s violent and profane formula to diminishing effect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('il vangelo secondo matteo the gospel according to st matthew', 91, 'The Gospel According to St. Matthew forgoes the pageantry of biblical epics in favor of a naturalistic retelling of the Christ story, achieving a respectful if not reverent interpretation with political verve.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('grandma', 91, 'Boasting a stellar performance from Lily Tomlin and some powerfully empathetic work from writer-director Paul Weitz, Grandma is a dramedy that shouldn''t have to ask you to visit.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('grease 2', 36, 'Grease 2 is undeniably stocked with solid songs and well-choreographed dance sequences, but there''s no getting around the fact that it''s a blatant retread of its far more entertaining predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('grease live', 92, 'Grease: Live took the pressure and threw away conventionality -- it belongs to yesterday. There was a chance that it could make it so far; we started believin'' we can be who we are. Grease: Live is the word.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the great dictator', 93, 'Charlie Chaplin demonstrates that his comedic voice is undiminished by dialogue in this rousing satire of tyranny, which may be more distinguished by its uplifting humanism than its gags.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('great expectations', 100, 'Furnished with striking visual detail and told with great narrative economy by director David Lean, Great Expectations is an exemplary adaptation of Charles Dickens'' dense and episodic novel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('great expectations', 68, 'Not the best version of the oft-filmed Dickens classic but far from the worst, Mike Newell''s Great Expectations breathes just enough life into the source material to justify yet another adaptation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the great muppet caper', 76, 'The Great Muppet Caper is overplotted and uneven, but the appealing presence of Kermit, Miss Piggy and the gang ensure that this heist flick is always breezily watchable.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the great new wonderful', 73, 'Set in post-9/11 New York, this largely evocative dramedy interweaves the stories of five disconnected individuals who share an unspoken emotional malaise that shadows their attempts at returning to normal life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('green dragon', 61, 'Green Dragon struggles to control its sentimental tendencies, but its flaws are just outweighed by an affecting -- and often overlooked -- perspective on the Vietnam War.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('grey gardens', 94, 'Edith and Edie Beale are eccentric subjects who offer a generous amount of themselves in Grey Gardens, an inquisitive and nonjudgmental exploration of the isolated socialites'' lifestyle.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gridiron gang', 42, 'The role of probation officer Sean Porter fits Dwayne "The Rock" Johnson like a glove; however, the execution is so cliched, the youths'' stories (based on real events), fail to inspire.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gringo', 40, 'Gringo rounds up a bafflingly overqualified cast for a misfire of a comedy that''s fatally undermined by its messy plot, poorly conceived characters, and obvious debts to better films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('grown ups 2', 8, 'While it''s almost certainly the movie event of the year for filmgoers passionate about deer urine humor, Grown Ups 2 will bore, annoy, and disgust audiences of nearly every other persuasion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('guardians of the galaxy', 91, 'Guardians of the Galaxy is just as irreverent as fans of the frequently zany Marvel comic would expect -- as well as funny, thrilling, full of heart, and packed with visual splendor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('guardians of the galaxy vol 2', 85, 'Guardians of the Galaxy Vol. 2''s action-packed plot, dazzling visuals, and irreverent humor add up to a sequel that''s almost as fun -- if not quite as thrillingly fresh -- as its predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('guess whos coming to dinner', 70, 'More well-intentioned than insightful in its approach to interracial marriage, Guess Who''s Coming to Dinner succeeds thanks to the fizzy chemistry of its star-studded ensemble.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('guest of cindy sherman', 71, 'The filmmakers'' motivations may be suspect, but this inside look at New York art legend Cindy Sherman -- and, by extension, the culture she inhabits -- is undeniably satisfying.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('gullivers travels', 20, 'Though Jack Black is back doing what he does best, Gulliver''s Travels largely fails to do any justice to its source material, relying instead on juvenile humor and special effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hacksaw ridge', 84, 'Hacksaw Ridge uses a real-life pacifist''s legacy to lay the groundwork for a gripping wartime tribute to faith, valor, and the courage of remaining true to one''s convictions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hairspray', 91, 'Hairspray is an energetic, wholly entertaining musical romp; a fun Summer movie with plenty of heart. Its contagious songs will make you want to get up and start dancing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hall pass', 33, 'Some filmgoers may be surprised by the Farrellys'' defense of traditional domestic values in Hall Pass -- unfortunately, they''ll probably also be dismayed by the absence of laughs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('halloween', 79, 'Halloween largely wipes the slate clean after decades of disappointing sequels, ignoring increasingly elaborate mythology in favor of basic - yet still effective - ingredients.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('halloween 4 the return of michael myers', 29, 'Halloween 4: The Return Of Michaels Myers may bring the series'' masked killer back into the fold, but fails to offer the visceral scares and inventiveness of the original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hanging up', 12, 'Though the screenplay and the novel it''s based on were both written by the same person, critics say Hanging Up is an unsuccessful adaptation. The acting is praised as solid, but is ultimately unable to save the film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('happy death day 2u', 71, 'A funnier follow-up with a sci-fi bent, Happy Death Day 2U isn''t as fiendishly fresh as its predecessor, but fans of the original may still find this a sequel worth celebrating.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('happy gilmore', 61, 'Those who enjoy Adam Sandler''s schtick will find plenty to love in this gleefully juvenile take on professional golf; those who don''t, however, will find it unfunny and forgettable.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('happy texas', 81, 'A smart, light-hearted romantic comedy, Happy, Texas uses its well-written script and exceptional cast to prove there''s still life left in the fish-out-of-water caper genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hard candy', 67, 'Disturbing, controversial, but entirely engrossing, Hard Candy is well written with strong lead performances, especially that of newcomer Ellen Page. A movie that stays with the viewer long after leaving the theater.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hard target', 57, 'Hard Target gets a boost from John Woo''s stylish direction, but at heart, it''s still another silly, explosion-dependent action thriller in the Jean-Claude Van Damme oeuvre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('harry brown', 63, 'Its lurid violence may put off some viewers, but Harry Brown is a vigilante thriller that carries an emotional as well as a physical punch, thanks to a gripping performance from Michael Caine in the title role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('harry potter and the chamber of secrets', 82, 'Though perhaps more enchanting for younger audiences, Chamber of Secrets is nevertheless both darker and livelier than its predecessor, expanding and improving upon the first film''s universe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('harry potter and the deathly hallows part 1', 77, 'It can''t help but feel like the prelude it is, but Deathly Hallows: Part I is a beautifully filmed, emotionally satisfying penultimate installment for the Harry Potter series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('harry potter and the goblet of fire', 88, 'The main characters are maturing, and the filmmakers are likewise improving on their craft; vibrant special effects and assured performances add up to what is the most complex yet of the Harry Potter films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('harry potter and the order of the phoenix', 78, 'It''s not easy to take the longest Harry Potter book and streamline it into the shortest HP movie, but director David Yates does a bang up job of it, creating an Order of the Phoenix that''s entertaining and action-packed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('harry potter and the prisoner of azkaban', 90, 'Under the assured direction of Alfonso Cuaron, Harry Potter and the Prisoner of Azkaban triumphantly strikes a delicate balance between technical wizardry and complex storytelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('harry potter and the sorcerers stone', 81, 'Harry Potter and the Sorcerer''s Stone adapts its source material faithfully while condensing the novel''s overstuffed narrative into an involving -- and often downright exciting -- big-screen magical caper.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('haywire', 80, 'MMA star and first-time actress Gina Carano displays ample action-movie chops in Haywire, a fast-paced thriller with a top-notch cast and outstanding direction from Steven Soderbergh.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('he got game', 81, 'Though not without its flaws, He Got Game finds Spike Lee near the top of his game, combining trenchant commentary with his signature visuals and a strong performance from Denzel Washington.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('head count', 68, 'Head Count doesn''t wrack up enough punchy scares to be an unqualified success as a horror outing, but an engaging cast and textured characters make it a refreshing genre exercise with something on its mind.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hearts and minds', 90, 'A powerful, unflinching exploration of the Vietnam War, with first-person stories from both sides of the conflict, Hearts and Minds still hits the mark decades after its release.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hearts of darkness a filmmakers apocalypse', 100, 'Chronicling the filming of Apocalypse Now through Eleanor Coppola''s empathetic and frank point of view, Hearts of Darkness is a revelatory investigation of moviemaking and how creative obsession can impact an artist''s family.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heaven is for real', 51, 'Heaven Is for Real boasts a well-written screenplay and a talented cast, but overextends itself with heavy-handed sequences depicting concepts it could have trusted the audience to take on faith.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heavy metal in baghdad', 83, 'Despite being a Gonzo-esque rockumentary following the fortunes of Iraq''s one and only heavy metal band, Acrassicauda, Heavy Metal is actually a moving and impassioned account of the middle-east crisis.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heli', 59, 'There''s no denying the seriousness of Heli''s story or the raw power of its more uncomfortable moments, but they''re used in service of a grimly alienating film that many viewers may ultimately find unrewarding.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hell baby', 31, 'Though its brand of immature comedy may appeal to some, Hell Baby misses the mark with much of its humor, rendering it a largely ineffective -- and often crass -- genre sendup.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hello i must be going', 75, 'Hello I Must Be Going offers an offbeat twist to the romance genre, a solid character study for fans of grown-up drama, and a career-making breakout vehicle for Melanie Lynskey.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hemingway gellhorn', 49, 'Nicole Kidman''s poised performance provides some measure of reclamation for Martha Gellhorn, but this trite historical melodrama reduces Ernest Hemingway and the era that the two war correspondents lived through into a broad caricature.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('henry v the chronicle history of king henry the fift with his battell fought at agincourt in france', 100, 'A patriotic booster, Laurence Olivier''s directorial debut and star turn as Henry V result in a sharply realized and resonant take on Shakespeare''s deeply British warrior king.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hercules', 58, 'Hercules has Brett Ratner behind the cameras and Dwayne Johnson rocking the loincloth -- and delivers exactly what any reasonable person reading that description might expect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('here comes the boom', 41, 'Here Comes the Boom benefits from Kevin James''s genial presence but the film doesn''t deliver enough laughs to live up to its title -- or enough satisfying plot to make up the difference.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('here on earth', 17, 'Critics say Here on Earth''s weakness comes from its script. The story may appeal to young teenage girls, but it suffers from being overly sentimental and formulaic. The cinematography, however, is lovely in how it captures its Minnesota setting.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hereafter', 47, 'Despite a thought-provoking premise and Clint Eastwood''s typical flair as director, Hereafter fails to generate much compelling drama, straddling the line between poignant sentimentality and hokey tedium.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('high life', 82, 'High Life is as visually arresting as it is challenging, confounding, and ultimately rewarding - which is to say it''s everything film fans expect from director Claire Denis.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('highrise', 60, 'High-Rise may not quite live up to its classic source material, but it still offers an energetic, well-acted, and thought-provoking take on its timely socioeconomic themes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('himalaya lenfance dun chef caravan', 87, 'Unlike the overproduced and overbudgeted Hollywood blockbusters, Himalaya is a stunningly photographed movie that offers an intimate look into the lives of a Dolpo tribe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hiroshima mon amour', 97, 'Distinguished by innovative technique and Emmanuelle Riva''s arresting performance, Hiroshima Mon Amour is a poignant love story as well as a thoughtful meditation on international trauma.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('history of the worldpart i', 58, 'History of the World: Part I may not have enough comedic inspiration to merit a Part II, but the sporadic cleverness of these anachronistic skits are still a testament to Mel Brooks'' gift for farce.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a history of violence', 87, 'A History of Violence raises compelling and thoughtful questions about the nature of violence, while representing a return to form for director David Cronenberg in one of his more uncharacteristic pieces.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hitman agent 47', 9, 'Hitman: Agent 47 fails to clear the low bar set by its predecessor, forsaking thrilling action in favor of a sleekly hollow mélange of dull violence and product placement.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hobo with a shotgun', 66, 'It certainly isn''t subtle -- or even terribly smart -- but as a gleefully gory homage to low-budget exploitation thrillers, Hobo with a Shotgun packs plenty of firepower.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('holiday inn', 100, 'With the combined might of Bing Crosby, Fred Astaire, and Irving Berlin working in its favor, Holiday Inn is a seasonal classic -- not least because it introduced "White Christmas" to the world.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('holy motors', 92, 'Mesmerizingly strange and willfully perverse, Holy Motors offers an unforgettable visual feast alongside a spellbinding -- albeit unapologetically challenging -- narrative.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('home alone 3', 29, 'Macaulay Culkin''s precocious charisma is sorely missed in this hollow sequel, which doubles down on the broad comedy while lacking all the hallmarks that made the original a classic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a home at the end of the world', 50, 'A Home at the End of the World aims for profundity, but settles for stale melodrama, yielding a slew of sensitive performances that are nevertheless in service of characters who prove to be ciphers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('home sweet hell', 5, 'Home Sweet Hell mistakes misogyny for subversive wit, aiming for black comedy but ending up with a grueling test of viewer endurance that wastes game efforts from its likable leads.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('homeward bound the incredible journey', 87, 'Disney''s remake of The Incredible Journey successfully replicates, and in some ways improves upon, the simple charms of the original, with its cross-country animal odyssey sure to delight kids.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hoop dreams', 98, 'One of the most critically acclaimed documentaries of all time, Hoop Dreams is a rich, complex, heartbreaking, and ultimately deeply rewarding film that uses high school hoops as a jumping-off point to explore issues of race, class, and education in modern America.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hope springs', 75, 'Led by a pair of mesmerizing performances from Meryl Streep and Tommy Lee Jones, Hope Springs offers filmgoers some grown-up laughs -- and a thoughtful look at mature relationships.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('horror of dracula', 90, 'Trading gore for grandeur, Horror of Dracula marks an impressive turn for inveterate Christopher Lee as the titular vampire, and a typical Hammer mood that makes aristocracy quite sexy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hot fuzz', 91, 'The brilliant minds behind Shaun of the Dead successfully take a shot at the buddy cop genre with Hot Fuzz. The result is a bitingly satiric and hugely entertaining parody.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hot summer nights', 43, 'Hot Summer Nights is easy on the eyes and clearly indebted to some great films, but its strengths -- including a charismatic young cast -- are often outweighed by its uninspired story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hotel artemis', 58, 'Hotel Artemis has a few flashes of wit and an intriguing cast, but mostly it''s just a serviceable chunk of slightly futuristic violence -- which might be all its audience is looking for.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hotel transylvania 2', 56, 'Hotel Transylvania 2 is marginally better than the original, which may or may not be enough of a recommendation to watch 89 minutes of corny, colorfully animated gags from Adam Sandler and company.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hotel transylvania 3 summer vacation', 62, 'Hotel Transylvania 3: Summer Vacation delivers exactly what fans will expect - which means another 97 agreeably lightweight minutes of fast-paced gags and colorful animation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hottie and the nottie', 6, 'The Hottie and the Nottie is a crass, predictable, and ineptly staged gross-out comedy that serves little purpose beyond existing as another monument to Paris Hilton''s vanity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hounds of love', 88, 'Smartly constructed and powerfully acted, Hounds of Love satisfies as a psychological thriller with a few nasty surprises -- and marks writer-director Ben Young as a promising talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('how to lose friends alienate people', 37, 'A decent performance from Pegg in a disappointing film. Neither sharp nor satirical, Weide''s adaptation relies too heavily on slapstick, and misses the point of the source material in the process.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('howards end', 94, 'A superbly-mounted adaptation of E.M. Forster''s tale of British class tension, with exceptional performances all round, Howard''s End ranks among the best of Merchant-Ivory''s work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('howls moving castle', 87, 'Exquisitely illustrated by master animator Miyazaki, Howl''s Moving Castle will delight children with its fantastical story and touch the hearts and minds of older viewers as well.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hunger', 90, 'Unflinching, uncompromising, vivid and vital, Steve McQueen''s challenging debut is not for the faint hearted, but it''s still a richly rewarding retelling of troubled times.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hyde park on hudson', 37, 'Though bolstered by a thoroughly charming performance by Bill Murray in the central role, Hyde Park on Hudson is an FDR biopic that lets down both its audience and its subject.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i am chris farley', 71, 'I Am Chris Farley lives up to its title by taking a poignant look at the life of the deceased star that should prove affecting and illuminating for novicers and longtime fans alike.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i am michael', 64, 'I Am Michael takes a determinedly balanced approach to its complex subject, and although the results don''t always add up, they''re anchored by strong work from James Franco.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i am not your negro', 99, 'I Am Not Your Negro offers an incendiary snapshot of James Baldwin''s crucial observations on American race relations -- and a sobering reminder of how far we''ve yet to go.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i am number four', 33, 'It''s positioned as the start of a franchise, but I Am Number Four''s familiar plot and unconvincing performances add up to one noisy, derivative, and ultimately forgettable sci-fi thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i can only imagine', 63, 'I Can Only Imagine''s message will have the most impact among Christian audiences, but overall, its performances and storytelling represent a notable evolution in faith-based cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i dont feel at home in this world anymore', 89, 'I don''t feel at home in this world anymore. transcends its unwieldy title to offer timely, intoxicatingly dark observations on gender dynamics and social norms in modern America.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i feel pretty', 35, 'I Feel Pretty has a charming star and the outline of a worthwhile comedy -- but unlike its suddenly confident central character, it suffers from a fundamental lack of conviction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i hope they serve beer in hell', 20, 'I Hope They Serve Beer in Hell fails in its attempts at raunchy humor, and Tucker Max comes across so unlikable and outrageous that the film''s inevitable story arc feels forced.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i lost my body', 96, 'Beautifully animated and utterly unique, I Lost My Body takes audiences on a singularly strange journey whose unexpected contours lead to a wholly satisfying destination.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i melt with you', 16, 'Presenting itself as profound while relying entirely on shock factor, I Melt With You subjects its audience to a misanthropic marathon of bad behavior that''s about as fun as a mid-life crisis.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i saw the light', 18, 'I Saw the Light boasts a terrifically talented cast, but their performances aren''t enough to enliven an unfocused biopic that never comes close to capturing its subject''s timeless appeal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i see you', 78, 'I See You gets tripped up on its own narrative contortions, but a solid cast and an effective blend of scares and suspense make this slow-building mystery worth watching.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i tonya', 89, 'Led by strong work from Margot Robbie and Alison Janney, I, Tonya finds the humor in its real-life story without losing sight of its more tragic -- and emotionally resonant -- elements.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i walked with a zombie', 93, 'Evocative direction by Jacques Tourneur collides with the low-rent production values of exploitateer Val Lewton in I Walked with a Zombie, a sultry sleeper that''s simultaneously smarmy, eloquent and fascinating.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('i wish', 93, 'Elliptical and deliberately paced yet steadily absorbing, I Wish presents a beguiling portrait of childhood that grounds its sweetly nostalgic glow with well-rounded characters and attention to detail.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('icarus', 94, 'Icarus is eye-opening viewing for professional sports enthusiasts, yet it should also prove thoroughly gripping even for filmgoers who might not necessarily be drawn to the subject.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ice age collision course', 18, 'Unoriginal and unfunny, Ice Age: Collision Course offers further proof that not even the healthiest box office receipts can keep a franchise from slouching toward creative extinction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('if i stay', 35, 'Although Chloë Grace Moretz gives it her all and the story adds an intriguing supernatural twist to its melodramatic YA framework, If I Stay is ultimately more manipulative than moving.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('il divo', 92, 'While the web of corruption in this Italian political thriller can be hard for a non-native to follow, the visuals and the intrigue are compelling and thrilling in equal measure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ill see you in my dreams', 93, 'I''ll See You in My Dreams would be worth watching even if Blythe Danner''s central performance was all it had going for it, but this thoughtful drama satisfies on multiple levels.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ill sleep when im dead', 44, 'I''ll Sleep When I''m Dead''s spare performances and slick style are undermined by a lack of cohesive story, yielding a neatly packaged noir with little substance beneath its polished surface.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('im not there', 77, 'I''m Not There''s unique editing, visuals, and multiple talented actors portraying Bob Dylan make for a deliciously unconventional experience. Each segment brings a new and fresh take on Dylan''s life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('im still here', 53, 'As unkempt and inscrutable as Joaquin Phoenix himself, I''m Still Here raises some interesting questions about its subject, as well as the nature of celebrity, but it fails to answer many of them convincingly.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('imperium', 85, 'The unsettling Imperium boasts troublingly timely themes and a talented cast led by Daniel Radcliffe as an undercover FBI agent infiltrating a ring of white supremacists.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the importance of being earnest', 57, 'Oliver Parker''s adaptation of Oscar Wilde''s classic play is breezy entertainment, helped by an impressive cast, but it also suffers from some peculiar directorial choices that ultimately dampen the film''s impact.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in out', 71, 'It doesn''t always find comfortable ground between broad comedy and social commentary, but lively performances -- especially from Kevin Kline and Joan Cusack -- enrich In & Out''s mixture of laughs and sexual tolerance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in another country', 82, 'In Another Country offers intelligent observations throughout its trio of overlapping stories -- and demonstrates again just how much Isabelle Huppert''s presence can improve a film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in search of beethoven', 93, 'With a wealth of insightful talking heads and deft musical performances, In Search of Beethoven is a thorough, thoughtful examination of the great composer''s life and times.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in search of greatness', 92, 'Gabe Polsky''s persuasive documentary comes close to Greatness, making a strong case for its intriguing thesis and chock full of refreshing insights into some of the world''s most admired athletes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in search of mozart', 81, 'In Search of Mozart may not be quite as exhilarating as its subject''s classic compositions, but it offers an enlightening, entertaining primer on the life of a brilliant artist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the army now', 6, 'This 1994 Pauly Shore vehicle stretches its star''s thin shtick to the breaking point with a laugh-deficient screenplay that borrows shamelessly from Bill Murray''s far superior Stripes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the company of men', 89, 'Neil LaBute''s pitch-black comedy is a masterful exploration of male insecurity, and it''s elevated by a breakout performance by Aaron Eckhart as a businessman who likes to play psychological games.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the heart of the sea', 43, 'The admirably old-fashioned In the Heart of the Sea boasts thoughtful storytelling to match its visual panache, even if it can''t claim the depth or epic sweep to which it so clearly aspires.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the heat of the night', 95, 'Tense, funny, and thought-provoking all at once, and lifted by strong performances from Sydney Poitier and Rod Steiger, director Norman Jewison''s look at murder and racism in small-town America continues to resonate today.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the land of blood and honey', 57, 'Angelina Jolie displays a deft directorial hand in her feature debut, but In the Land of Blood and Honey''s contrived love story never mixes in comfortably with depictions of the Bosnian genocide.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the line of fire', 96, 'A straightforward thriller of the highest order, In the Line of Fire benefits from Wolfgang Peterson''s taut direction and charismatic performances from Clint Eastwood and John Malkovich.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the name of the father', 94, 'Impassioned and meticulously observed, In the Name of the Father mines rousing drama from a factual miscarriage of justice, aided by scorching performances and director Jim Sheridan''s humanist focus.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('in the valley of elah', 74, 'Though some of Paul Haggis''s themes are heavy-handed, In the Valley of Elah is otherwise an engrossing murder mystery and antiwar statement, featuring a mesmerizing performance from Tommy Lee Jones.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('incredibles 2', 93, 'Incredibles 2 reunites Pixar''s family crimefighting team for a long-awaited follow-up that may not quite live up to the original, but comes close enough to earn its name.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('indiana jones and the kingdom of the crystal skull', 78, 'Though the plot elements are certainly familiar, Indiana Jones and the Kingdom of the Crystal Skull still delivers the thrills and Harrison Ford''s return in the title role is more than welcome.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('indiana jones and the last crusade', 88, 'Lighter and more comedic than its predecessor, Indiana Jones and the Last Crusade returns the series to the brisk serial adventure of Raiders, while adding a dynamite double act between Harrison Ford and Sean Connery.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('indiana jones and the temple of doom', 84, 'It may be too "dark" for some, but Indiana Jones and the Temple of Doom remains an ingenious adventure spectacle that showcases one of Hollywood''s finest filmmaking teams in vintage form.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('inequality for all', 90, 'While it arrives in a glut of similarly themed documentaries, Inequality for All distinguishes itself with a compelling presentation of an important message, as well as much-needed splashes of wit.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('inherent vice', 74, 'Inherent Vice may prove frustrating for viewers who demand absolute coherence, but it does justice to its acclaimed source material -- and should satisfy fans of director P.T. Anderson.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('innerspace', 82, 'A manic, overstuffed blend of sci-fi, comedy, and romance, Innerspace nonetheless charms, thanks to Martin Short''s fine performance and the insistent zaniness of the plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('inside deep throat', 82, 'A documentary on the film that brought smut mainstream, Inside Deep Throat is gaining praise as an entertaining look at a pop culture milestone. However, some critics say the film could have gone a little deeper into the people involved.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('inside man', 86, 'Spike Lee''s energetic and clever bank-heist thriller is a smart genre film that is not only rewarding on its own terms, but manages to subvert its pulpy trappings with wit and skill.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('instant family', 80, 'Instant Family may not quite capture the complexity of real-life adoption, but fittingly for the unconditional bond it honors, this flawed yet well-intentioned dramedy is ultimately worth the investment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('interstellar', 72, 'Interstellar represents more of the thrilling, thought-provoking, and visually resplendent filmmaking moviegoers have come to expect from writer-director Christopher Nolan, even if its intellectual reach somewhat exceeds its grasp.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('interview with the vampire', 63, 'Despite lacking some of the book''s subtler shadings, and suffering from some clumsy casting, Interview with a Vampire benefits from Neil Jordan''s atmospheric direction and a surfeit of gothic thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('intimate strangers', 86, 'Intimate Strangers is Hitchcockian noir with a Gallic twist: Rather than simply imitating the genre''s form, director/screenwriter Patrice Leconte delves into the underlying psychological drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('into the forest', 76, 'Into the Forest grounds its familiar apocalyptic framework with a relatable look at the bond between two sisters, compellingly brought to life by Ellen Page and Evan Rachel Wood.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('into the inferno', 92, 'Into the Inferno finds director Werner Herzog observing some of the most beautiful -- and terrifying -- wonders of the natural world with his signature blend of curiosity and insight.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('into the woods', 71, 'On the whole, this Disney adaptation of the Sondheim classic sits comfortably at the corner of Hollywood and Broadway -- even if it darkens to its detriment in the final act.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('invictus', 77, 'Delivered with typically stately precision by director Clint Eastwood, Invictus may not be rousing enough for some viewers, but Matt Damon and Morgan Freeman inhabit their real-life characters with admirable conviction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('invincible', 72, 'As simple and authentic as the gritty South Philly invirons in which it''s set in, Invincible sends a uplifting and heartfelt message packed with an athletic enthusiasm that shouldn''t be missed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the invisible circus', 22, 'Despite Jordana Brewster''s strong performance, The Invisible Circus lacks the necessary dramatic tension to be interesting. Also, the cultural and political contexts of the period are barely explored.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ip man', 85, 'At once beholden to the established conventions of the genre and delightfully subversive of them, Ip Man is one of the most exciting -- and refreshingly character-driven -- martial arts films in years.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('iron man 3', 79, 'With the help of its charismatic lead, some impressive action sequences, and even a few surprises, Iron Man 3 is a witty, entertaining adventure and a strong addition to the Marvel canon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('is the man who is tall happy an animated conversation with noam chomsky', 92, 'An unlikely pairing of form and style, Michel Gondry''s Is the Tall Man Happy? successfully gives Noam Chomsky''s philosophical musings an expressive canvas with a delightfully anarchic animation style.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ishtar', 37, 'Warren Beatty, Dustin Hoffman, and laughter itself get lost in the desert during a flawed spoof of classic road movies that proves ill-suited for its mismatched and miscast stars.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('island of lemurs madagascar', 81, 'Brief enough for the youngest viewers yet informative and visually spectacular enough for all ages, Island of Lemurs: Madagascar is educational entertainment for the whole family.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('it', 85, 'Well-acted and fiendishly frightening with an emotionally affecting story at its core, It amplifies the horror in Stephen King''s classic story without losing touch with its heart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('it comes at night', 87, 'It Comes at Night makes lethally effective use of its bare-bones trappings while proving once again that what''s left unseen can be just as horrifying as anything on the screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the italian', 91, 'Poignant and unforgettable, The Italian stands out from other European melodramas. Like its extraordinary child lead, this Russian drama about an orphan''s search for his birth mother is small in size and monumental in pathos.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('its kind of a funny story', 57, 'It''s amiable, and it does a surprisingly good job of sidestepping psych ward comedy cliches, but given its talented cast and directors, It''s Kind of a Funny Story should be more than just mildly entertaining.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('its all gone pete tong', 76, 'Part raucous mockumentary, part drama-filled biopic, It''s All Gone Pete Tong amuses and warms hearts with its touching, comic, and candid look at a musician faced with a career-ending handicap.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ivory tower', 83, 'Although Ivory Tower makes it clear that there isn''t enough room in a 90-minute film to tackle spiraling student loan debt, it also serves as a compelling call for deeper investigation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('j edgar', 43, 'Leonardo DiCaprio gives a predictably powerhouse performance, but J. Edgar stumbles in all other departments with cheesy makeup, poor lighting, confusing narrative, and humdrum storytelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jack brooks monster slayer', 61, 'A sincere but sometimes-excessive send up of low-rent horror hokum, Jack Brooks: Monster Slayer features some sharp laughs and features a scene-stealing performance by Robert Englund.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jackass 3', 65, 'The Jackass gang might be running out of gross-out stunts, but this installment contains plenty of brilliantly brain-dead comedy -- and the 3-D adds a pungent new dimension.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jackass presents bad grandpa', 61, 'Never quite as funny as it wants to be, Jackass Presents: Bad Grandpa still offers viewers the timeless pleasures of seeing an old man get his privates stuck in a vending machine.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('james white', 92, 'Led by powerfully complementary performances from Christopher Abbott and Cynthia Nixon, James White offers an affecting calling card for debuting writer-director Josh Mond.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jane eyre', 84, 'Cary Fukunaga directs a fiery and elegant adaptation of Charlotte Bronte''s classic novel, and Mia Wasikowska delivers possibly the best portrayal of the title character ever.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('janis little girl blue', 94, 'Respectful without veering into hagiography and inquisitive without being intrusive, Janis: Little Girl Blue offers an insightful glimpse into the life of a rock ''n'' roll legend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jaws', 98, 'Compelling, well-crafted storytelling and a judicious sense of terror ensure Steven Spielberg''s Jaws has remained a benchmark in the art of delivering modern blockbuster thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jaws 3', 12, 'A cheese-soaked ocean thriller with no evident reason to exist, Jaws 3 bellows forth with a plaintive yet ultimately unheeded cry to put this franchise out of viewers'' misery.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jay and silent bob strike back', 52, 'Fans can expect a good laugh as the cast from Smith''s previous films reunite for Jay and Silent Bob''s last bow. The loose plotting and crude language may be too much for others though.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jayne mansfields car', 35, 'Jayne Mansfield''s Car assembles an impressive number of talented actors, but the screenplay -- co-written by director and star Billy Bob Thornton -- never gives them much of anything to do.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jeremiah johnson', 95, 'Jeremiah Johnson''s deliberate pace demands an investment from the viewer, but it''s rewarded with a thoughtful drama anchored by a starring performance from Robert Redford.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the jewel of the nile', 48, 'The sense of romantic spark has waned and the prevalence of stereotypes has grown in Jewel of the Nile, although there is still plenty of swooning action for fans of the first adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jim andy the great beyond featuring a very special contractually obligated mention of tony clifton', 94, 'Jim & Andy: The Great Beyond offers a fascinating behind-the-scenes glimpse of method acting in action -- and one star''s journey toward something like personal acceptance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jingle all the way', 15, 'Arnold Schwarzenegger tries his best, but Jingle All the Way suffers from an uneven tone, shifting wildly from a would-be satire on materialism to an antic, slapstick yuk-fest.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('joan didion the center will not hold', 89, 'Joan Didion: The Center Will Not Hold pays tribute to an American literary legend with a richly personal perspective that should thrill devotees while enlightening newcomers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('joe strummer the future is unwritten', 89, 'Displaying Joe Strummer warts and all, The Future is Unwritten succeeds as both an engrossing documentary and a comprehensive examination of one of music''s most legendary figures.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('joe versus the volcano', 61, 'Joe Versus the Volcano erupts with plenty of screwball energy and thoughtful observations about living to the fullest, but its existential ambition may prove too goofy for some audiences.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('john carpenters ghosts of mars', 21, 'John Carpenter''s Ghosts of Mars is not one of Carpenter''s better movies, filled as it is with bad dialogue, bad acting, confusing flashbacks, and scenes that are more campy than scary.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('john carter', 52, 'While John Carter looks terrific and delivers its share of pulpy thrills, it also suffers from uneven pacing and occasionally incomprehensible plotting and characterization.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('john mulaney the sack lunch bunch', 96, 'With spectacular musical numbers, a smartly silly sensibility, and just the right amount of existential dread, John Mulaney & The Sack Lunch Bunch is a joyous reminder that kindness and comedy can in fact go hand in hand.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rambo rambo iv', 38, 'Sylvester Stallone knows how to stage action sequences, but the movie''s uneven pacing and excessive violence (even for the franchise) is more nauseating than entertaining.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('john wick chapter 2', 89, 'John Wick: Chapter 2 does what a sequel should -- which in this case means doubling down on the non-stop, thrillingly choreographed action that made its predecessor so much fun.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('johnny english reborn', 38, 'Arguably a marginal improvement on its mostly-forgotten predecessor, Johnny English Reborn nonetheless remains mired in broad, tired spy spoofing that wastes Rowan Atkinson''s once considerable comedic talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('joker', 68, 'Joker gives its infamous central character a chillingly plausible origin story that serves as a brilliant showcase for its star -- and a dark evolution for comics-inspired cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the joneses', 63, 'It doesn''t pursue its subversive premise as far as it should, but The Joneses benefits from its timely satire of consumer culture -- as well as a pair of strong performances from David Duchovny and Demi Moore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('journey to the west', 94, 'As sweet, silly, action-packed and ridiculous as director Steven Chow''s best work, Journey to the West serves up dazzling action sequences while playing its disparate elements against each other with thrilling abandon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('journeys end', 92, 'Journey''s End brings R.C. Sherriff''s 90-year-old play to the screen with thrilling power, thanks to director Saul Dibb''s hard-hitting urgency and brilliant work from a talented cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('joy', 61, 'Joy is anchored by a strong performance from Jennifer Lawrence, although director David O. Russell''s uncertain approach to its fascinating fact-based tale only sporadically sparks bursts of the titular emotion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('joyful noise', 32, 'Joyful Noise''s musical numbers are solidly entertaining, and it benefits from Queen Latifah and Dolly Parton''s sizable chemistry; unfortunately, they aren''t enough to make up for the rest of the film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jt leroy', 55, 'While it may leave some viewers wishing for a more in-depth exploration of its story and themes, J.T. Leroy offers a diverting dramatization of incredible real-life events.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('juanita', 81, 'Juanita''s refreshing journey of self-actualization may lead to a predictable destination, but a sterling star turn by Alfre Woodard gives this sojourn an invaluable spark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jungfrukällan the virgin spring', 87, 'The Virgin Spring marks one of Ingmar Bergman''s most controversial dramas, although its uncomfortable exploration of divine justice -- or lack thereof -- is undeniably thought-provoking.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('juno', 94, 'One of the brightest, funniest comedies of the year, Juno''s smart script and direction are matched by assured performances in a coming of age story with a 21st century twist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('jurassic world', 70, 'Jurassic World can''t match the original for sheer inventiveness and impact, but it works in its own right as an entertaining -- and visually dazzling -- popcorn thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('just getting started', 4, 'A thoroughly unfunny misfire, Just Getting Started manages the incredible feat of wasting more than a century of combined acting experience from its three talented leads.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('just like heaven', 55, 'Delightfully sweet like a lollipop, Just Like Heaven is a dreamy romantic comedy that may give you a toothache when it attempts to broach difficult end of life issues by throwing a cherry on top.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('justice league', 40, 'Justice League leaps over a number of DC movies, but its single bound isn''t enough to shed the murky aesthetic, thin characters, and chaotic action that continue to dog the franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kabluey', 84, 'An effecting treatise on modern alienation, Scott Prendergast''s story of a hapless loser who finds recognition by donning a featureless suit is full of whimsy and sorrow.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('katy perry part of me', 76, 'Katy Perry: Part of Me succeeds on the strengths of the pop star''s genuine likability, inspiring work ethic, and dazzling stage show, even if it plays somewhat like a PR puff piece at times.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kazaam', 5, 'Crafted from a mix of genre clichés, Kazaam doesn''t know what kind of film it wants to be, and Shaq''s larger-than-life charisma is stifled by rote filmmaking and an unimaginative story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('keane', 81, 'The scrutinizing camera angles of Keane might at first feel too close for comfort, but this powerful portrait of a man distraught by the abduction of his child plumbs the depths of mental illness and the corners of fleabag hotels in an intimate and touching examination of the seedier side of life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kedi', 98, 'Kedi is a cat fancier''s dream, but this thoughtful, beautifully filmed look at Istanbul''s street feline population offers absorbing viewing for filmgoers of any purr-suasion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kellys heroes', 78, 'Kelly''s Heroes subverts its World War II setting with pointed satirical commentary on modern military efforts, offering an entertaining hybrid of heist caper and battlefield action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kevin hart let me explain', 61, 'It''s ironically rather short on standup from Mr. Hart himself, but structural problems aside, Kevin Hart: Let Me Explain offers another example of why he''s achieved mainstream success on his own terms.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kids for cash', 92, 'Dispassionately presented yet frequently enraging, Kids for Cash uses the fallout from one horrific scandal to offer a thought-provoking critique of the justice system in general.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kill me three times', 16, 'Kill Me Three Times offers Simon Pegg an opportunity to play against type as a villain; unfortunately, its derivative storyline fails to offer much of anything to viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kill the irishman', 62, 'Kill the Irishman may not add much in the way of new ingredients to its crowded genre, but the admirable efforts of a solidly assembled cast add extra depth to a familiar story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kill your darlings', 77, 'Bolstered by the tremendous chemistry between Daniel Radcliffe and Dane DeHaan, Kill Your Darlings casts a vivid spotlight on an early chapter in the story of the Beat Generation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the killing fields', 93, 'Artfully composed, powerfully acted, and fueled by a powerful blend of anger and empathy, The Killing Fields is a career-defining triumph for director Roland Joffé and a masterpiece of American cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('killing ground', 75, 'Killing Ground unnerves and compels in equal measure with a grimly intense story that may be too disturbing for some but delivers a white-knuckle experience for fans of brutally realistic thrillers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kin', 34, 'Part family drama, part sci-fi adventure, Kin struggles to balance its narrative until a late twist that suggests it all might have worked better as the first episode of a TV series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('king kong', 84, 'Featuring state-of-the-art special effects, terrific performances, and a majestic sense of spectacle, Peter Jackson''s remake of King Kong is a potent epic that''s faithful to the spirit of the 1933 original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('king of california', 63, 'A quirky and often touching comedy about a mature teenager and her manic depressive father, King of California is a charming tale of familial relations and treasure hunting.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('king of devils island', 94, 'Scandinavian in the most bleakly satisfying way, King of Devil''s Island satisfies with a richly layered narrative and a typically strong performance from Stellan Skarsgard.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the king of kong a fistful of quarters', 97, 'The King of Kong is funny and compelling with more than a few poignant insights into human behavior. Director Seth Gordon presents the dueling King Kong players in all their obsessive complexity and with perfectly al dente observations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kinky boots', 56, 'Kinky Boots relies heavily on the Full Monty formula of Britcoms, while playing it too safe in a desperate attempt not to offend. Ejiofor''s performance is its redeeming virtue.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('klute', 93, 'Donald Sutherland is coolly commanding and Jane Fonda a force of nature in Klute, a cuttingly intelligent thriller that generates its most agonizing tension from its stars'' repartee.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('knight day', 52, 'It''s pure formula, but thanks to its breezy pace and a pair of charming performances from Tom Cruise and Cameron Diaz, Knight and Day offers some agreeably middle-of-the-road summer action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('knight of cups', 47, 'Knight of Cups finds Terrence Malick delving deeper into the painterly visual milieu he''s explored in recent efforts, but even hardcore fans may struggle with the diminishing narrative returns.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('knock knock', 37, 'Knock Knock brings a lot of talent to bear on its satirical approach to torture horror, but not effectively enough to overcome its repetitive story or misguidedly campy tone.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('knocked up', 90, 'Knocked Up is a hilarious, poignant and refreshing look at the rigors of courtship and child-rearing, with a sometimes raunchy, yet savvy script that is ably acted and directed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kon tiki', 81, 'A well-crafted retelling of an epic true story, Kon Tiki is a throwback to old-school adventure filmmaking that''s exciting and entertaining in spite of its by-the-book plotting.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kong skull island', 75, 'Offering exhilarating eye candy, solid acting, and a fast-paced story, Kong: Skull Island earns its spot in the movie monster''s mythos without ever matching up to the classic original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kpax', 42, 'For those who have seen One Flew Over the Cuckoo''s Nest or Starman, K-Pax may not hold anything new. The movie works best as a showcase for Kevin Spacey and Jeff Bridges.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('krampus', 66, 'Krampus is gory good fun for fans of non-traditional holiday horror with a fondness for Joe Dante''s B- movie classics, even if it doesn''t have quite the savage bite its concept calls for.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kung fu panda 3', 87, 'Kung Fu Panda 3 boasts the requisite visual splendor, but like its rotund protagonist, this sequel''s narrative is also surprisingly nimble, adding up to animated fun for the whole family.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('kaidan kwaidan ghost stories', 90, 'Exquisitely designed and fastidiously ornate, Masaki Kobayashi''s ambitious anthology operates less as a frightening example of horror and more as a meditative tribute to Japanese folklore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('la bamba', 91, 'Elevated by a perceptive performance by a perfectly cast Lou Diamond Phillips, La Bamba distills its subject''s creative energy -- and reflects his music''s enduring appeal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('la grande illusion grand illusion', 97, 'Jean Renoir''s Grand Illusion is a masterful anti-war statement, bringing humane insight and an undercurrent of ironic humor to an unusual relationship between captor and captive.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('la vie en rose la mome', 74, 'The set design and cinematography are impressive, but the real achievement of La Vie en Rose is Marion Cotillard''s mesmerizing, wholly convincing performance as Edith Piaf.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ladies in black', 88, 'Ladies in Black gleans socially relevant observations from Australian history with entertaining flair, embroidering a tale that touches on immigration and female empowerment with a fashionable pizazz.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lady and the tramp', 93, 'A nostalgic charmer, Lady and the Tramp''s token sweetness is mighty but the songs and richly colored animation are technically superb and make for a memorable experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lady eve', 100, 'A career highlight for Preston Sturges, The Lady Eve benefits from Barbara Stanwyck and Henry Fonda''s sparkling chemistry -- and a script that inspired countless battle-of-the-sexes comedies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lake placid', 47, 'Betty White''s delightful supporting turn may be worth the price of admission alone, but Lake Placid is swamped by a smarmy script and inability to deliver on the creature feature mayhem.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lambert stamp', 89, 'A sharp accounting of an era framed through the early adventures of the Who and the managers who helped make them famous, Lambert & Stamp should prove fascinating for fans and novices alike.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('land of mine under sandet', 92, 'Land of Mine uses an oft-forgotten chapter from the aftermath of World War II to tell a hard-hitting story whose period setting belies its timeless observations about bloodshed and forgiveness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('land of the dead', 74, 'George A. Romero''s latest entry in his much-vaunted Dead series is not as fresh as his genre-inventing original, Night of the Living Dead. But Land of the Dead does deliver on the gore and zombies-feasting-on-flesh action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('landline', 74, 'Landline''s talented cast -- and a fast-paced approach from director/co-writer Gillian Robespierre -- help this charming multi-generational dramedy overcome a familiar storyline.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('heartbreaker larnacoeur', 68, 'While definitely on the fluffier side of French comedy, Heartbreaker benefits from never taking itself too seriously -- and from the performance of the ever-charming Romain Duris.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last king of scotland', 87, 'Forest Whitaker''s performance as real-life megalomaniac dictator Idi Amin powers this fictionalized political thriller, a blunt and brutal tale about power and corruption.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last kiss', 46, 'You''ll either find the The Last Kiss to be a phony bore or a refreshing take about young 20-somethings at the crossroads between their carefree lifestyle and responsibility. Zach Braff and the rest of the appealing cast make the case for the latter.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('last man standing', 37, 'Last Man Standing''s brooding atmosphere and bursts of artfully arranged action prove intriguing yet ultimately insufficient substitutes for a consistently compelling story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last unicorn', 71, 'The Last Unicorn lacks the fluid animation to truly sparkle as an animated epic, but offbeat characters and an affecting story make it one of a kind for the true believers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lawrence of arabia', 98, 'The epic of all epics, Lawrence of Arabia cements director David Lean''s status in the filmmaking pantheon with nearly four hours of grand scope, brilliant performances, and beautiful cinematography.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('le cercle rouge', 95, 'Melville is at the top of his game, giving us his next-to-last entry into the world of deception, crime, and extreme suspense that made him a maestro of the French heist genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('le weekend', 89, 'Topped with bittersweet humor but possessing surprisingly thorny depths, Le Week-End offers a sophisticated, well-acted portrait of late-life struggles and long-term marriage.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('leap', 42, 'From its bland story to its unremarkable animation, Leap! does little to distinguish itself from a long list of like-minded -- and superior -- family-friendly alternatives.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('leap year año bisiesto', 92, 'Unpredictable, gripping, and ultimately haunting, Leap Year uses a couple''s fraught emotional journey as the narrative fuel for a probing look at societal mores and human needs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('leatherface', 30, 'Leatherface may wear the skin of a Texas Chainsaw Massacre prequel, but it proves gutless as an origin story and finds little invention in the horror tropes it''s cannibalizing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('leave it to beaver', 21, 'Declining to update the television series'' sensibility for modern audiences while lacking in its requisite charm, Leave it to Beaver should have just left these characters in the past.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('leave no trace', 100, 'Leave No Trace takes an effectively low-key approach to a potentially sensationalistic story -- and further benefits from brilliant work by Ben Foster and Thomasin McKenzie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the legend of bagger vance', 43, 'Despite the talent involved in The Legend of Bagger Vance, performances are hindered by an inadequate screenplay full of flat characters and bad dialogue. Also, not much happens, and some critics are offended by how the film glosses over issues of racism.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('legends of the fall', 58, 'Featuring a swoon-worthy star turn by Brad Pitt, Legends of the Fall''s painterly photography and epic sweep often compensate for its lack of narrative momentum and glut of melodramatic twists.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lemony snickets a series of unfortunate events', 72, 'Although it softens the nasty edges of its source material, Lemony Snicket''s A Series of Unfortunate Events is a gothic visual treat, and it features a hilariously manic turn from Jim Carrey as the evil Count Olaf.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lenfant', 85, 'The Dardennes continue to excel at presenting works of rigorous naturalism, with detached observations of authentic characters that nevertheless resonate with complex moral issues.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('léon the professional', 74, 'Pivoting on the unusual relationship between seasoned hitman and his 12-year-old apprentice -- a breakout turn by young Natalie Portman -- Luc Besson''s Léon is a stylish and oddly affecting thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('less than zero', 50, 'A couple of standout performances -- notably Robert Downey, Jr. and James Spader -- and a killer soundtrack can''t quite elevate a somewhat superficial adaptation of Bret Easton Ellis'' story of drugged-out LA rich kids.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('let me in', 88, 'Similar to the original in all the right ways -- but with enough changes to stand on its own -- Let Me In is the rare Hollywood remake that doesn''t add insult to inspiration.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('let the fire burn', 98, 'Smartly edited and heartbreakingly compelling, Let the Fire Burn uses archival footage to uncover a troubling -- and still deeply resonant -- chapter in American history.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lethal weapon 2', 82, 'Lethal Weapon 2 may sport a thin plot typical of action fare, but its combination of humor and adrenaline, along with the chemistry between its leads, make this a playful, entertaining sequel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lethal weapon 3', 60, 'Murtaugh and Riggs remain an appealing partnership, but Lethal Weapon 3 struggles to give them a worthy new adventure as it cranks up the camp along with the mean-spiritedness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('letters from iwo jima', 91, 'A powerfully humanistic portrayal of the perils of war, this companion piece to Flags of our Fathers is potent and thought-provoking, and it demonstrates Clint Eastwood''s maturity as a director.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('liberal arts', 71, 'While it''s hard not to wish it had a little more bite, Liberal Arts ultimately succeeds as a good-natured -- and surprisingly clever -- look at the addictive pull of nostalgia for our youth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('licence to kill', 78, 'License to Kill is darker than many of the other Bond entries, with Timothy Dalton playing the character with intensity, but it still has some solid chases and fight scenes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('life of pi', 87, 'A 3D adaptation of a supposedly "unfilmable" book, Ang Lee''s Life of Pi achieves the near impossible -- it''s an astonishing technical achievement that''s also emotionally rewarding.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('life', 64, 'Life may frustrate viewers seeking a James Dean biopic with its subject''s intensity, but it remains a diverting, well-acted effort assembled with admirable craft and ambition.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the life and death of colonel blimp', 96, 'A moving evocation of both British values and the passage of time, The Life and Death of Colonel Blimp is an epic portrait of a singular character by Powell and Pressburger.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the life aquatic with steve zissou', 56, 'Much like the titular oceanographer, The Life Aquatic with Steve Zissou''s overt irony may come off as smug and artificial -- but for fans of Wes Anderson''s unique brand of whimsy it might be worth the dive.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('life of the party', 38, 'Life of the Party''s good-natured humor and abundance of onscreen talent aren''t enough to make up for jumbled direction and a script that misses far more often than it hits.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lights out', 76, 'Lights Out makes skillful use of sturdy genre tropes -- and some terrific performances -- for an unsettling, fright-filled experience that delivers superior chills without skimping on story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lila eve', 40, 'Lila & Eve gets some mileage out of its formidable stars, with Viola Davis in particular proving that she will commandingly commit to any material, but this is a revenge flick served stale due to a lackluster script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lincoln lawyer', 83, 'It doesn''t offer any twists on the predictable courtroom thriller formula, but with a charming Matthew McConaughey leading its solid cast, The Lincoln Lawyer offers briskly enjoyable entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('listen up philip', 82, 'As thought-provoking as it is uncompromising, Listen Up Philip finds writer-director Alex Ross Perry taking a creative step forward while hearkening back to classic neurotic comedies of ''70s cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little', 46, 'A disappointingly uneven but overall agreeable spin on a familiar formula, Little benefits from a big heart -- and a story that makes good use of its talented, well-matched cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little buddha', 68, 'Little Buddha''s storytelling may be too childlike to best service its audacious plot, but Bernardo Bertolucci''s direction and Vittorio Storaro''s cinematography conspire to deliver a visually strong epic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little men', 97, 'Little Men takes a compassionate look at the ways in which adult problems impact childhood friendships -- and offers another affecting New York drama from director Ira Sachs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little miss sunshine', 91, 'Little Miss Sunshine succeeds thanks to a strong ensemble cast that includes Greg Kinnear, Steve Carell, Toni Collette, Alan Arkin, and Abigail Breslin, as well as a delightfully funny script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little sister', 94, 'Little Sister subverts indie drama expectations with a refreshingly off-kilter look at family dynamics that makes its points through solid characterizations and earnest effort.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('little white lies', 42, 'Little White Lies luxuriates in the company of its impressive cast and small-scale dilemmas to its detriment, yielding a comedy of initial charm that meanders into boredom.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('live by night', 35, 'Live by Night boasts visual style and an impressive cast, but they''re lost in a would-be crime saga that finds producer, director, and star Ben Affleck revisiting familiar themes to diminishing effect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('live die repeat edge of tomorrow', 91, 'Gripping, well-acted, funny, and clever, Edge of Tomorrow offers entertaining proof that Tom Cruise is still more than capable of shouldering the weight of a blockbuster action thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('live free or die hard', 82, 'Live Free or Die Hard may be preposterous, but it''s an efficient, action-packed summer popcorn flick with thrilling stunts and a commanding performance by Bruce Willis. Fans of the previous Die Hard films will not be disappointed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('living in oblivion', 88, 'Living in Oblivion dives into the folly of filmmaking with a sharp satire that sends up indie cinema while working as an entertaining independent picture in its own right.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lo and behold reveries of the connected world', 93, 'Lo and Behold: Reveries of the Connected World finds Werner Herzog bringing his distinctive documentarian gifts to bear on a timely topic with typically thought-provoking results.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('logan', 93, 'Hugh Jackman makes the most of his final outing as Wolverine with a gritty, nuanced performance in a violent but surprisingly thoughtful superhero action film that defies genre conventions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('logan lucky', 92, 'High-octane fun that''s smartly assembled without putting on airs, Logan Lucky marks a welcome end to Steven Soderbergh''s retirement -- and proves he hasn''t lost his ability to entertain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lola versus', 36, 'It''s fun to see Greta Gerwig mature her acting career but Lola Versus -- with its unpleasant characters and completely familiar script -- does not succeed as her first major leading role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('london has fallen', 28, 'London Has Fallen traps a talented cast -- and all who dare to see it -- in a mid-1990s basic-cable nightmare of a film loaded with xenophobia and threadbare action-thriller clichés.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the loneliness of the long distance runner', 73, 'Dry and full of angst, this British New Wave classic features potent social commentary and a star making performance by Tom Courtenay as a textbook example of the "angry young man."');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('long way north tout en haut du monde', 98, 'Smart and refreshingly free of sentimentality, Long Way North takes viewers on a beautifully animated adventure grounded in fully realized characters and genuine emotion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('look whos talking', 56, 'Look Who''s Talking holds some appeal thanks to its affable stars and Amy Heckerling''s energetic direction, but a silly script doesn''t allow wit to get a word in edgewise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('looking glass', 21, 'Looking Glass gives Nicolas Cage a chance to turn in an atypically understated performance, but this is still a suspense thriller with a fatal dearth of suspense or thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lord of the rings', 52, 'Ralph Bakshi''s valiant attempt at rendering Tolkein''s magnum opus in rotoscope never lives up to the grandeur of its source material, with a compressed running time that flattens the sweeping story and experimental animation that is more bizarre than magical.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lore', 94, 'Newcomer Saskia Rosendahl gives an astonishingly assured performance in the title role, and director Cate Shortland establishes a delicate, disturbingly ominous tone in the powerful World War II drama Lore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lorenzos oil', 92, 'A harrowing tribute to the heroism of parental love, Lorenzo''s Oil is kept from abject misery by George Miller''s sensitive direction and outstanding performances from Nick Nolte and Susan Sarandon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lost boys', 76, 'Flawed but eminently watchable, Joel Schumacher''s teen vampire thriller blends horror, humor, and plenty of visual style with standout performances from a cast full of young 1980s stars.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lost highway', 61, 'Marking a further escalation in David Lynch''s surrealist style, Lost Highway is a foreboding mystery that arguably leads to a dead end, although it is signposted throughout with some of the director''s most haunting images yet.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lost in la mancha', 94, 'A remarkable behind-the-scenes look at a movie that wasn''t, Lost in La Mancha is an incisive, entertaining document of the difficulties inherent in the moviemaking process.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lost river', 31, 'Lost River suggests that debuting writer-director Ryan Gosling may have a bright future as a filmmaker, but it doesn''t hold together well enough to recommend on its own merit.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lost weekend', 97, 'Director Billy Wilder''s unflinchingly honest look at the effects of alcoholism may have had some of its impact blunted by time, but it remains a powerful and remarkably prescient film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lost world jurassic park', 53, 'The Lost World demonstrates how far CG effects have come in the four years since Jurassic Park; unfortunately, it also proves how difficult it can be to put together a truly compelling sequel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('loudquietloud a film about the pixies', 68, 'Although it''ll be primarily of interest to longtime fans, LoudQUIETloud: A Film About the Pixies also serves as a decent introduction to the band''s music and enduring appeal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('love and death', 100, 'Woody Allen plunks his neurotic persona into a Tolstoy pastiche and yields one of his funniest films, brimming with slapstick ingenuity and a literary inquiry into subjects as momentous as Love and Death.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('love gilda', 88, 'Love, Gilda pays gentle, unequivocal tribute to its subject with more than enough of her genuine spirit to compensate for a lack of critical distance or truly fresh insight.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('love is strange', 93, 'Held aloft by remarkable performances from John Lithgow and Alfred Molina, Love Is Strange serves as a graceful tribute to the beauty of commitment in the face of adversity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('love simon', 91, 'Love, Simon hits its coming-of-age beats more deftly than many entries in this well-traveled genre -- and represents an overdue, if not entirely successful, milestone of inclusion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('love the coopers', 18, 'Love the Coopers has a talented cast and a uniquely bittersweet blend of holiday cheer in its better moments, but they''re all let down by a script content to settle for cloying smarm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('loving', 89, 'Loving takes an understated approach to telling a painful -- and still relevant -- real-life tale, with sensitive performances breathing additional life into a superlative historical drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lu over the wall yoake tsugeru rû no uta', 78, 'Lu Over the Wall can be more fun to watch than to follow, but director Masaaki Yuasa''s distinctive visual style offers colorful compensation for an occasionally scattered story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('lucky numbers', 22, 'Nora Ephron''s attempt at dark comedy is an uneven product, both in terms of the direction and the acting. The characters are unlikable to the point where you don''t care what happens to them, and Ephron condescends to the material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('m butterfly', 43, 'David Cronenberg reins in his provocative sensibility and handles delicate material with restraint, yielding a disappointing adaptation that flattens M. Butterfly into a tedious soap opera.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('macbeth', 80, 'Faithful to the source material without sacrificing its own cinematic flair, Justin Kurzel''s Macbeth rises on the strength of a mesmerizing Michael Fassbender performance to join the upper echelon of big-screen Shakespeare adaptations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mad max', 90, 'Staging the improbable car stunts and crashes to perfection, director George Miller succeeds completely in bringing the violent, post-apocalyptic world of Mad Max to visceral life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('madagascar', 54, 'Though its story is problematic in spots and its humor is hit-or-miss for the adult crowd, Madagascar boasts impressive visuals and enough spunky charm to keep children entertained.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the madness of king george', 93, 'Thanks largely to stellar all-around performances from a talented cast, The Madness of King George is a funny, entertaining, and immensely likable adaptation of the eponymous stage production.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('magic mike xxl', 65, 'Magic Mike XXL has enough narrative thrust and beefy charm to deliver another helping of well-oiled entertainment, even if this sequel isn''t quite as pleasurable as its predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('magician the astonishing life and work of orson welles', 73, 'It may not quite live up to the superlative in its title, but Magician: The Astonishing Life and Work of Orson Welles serves as a passable primer for those seeking an introduction to the legendary filmmaker.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('major league', 83, 'Major League may be predictable and formulaic, but buoyed by the script''s light, silly humor -- not to mention the well-built sports action sequences and funny performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mala noche', 96, 'Mala Noche is a raw and gritty portrait of desire, doomed romance, and rejection -- and marks debuting director Gus Van Sant as a filmmaker with a gratifyingly personal touch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('man of tai chi', 70, 'It may not be groundbreaking, but Man of Tai Chi represents an agreeably old-fashioned picture for martial arts fans -- and a solid debut for first-time director Keanu Reeves.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('man of the year', 22, 'Weakened by second-half attempts at thriller and romance, this presidential comedy also fails to hit any sharp political notes, resulting in a confused and unsatisfying mess.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man who shot liberty valance', 94, 'Featuring a trio of classic leading men and a rich story captured by a director at the peak of his craft, The Man Who Shot Liberty Valance is one of the finest Westerns ever filmed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('man with a movie camera', 97, 'Groundbreaking in its exploration of the medium, Man with a Movie Camera is proof that cinema in and of itself can be a source of grand entertainment and sociological value.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mandela long walk to freedom', 61, 'It might be too respectful to truly soar, but there''s no denying Idris Elba''s impressive work in Mandela: Long Walk to Freedom -- or the inspirational power of the life it depicts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('manufactured landscapes', 84, 'Manufactured Landscapes leaves the work of drawing conclusions mostly to the viewer, although the imagery makes director Jennifer Baichwal''s arguments well enough on its own.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('marathon man', 81, 'Marathon Man runs the gamut from patient mystery to pulse-pounding thriller, aided by Laurence Oliver''s coldly terrifying performance and a brainy script by William Goldman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mars attacks', 54, 'Tim Burton''s alien invasion spoof faithfully recreates the wooden characters and schlocky story of cheesy ''50s sci-fi and Ed Wood movies -- perhaps a little too faithfully for audiences.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('marvels the avengers', 92, 'Thanks to a script that emphasizes its heroes'' humanity and a wealth of superpowered set pieces, The Avengers lives up to its hype and raises the bar for Marvel at the movies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mary shelley', 38, 'Mary Shelley smooths out its subject''s fascinating life and fails to communicate the spark of her classic work, undermining fine period detail and a solid Elle Fanning performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('masters of the universe', 17, 'Masters of the Universe is a slapdash adaptation of the He-Man mythos that can''t overcome its cynical lack of raison d''etre, no matter how admirably Frank Langella throws himself into the role of Skeletor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('maudie', 89, 'Maudie''s talented cast -- particularly Sally Hawkins in the title role -- breathe much-needed depth into a story that only skims the surface of a fascinating life and talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('max', 38, 'Max has good intentions and tries to hearken back to classic family-friendly features, but its disjointed, manipulative plot overwhelms the efforts of its talented human and canine stars.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('maze runner the death cure', 43, 'Maze Runner: The Death Cure may offer closure to fans of the franchise, but for anyone who hasn''t already been hooked, this bloated final installment is best left unseen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mcfarland usa', 81, 'Disney''s inspirational sports drama formula might be old hat, but McFarland, USA proves it still works -- especially with a talented director and eminently likable star in the mix.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mean dreams', 78, 'Mean Dreams enlivens its familiar premise with rich details, strong performances from a talented cast playing fully realized characters, and sensitive work from director Nathan Morlando.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mean streets', 95, 'Mean Streets is a powerful tale of urban sin and guilt that marks Scorsese''s arrival as an important cinematic voice and features electrifying performances from Harvey Keitel and Robert De Niro.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('meatballs', 72, 'Meatballs is a summer camp comedy with few surprises, but Bill Murray''s riffing adds a spark that sets it apart from numerous subpar entries in a frequently uninspired genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('meet the parents', 84, 'Despite sometimes sitcom-like execution, Meet the Parents is a hilarious look at familial relationships that works mostly because the chemistry between its two leads is so effective.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('meet the patels', 87, 'Meet the Patels works on multiple levels, offering an affably entertaining documentary about one man looking for love while posing thoughtful questions about cultural assimilation and modern romance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('megamind', 72, 'It regurgitates plot points from earlier animated efforts, and isn''t quite as funny as it should be, but a top-shelf voice cast and strong visuals help make Megamind a pleasant, if unspectacular, diversion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('melancholia', 79, 'Melancholia''s dramatic tricks are more obvious than they should be, but this is otherwise a showcase for Kirsten Dunst''s acting and for Lars von Trier''s profound, visceral vision of depression and destruction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('menashe', 96, 'Menashe offers an intriguing look at a culture whose unfamiliarity to many viewers will be rendered irrelevant by the story''s universally affecting themes and thoughtful approach.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the mexican', 54, 'Though The Mexican makes a good attempt at originality, its ponderous length makes it wear out its welcome. Also, those looking forward to seeing Roberts and Pitt paired up may end up disappointed, as they are kept apart for most of the movie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('miami vice', 47, 'Miami Vice is beautifully shot but the lead characters lack the charisma of their TV series counterparts, and the underdeveloped story is well below the standards of Michael Mann''s better films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('michael clayton', 91, 'Michael Clayton is one of the most sharply scripted films of 2007, with an engrossing premise and faultless acting. Director Tony Gilroy succeeds not only in capturing the audience''s attention, but holding it until the credits roll.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('michael collins', 77, 'As impressively ambitious as it is satisfyingly impactful, Michael Collins honors its subject''s remarkable achievements with a magnetic performance from Liam Neeson in the title role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('michael jacksons this is it', 81, 'While it may not be the definitive concert film (or the insightful backstage look) some will hope for, Michael Jackson''s This Is It packs more than enough entertainment value to live up to its ambitious title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('midnight cowboy', 88, 'John Schlesinger''s gritty, unrelentingly bleak look at the seedy underbelly of urban American life is undeniably disturbing, but Dustin Hoffman and Jon Voight''s performances make it difficult to turn away.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('midnight in the garden of good and evil', 50, 'Clint Eastwood''s spare directorial style proves an ill fit for this Southern potboiler, which dutifully trudges through its mystery while remaining disinterested in the cultural flourishes that gave its source material its sense of intrigue.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('midnights children', 41, 'Though Midnight''s Children is beautiful to look at and poignant in spots, its script is too indulgent and Deepa Mehta''s direction, though ambitious, fails to bring the story together cohesively.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mifune the last samurai', 83, 'Capturing the breadth of Toshiro Mifune''s storied career, if not fully reckoning with the depth of the man, The Last Samurai is a compelling celebration of one of cinema''s greatest stars.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the mighty quinn', 88, 'A deft hybrid of laughs, espionage, and music, The Mighty Quinn is a smart, pleasant entertainment that offers an early example of Denzel Washington''s onscreen magnetism.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mike and dave need wedding dates', 38, 'Mike and Dave Need Wedding Dates benefits from the screwball premise and the efforts of a game cast, even if the sporadically hilarious results don''t quite live up to either.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mile 22', 23, 'Mile 22 lets the bullets fly -- and not much else -- in a thrill-deficient action thriller whose title proves sadly fitting for a film that feels close to a marathon endurance test.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('miles ahead', 74, 'Miles Ahead is worth watching for Don Cheadle''s strong work on both sides of the camera, even if this unconventional biopic doesn''t quite capture its subject''s timeless appeal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('millennium actress sennen joyû', 93, 'The story of an aging movie actress'' complicated personal saga unfolds in this sophisticated anime film that deftly blurs memory and make-believe into a meditation on the nature of cinema itself.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('millers crossing', 92, 'Though possibly more notable for its distinctive style than an airtight story, this Coen brothers take on the classic gangster flick features sharp dialogue, impressive cinematography, and a typically quirky cast of characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('million dollar arm', 65, 'Pleasant to a fault, Million Dollar Arm is a middle-of-the-plate pitch that coasts on Jon Hamm''s considerable charm without adding any truly original curves to Disney''s inspirational sports formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('million dollar baby', 91, 'Clint Eastwood''s assured direction - combined with knockout performances from Hilary Swank and Morgan Freeman - help Million Dollar Baby to transcend its clichés, and the result is deeply heartfelt and moving.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last mimzy', 55, 'The Last Mimzy makes efforts to be a fun children''s movie, but unsuccessfully juggles too many genres and subplots -- eventually settling as an unfocused, slightly dull affair.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('minions', 55, 'The Minions'' brightly colored brand of gibberish-fueled insanity stretches to feature length in their self-titled Despicable Me spinoff, with uneven but often hilarious results.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('miracle on 34th street', 96, 'Irrefutable proof that gentle sentimentalism can be the chief ingredient in a wonderful film, Miracle on 34th Street delivers a warm holiday message without resorting to treacle.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('miracles from heaven', 45, 'Miracles from Heaven makes the most out of an outstanding performance from Jennifer Garner, but it isn''t quite enough to keep this faith-based drama from preaching to the choir.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('miral', 17, 'Miscast and dramatically inert, Miral is a thin chronicle of geopolitical history that offers only shallow insight into the Israeli-Palestinian conflict and characters with even less depth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mirror mirror', 50, 'Like most of Tarsem Singh''s films, Mirror Mirror is undeniably beautiful -- but its treatment of the age-old Snow White fable lacks enough depth or originality to set it apart from the countless other adaptations of the tale.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('miss peregrines home for peculiar children', 64, 'Miss Peregrine''s Home for Peculiar Children proves a suitable match for Tim Burton''s distinctive style, even if it''s on stronger footing as a visual experience than a narrative one.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('miss you already', 71, 'Miss You Already isn''t shy about going for filmgoers'' tear ducts, but its solid script and talented cast are often powerful enough to make up for its more manipulative moments.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mission impossible iii', 71, 'Fast-paced, with eye-popping stunts and special effects, the latest Mission: Impossible installment delivers everything an action fan could ask for. A thrilling summer popcorn flick.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mission impossible fallout', 97, 'Fast, sleek, and fun, Mission: Impossible - Fallout lives up to the "impossible" part of its name by setting yet another high mark for insane set pieces in a franchise full of them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mo better blues', 71, 'Mo'' Better Blues is rich with vibrant hues and Denzel Washington''s impassioned performance, although its straightforward telling lacks the political punch fans expect from a Spike Lee joint.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('moana', 95, 'With a title character as three-dimensional as its lush animation and a story that adds fresh depth to Disney''s time-tested formula, Moana is truly a family-friendly adventure for the ages.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mollys game', 81, 'Powered by an intriguing story and a pair of outstanding performances from Jessica Chastain and Idris Elba, Molly''s Game marks a solid debut for writer-director Aaron Sorkin.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mommie dearest', 49, 'Mommie Dearest certainly doesn''t lack for conviction, and neither does Faye Dunaway''s legendary performance as a wire-wielding monster; unfortunately, the movie is too campy and undisciplined to transcend guilty pleasure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mondays in the sun los lunes al sol', 80, 'Javier Bardem gives an outstanding performance in this hought-provoking (though occasionally plodding) movie about the effects of unemployment on a group of former shipyard workers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('money monster', 59, 'Money Monster''s strong cast and solidly written story ride a timely wave of socioeconomic anger that''s powerful enough to overcome an occasionally muddled approach to its worthy themes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('monsieur verdoux', 97, 'Charles Chaplin adds an undercurrent of malice to his comedic persona in Monsieur Verdoux, an unsettling satire that subverts the tramp''s image to perversely amusing effect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('monster', 81, 'Charlize Theron gives a searing, deglamorized performance as real life serial killer Aileen Wuornos in Monster, an intense, disquieting portrait of a profoundly damaged soul.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('monster family', 10, 'Monster Family promises a family-friendly animated monster mash, but succeeds only in delivering a viewing experience so lackluster that parents may find it genuinely frightening.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('monster hunt zhuo yao ji', 66, 'This freewheeling adventure may be too daffy for some audiences, but flamboyant creature designs and an irrepressible sense of playfulness make Monster Hunt undeniably fun.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('more than a game', 71, 'Though the film may not delve as deep as some would prefer, More Than a Game is an inspiring documentary featuring likable youngsters, a positive message, and some exciting in-game footage.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mortal engines', 26, 'Mortal Engines has no shortage of eye-catching special effects, but lacks enough high-octane narrative fuel to give this futuristic fantasy sufficient cinematic combustion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mortal kombat', 48, 'Despite an effective otherwordly atmosphere and appropriately cheesy visuals, Mortal Kombat suffers from its poorly constructed plot, laughable dialogue, and subpar acting.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mortal kombat annihilation', 2, 'With its shallow characters, low budget special effects, and mindless fight scenes, Mortal Kombat - Annihilation offers minimal plot development and manages to underachieve the low bar set by its predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('moscow on the hudson', 86, 'With Robin Williams'' affecting portrayal as a Russian immigrant at the center of its fish-out-of-water story, Moscow on The Hudson soars with an abundance of laughs and heart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mother and child', 78, 'Though it occasionally veers into unnecessary melodrama, Mother and Child benefits from a stellar cast and writer-director Rodrigo Garcia''s finely detailed, bravely unsentimental script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mother of tears the third mother', 48, 'As excessive and ketchup laden as predecessors Suspiria and Inferno, Dario Argento''s Mother of Tears completes the trilogy with the same baroque grandeur and soggy 1970s sensibilities.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('la moustache', 86, 'Though the premise may be modest on the surface, Carrere uses a man and his mustache that may or may not exist as a springboard into psychological suspense and unsettling questions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('moving midway', 100, 'This strange, heartfelt documentary from film critic Godfrey Cheshire is a fascinating examination of his family roots, as well as an evocative meditation on the complexities of the South.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mowgli legend of the jungle', 53, 'Mowgli: Legend of the Jungle brings impressive special effects to bear on the darker side of its classic source material, but loses track of the story''s heart along the way.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mr mrs smith', 60, 'Although this action-romance suffers from weak writing and one too many explosions, the chemistry generated by onscreen couple Pitt and Jolie is palpable enough to make this a thoroughly enjoyable summer action flick.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mr magoo', 7, 'Leslie Nielsen''s affability can''t save this dunderheaded update of Mr. Magoo, which delivers a stream of slapstick gags so lame that audiences will feel like they''ve stepped on a rake.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mr nobody', 68, 'Mr. Nobody''s narrative tangles may bedevil as much as they entertain, but its big ambitions and absorbing visuals make for an intriguing addition to director Jaco Van Dormael''s filmography.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mr saturday night', 58, 'Billy Crystal''s flawed directorial debut can''t seem to decide whether it wants the viewer to love its protagonist or hate him, but it features fine work from Crystal and his co-stars.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mr wrong', 7, 'A mean-spirited joke without a punchline, Mr. Wrong is so painfully unfunny that Ellen DeGeneres and Bill Pullman''s lack of chemistry feels like a total drag despite being the point.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mrs brown', 92, 'Thanks to some top notch acting, the chemistry between its stars, and a witty, thoughtful script, Mrs. Brown delivers a nuanced and entertaining, if not entirely factual, account of a seldom explored historical relationship.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mrs hyde madame hyde', 58, 'Madame Hyde has a handful of interesting ideas and a typically radiant performance from Isabelle Huppert, although it''s all still a little less than the sum of its parts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('much ado about nothing', 86, 'Lighthearted to a fault, Much Ado About Nothing''s giddy energy and intimate charm make for an entertaining romantic comedy -- and a Shakespearean adaptation that''s hard to resist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mud', 97, 'Bolstered by a strong performance from Matthew McConaughey in the title role, Mud offers an engaging Southern drama that manages to stay sweet and heartwarming without being sappy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mugabe and the white african', 97, 'As much legal thriller as objective documentary, this account of a farmer''s battle with Zimbabwe''s regime serves as a powerful and emotional attack upon President Mugabe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mulholland drive', 83, 'David Lynch''s dreamlike and mysterious Mulholland Drive is a twisty neo-noir with an unconventional structure that features a mesmirizing performance from Naomi Watts as a woman on the dark fringes of Hollywood.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('munich', 78, 'Munich can''t quite achieve its lofty goals, but this thrilling, politically even-handed look at the fallout from an intractable political conflict is still well worth watching.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the muppet christmas carol', 76, 'It may not be the finest version of Charles Dickens'' tale to grace the screen, but The Muppet Christmas Carol is funny and heartwarming, and serves as a good introduction to the story for young viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('muppet treasure island', 73, 'Though less Muppet-centric than the original trilogy, Muppet Treasure Island is an energetic, cheerful take on Robert Louis Stevenson''s classic adventure, with typically solid gags.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('muppets from space', 63, 'If Muppets from Space lacks the magic and wit of its cinematic predecessors, this pleasingly silly space romp is funny and clever enough to make for better-than-average family entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('muppets most wanted', 80, 'While it may not reach the delirious heights of The Muppets, Muppets Most Wanted still packs in enough clever gags, catchy songs, and celebrity cameos to satisfy fans of all ages.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the muppets take manhattan', 83, 'If it''s not quite as sharp as The Muppet Movie, The Muppets Take Manhattan is still a smart, delightfully old-fashioned tale that follows the formula established by the first two movies -- a madcap adventure assisted by a huge group of human stars.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('murder on the orient express', 90, 'Murder, intrigue, and a star-studded cast make this stylish production of Murder on the Orient Express one of the best Agatha Christie adaptations to see the silver screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('murder on the orient express', 61, 'Stylish production and an all-star ensemble keep this Murder on the Orient Express from running off the rails, even if it never quite builds up to its classic predecessor''s illustrious head of steam.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('muscle shoals', 97, 'Essential for soul fans and entertaining for novices, Muscle Shoals offers a compelling, warts-and-all glimpse at one of the most fascinating stories in modern American music.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('music and lyrics', 63, 'Music & Lyrics is a light and pleasant romantic comedy that succeeds because of the considerable charm of its co-stars. The music segments featuring Hugh Grant are worth the price of admission.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('music from the inside out', 82, 'Music from the Inside Out lets the act of making music -- and the work that goes into it -- speak for itself, offering an engaging look at the life of an orchestra member along the way.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mute', 21, 'Visually polished but narratively derivative and overall muddled, Mute is a would-be sci-fi epic whose title serves as an unfortunate guide to how it might be best enjoyed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my big fat greek wedding', 76, 'Though it sometimes feels like a television sitcom, My Big Fat Greek Wedding is good-hearted, lovable, and delightfully eccentric, with a sharp script and lead performance from Nia Vardalos.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my big fat greek wedding 2', 27, 'My Big Fat Greek Wedding 2 is as sweet and harmless as the original, but its collection of sitcom gags and stereotypes never coalesces into anything resembling a story with a purpose.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my date with drew', 71, 'A love-it-or-hate-it stalkerazzi documentary, My Date With Drew effectively draws on America''s celeb-obsessed pop culture so that viewers either unabashedly identify with it, or are filing restraining orders on Drew Barrymore''s behalf.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my dinner with hervé', 83, 'My Dinner with Hervé offers a standard narrative on celebrity and infamy, but formidable performances by Peter Dinklage and Jamie Dornan find the dimensionality and pathos of Hervé Villechaize the man.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my dog skip', 73, 'Critics say My Dog Skip is cute, wholesome entertainment for the family. It''s especially designed to appeal to your sentiment, but you might find yourself choking up just the same.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my entire high school sinking into the sea', 85, 'My Entire High School Sinking Into the Sea''s attention-getting visual style matches debuting writer-director Dash Shaw''s distinctive narrative approach -- and signals a bright future for a promising talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my journey through french cinema voyage à travers le cinéma français', 100, 'Bertrand Tavernier is an engaging guide through this Journey Through French Cinema, curating a revelatory tour through his homeland''s film history with a personal touch that will delight movie fans and the culturally curious alike.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my kid could paint that', 94, 'Director Amir Bar-Lev grapples with exposing the authenticity of four-year-old Marla''s paintings at the sake of burdening her publicly shamed family to transfixing results.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my own private idaho', 80, 'A tantalizing glimpse of a talented director and his stars all at the top of their respective games, Gus Van Sant''s loose reworking of Henry IV is smart, sad and audacious.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('my son my son what have ye done', 49, 'Enigmatic and digressive, this mystical potboiler possesses director Werner Herzog''s penchant for offbeat atmosphere, but lacks the absurdist humor and profundity that makes his previous trips into madness compelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mysteries of lisbon', 86, 'Mysteries of Lisbon achieves an epic heft through an unhurried pace and lush photography, its beguiling episodes culminating in an impressive whole that justifies a lengthy runtime.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the mysteries of pittsburgh', 12, 'A listless interpretation of Michael Chabon''s first novel, Mysteries of Pittsburgh features none of the source material''s charm, but has coming-of-age film cliches in abundance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('mystery road', 92, 'Mystery Road evokes classic Westerns while using its Australian outback setting to delve into a surprisingly layered -- and powerfully impactful -- array of social issues.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nacho libre', 40, 'At times hilarious, but other times offensive, Director Jared Hess is unable to recapture the collective charisma of his Napoleon characters, instead relying on a one-joke concept that runs out of steam. Sure to entertain the adolescents, however.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nancy drew', 50, 'Emma Roberts is bubbly and charming as Nancy Drew, the junior detective. But despite her best efforts, Nancy Drew still lacks excitement, surprise, and compelling secondary characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('national lampoons animal house', 90, 'The talents of director John Landis and Saturday Night Live''s irrepressible John Belushi conspired to create a rambunctious, subversive college comedy that continues to resonate.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('national lampoons vacation', 93, 'Blessed by a brilliantly befuddled star turn from Chevy Chase, National Lampoon''s Vacation is one of the more consistent -- and thoroughly quotable -- screwball comedies of the 1980s.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('national velvet', 100, 'National Velvet makes the most of a breakout performance from Elizabeth Taylor, delivering a timeless family-friendly tearjerker that avoids straying into the sentimental.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('natural born killers', 48, 'Natural Born Killers explodes off the screen with style, but its satire is too blunt to offer any fresh insight into celebrity or crime -- pummeling the audience with depravity until the effect becomes deadening.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nerve', 67, 'Nerve''s fast pace and charming leads help overcome a number of fundamental flaws, adding up to a teen-friendly thriller with enough energy to occasionally offset its muddled execution.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('network', 91, 'Driven by populist fury and elevated by strong direction, powerful acting, and an intelligent script, Network''s searing satire of ratings-driven news remains sadly relevant more than four decades later.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('never apologize a personal visit with lindsay anderson', 67, 'Essentially a stage production of Malcolm Macdowell musing over his departed friend, and brit director Lindsey Anderson. Macdowell makes for an engaging raconteur, but only for Anderson fans.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('never let me go', 70, 'With Never Let Me Go, Mark Romanek has delivered a graceful adaptation that captures the spirit of the Ishiguro novel -- which will be precisely the problem for some viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('never say never again', 67, 'While the rehashed story feels rather uninspired and unnecessary, the return of both Sean Connery and a more understated Bond make Never Say Never Again a watchable retread.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the next karate kid', 7, 'The Next Karate Kid is noteworthy for giving audiences the chance to see a pre-Oscars Hilary Swank, but other than a typically solid performance from Pat Morita, this unnecessary fourth installment in the franchise has very little to offer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the next three days', 50, 'Russell Crowe and Elizabeth Banks give it their all, but their solid performances aren''t quite enough to compensate for The Next Three Days'' uneven pace and implausible plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nick of time', 32, 'It isn''t the worst ''90s action thriller, but by bungling a story pitting Johnny Depp against Christopher Walken, the rote Nick of Time ranks among the most disappointing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('night at the museum', 43, 'Parents might call this either a spectacle-filled adventure or a shallow and vapid CG-fest, depending on whether they choose to embrace this on the same level as their kids.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('night at the museum 2 battle of the smithsonian', 45, 'Night at the Museum: Battle at the Smithsonian is busy enough to keep the kids interested but the slapstick goes overboard and the special effects (however well executed) throw the production into mania.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('night comes on', 98, 'Steadily drawing viewers into its harrowing tale with equal parts grim intensity and startling compassion, Night Comes On heralds the arrivals of debuting director Jordan Spiro and her magnetic young stars.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('night moves', 86, 'A uniquely character-driven thriller with a finely composed cast and some outstanding direction from Kelly Reichardt, Night Moves bolsters its thought-provoking themes with compelling drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('il portiere di notte the night porter', 64, 'The Night Porter''s salaciousness gives its exploration of historical trauma a bitter aftertaste, but audiences seeking provocation are unlikely to forget the sting of this erotic drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('night watch', 60, 'This Russian horror/fantasy film pits darkness and light against each other using snazzy CGI visuals to create an extraordinary atmosphere of a dank, gloomy city wrestling with dread.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a nightmare on elm street', 15, 'Visually faithful but lacking the depth and subversive twists that made the original so memorable, the Nightmare on Elm Street remake lives up to its title in the worst possible way.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nights in rodanthe', 31, 'Derivative and schmaltzy, Nicholas Sparks'' Nights in Rodanthe is strongly mottled by contrivances that even the charisma of stars Diane Lane and Richard Gere can''t repair.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nights of cabiria le notti di cabiria', 97, 'Giulietta Masina is remarkable as a chronically unfortunate wretch with an indomitable spirit in Federico Fellini''s unrelentingly bleak -- yet ultimately uplifting -- odyssey through heartbreak.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the ninth gate', 43, 'Even though the film is stylish and atmospheric, critics say The Ninth Gate meanders aimlessly and is often ludicrous. And despite the advertising, there''s hardly any chills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nixon', 74, 'Much like its subject''s time in office, Nixon might have ended sooner -- but what remains is an engrossing, well-acted look at the rise and fall of a fascinating political figure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('no country for old men', 93, 'Bolstered by powerful lead performances from Javier Bardem, Josh Brolin, and Tommy Lee Jones, No Country for Old Men finds the Coen brothers spinning cinematic gold out of Cormac McCarthy''s grim, darkly funny novel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('no end in sight', 96, 'Charles Ferguson''s documentary provides a good summary of the decisions that led to the mess in post-war Iraq, and offers politically interested audiences something they''d been looking for: a lowdown on the decision making.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('no no a dockumentary', 97, 'While taking full advantage of its subject''s colorful baseball career, No No: A Dockumentary also imparts broader, thought-provoking messages that should resonate with viewers who aren''t sports fans.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('no one knows about persian cats les chats persans', 95, 'Bringing a dose of humor and a fresh perspective to a very serious subject, No One Knows About Persian Cats is an exhilarating, quietly powerful tribute to the courage of Iran''s underground musicians.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('no strings attached', 49, 'It benefits from the presence of Natalie Portman and director Ivan Reitman''s steady hand, but No Strings Attached doesn''t have the courage or conviction to follow through on its ribald premise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('noah', 76, 'With sweeping visuals grounded by strong performances in service of a timeless tale told on a human scale, Darren Aronofsky''s Noah brings the Bible epic into the 21st century.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nobodys fool', 24, 'Nobody''s Fool has a pair of strong leads and a smattering of scenes that highlight Tiffany Haddish''s talents -- all of which only make the uninspired end results more frustrating.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nonstop', 62, 'While Liam Neeson is undoubtedly an asset, Non-Stop wastes its cast -- not to mention its solid premise and tense setup -- on a poorly conceived story that hinges on a thoroughly unbelievable final act.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('norbit', 9, 'Coming off his Oscar-nominated performance in Dreamgirls, the talented-but-inconsistent Eddie Murphy plays three roles in Norbit, a cruel, crass, stereotype-filled comedy that''s more depressing than funny.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('norm of the north', 9, 'A pioneering feat in the field of twerking polar bear animation but blearily retrograde in every other respect, Norm of the North should only be screened in case of parental emergency.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('north dallas forty', 84, 'Muddled overall, but perceptive and brutally realistic, North Dallas Forty also benefits from strong performances by Nick Nolte and Charles Durning. Football fans will likely find it fascinating.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nosferatu a symphony of horror nosferatu eine symphonie des grauens nosferatu the vampire', 97, 'One of the silent era''s most influential masterpieces, Nosferatu''s eerie, gothic feel -- and a chilling performance from Max Schreck as the vampire -- set the template for the horror films that followed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('not another teen movie', 29, 'NATM has some funny moments, but the movie requires the audience to have familiarity with the movies being spoofed and a tolerance for toilet and sexual humor to be truly effective.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('nutty professor ii the klumps', 26, 'While Eddie Murphy is still hilarious as the entire Klump family, the movie falls apart because of uneven pacing, a poor script, and skits that rely on being gross rather than funny.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the object of my affection', 52, 'Despite heartfelt performances from Jennifer Aniston and Paul Rudd, The Object of My Affection suffers from too many plot contrivances and frequent turns into rom-com sappiness.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('oceans 8', 69, 'Ocean''s 8 isn''t quite as smooth as its predecessors, but still has enough cast chemistry and flair to lift the price of a ticket from filmgoers up for an undemanding caper.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('october sky', 91, 'Rich in sweet sincerity, intelligence, and good old-fashioned inspirational drama, October Sky is a coming-of-age story with a heart to match its Hollywood craftsmanship.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('oculus', 74, 'With an emphasis on dread over gore and an ending that leaves the door wide open for sequels, Oculus could be just the first spine-tingling chapter in a new franchise for discerning horror fans.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('office christmas party', 41, 'Its cast of gifted comics is good for a handful of laughs, but Office Christmas Party''s overstuffed plot ultimately proves roughly as disappointing as its clichéd gags and forced sentimentality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('okja', 86, 'Okja sees Bong Joon-ho continuing to create defiantly eclectic entertainment -- and still hitting more than enough of his narrative targets in the midst of a tricky tonal juggling act.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('old yeller', 100, 'Old Yeller is an exemplary coming of age tale, packing an emotional wallop through smart pacing and a keen understanding of the elemental bonding between humanity and their furry best friends.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('oliver company', 50, 'Predictable and stodgy, Oliver & Company isn''t one of Disney''s best, though its colorful cast of characters may be enough to entertain young viewers looking for a little adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('oliver twist', 100, 'David Lean brings the grimy beauty of Charles Dickens'' Victorian England to vivid cinematic life in Oliver Twist, a marvelous adaptation that benefits from Guy Green''s haunting cinematography and Alec Guinness'' off-kilter performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('olympus has fallen', 49, 'It''s far from original, but Olympus Has Fallen benefits from Antoine Fuqua''s tense direction and a strong performance from Gerard Butler -- which might just be enough for action junkies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('on her majestys secret service', 81, 'George Lazenby''s only appearance as 007 is a fine entry in the series, featuring one of the most intriguing Bond girls in Tracy di Vincenzo (Diana Rigg), breathtaking visuals, and some great ski chases.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('on the basis of sex', 73, 'On the Basis of Sex is nowhere near as groundbreaking as its real-life subject, but her extraordinary life makes a solid case for itself as an inspirational, well-acted biopic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('on the beach at night alone bamui haebyuneoseo honja', 92, 'On the Beach at Night Alone finds writer-director Sang-soo Hong working in a more personal vein -- without losing the singular sensibilities that have informed much of his acclaimed earlier work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('on the waterfront', 99, 'With his electrifying performance in Elia Kazan''s thought-provoking, expertly constructed melodrama, Marlon Brando redefined the possibilities of acting for film and helped permanently alter the cinematic landscape.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('once in the life', 28, 'Once in a Life is a promising directorial effort by Laurence Fishburne. But the story is too conventional and similar to the many ghetto action/dramas that come before it.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('once upon a forest', 22, 'Inert animation and generically chipper characters rob Once Upon a Forest of any personality despite its well-intentioned message and critter appeal for very young children.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('once upon a time in america', 87, 'Sergio Leone''s epic crime drama is visually stunning, stylistically bold, and emotionally haunting, and filled with great performances from the likes of Robert De Niro and James Woods.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('once upon a time in venice', 21, 'Once Upon a Time in Venice has a little more of a spark than typical late-period Bruce Willis tough guy movies, but it''s still a steep, disappointing tumble from his best work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('one flew over the cuckoos nest', 94, 'The onscreen battle between Jack Nicholson and Louise Fletcher serves as a personal microcosm of the culture wars of the 1970s -- and testament to the director''s vision that the film retains its power more than three decades later.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('one from the heart', 52, 'One from the Heart belies its reputation as a flop with Francis Ford Coppola''s earnest intentions and technical virtuosity, but not even the director''s ardor for the genre is enough to make audiences feel much for these characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ongbak ong bak muay thai warrior', 85, 'While Ong-Bak: The Thai Warrior may be no great shakes as a movie, critics are hailing the emergence of a new star in Tony Jaa, whose athletic performance is drawing comparisons with Bruce Lee, Jackie Chan, and Jet Li.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('only god forgives', 41, 'Director Refn remains as visually stylish as ever, but Only God Forgives fails to add enough narrative smarts or relatable characters to ground its beautifully filmed depravity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('only lovers left alive', 85, 'Worth watching for Tom Hiddleston and Tilda Swinton''s performances alone, Only Lovers Left Alive finds writer-director Jim Jarmusch adding a typically offbeat entry to the vampire genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('onward', 88, 'It may suffer in comparison to Pixar''s classics, but Onward makes effective use of the studio''s formula -- and stands on its own merits as a funny, heartwarming, dazzlingly animated adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('open city', 100, 'Open City fills in the familiar contours of its storyline with three-dimensional characters and a narrative depth that add up to a towering -- and still powerfully resonant -- cinematic achievement.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('opening night', 96, 'Opening Night is as dense and difficult as one would expect from John Cassavetes, but even the director''s detractors will be unable to deny the power of Gena Rowlands'' performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('operation finale', 60, 'Operation Finale is well-intentioned, well-acted, and overall entertaining, even if the depth and complexity of the real-life events depicted can get a little lost in their dramatization.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the opposite of sex', 80, 'The Opposite of Sex smartly lightens a bitter story with sharp insights and strong dialogue - as well as a startlingly mature performance from former child actor Christina Ricci.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('oranges and sunshine', 69, 'Grounded in a heartwrenching fact-based story, steered by Loach''s sensitive direction, and led by a powerful performance from Watson, Oranges and Sunshine sidesteps its pacing problems and occasionally clichéd screenplay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('orgazmo', 48, 'More juvenile than provocative, Orgazmo may have enough good-natured raunch to satisfy writer-director Trey Parker''s fans, but its satire is too soft to compete with the South Park co-creator''s best work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('oss 117 rio ne répond plus lost in rio', 75, 'Led by another appealing performance from Jean Dujardin, this sequel offers more absurdly fun action -- and more politically incorrect humor -- for fans of ''60s spy films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the other guys', 78, 'A clever parody of cop-buddy action-comedies, The Other Guys delivers several impressive action set pieces and lots of big laughs, thanks to the assured comic chemistry between Will Ferrell and Mark Wahlberg.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ouija origin of evil', 82, 'Ouija: Origin of Evil swerves its franchise''s planchette unexpectedly to YES with a surprisingly scary and dramatically satisfying follow-up to its lackluster predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('our brand is crisis', 93, 'Riveting and enraging, Our Brand Is Crisis peers behind the curtain of modern political campaigning and reveals a story that should be seen by citizens of all persuasions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('our brand is crisis', 36, 'Our Brand Is Crisis offers sporadic amusement and benefits from a talented cast, but ultimately lacks enough of a bite to add much of interest to the political satire genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('our kind of traitor', 72, 'Our Kind of Traitor relies on solid writing and acting rather than action to deliver its spy-movie thrills -- and thankfully has the pedigree to pull it off on both fronts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('our nixon', 91, 'Our Nixon offers a privileged personal perspective on a White House soon to be derailed by scandal, giving viewers an intimate look at the people behind the political legend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('out of africa', 59, 'Though lensed with stunning cinematography and featuring a pair of winning performances from Meryl Streep and Robert Redford, Out of Africa suffers from excessive length and glacial pacing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the outlaw josey wales', 90, 'Recreating the essence of his iconic Man With No Name in a post-Civil War Western, director Clint Eastwood delivered the first of his great revisionist works of the genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('overboard', 24, 'Overboard makes poor use of the ever-charming Anna Faris -- and chooses questionable source material -- to offer a remake that fails to clear the fairly low bar set by the original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('oz the great and powerful', 57, 'It suffers from some tonal inconsistency and a deflated sense of wonder, but Oz the Great and Powerful still packs enough visual dazzle and clever wit to be entertaining in its own right.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pacific rim uprising', 43, 'Pacific Rim Uprising won''t win any points for subtlety or originality, but it delivers enough of the rock ''em-sock ''em robots-vs.-kaiju thrills that fans of the original will be looking for.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paddington 2', 100, 'Paddington 2 honors its star''s rich legacy with a sweet-natured sequel whose adorable visuals are matched by a story perfectly balanced between heartwarming family fare and purely enjoyable all-ages adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paddington', 98, 'Paddington brings a beloved children''s character into the 21st century without sacrificing his essential charm, delivering a family-friendly adventure as irresistibly cuddly as its star.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the painted veil', 74, 'Visually, The Painted Veil has all the trappings of a stuffy period drama, but Norton''s and Watts''s deft portrayals of imperfect, complicated characters give the film a modern-day spark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pale rider', 93, 'Nearly a decade after The Outlaw Josey Wales, Clint Eastwood returns as a director to the genre that made his name with this elegant, spiritual Western that riffs on the classic Shane.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paper towns', 58, 'Paper Towns isn''t as deep or moving as it wants to be, yet it''s still earnest, well-acted, and thoughtful enough to earn a place in the hearts of teen filmgoers of all ages.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paper clips', 72, 'A touching, though somewhat flat, documentary that follows a homogenous class of white Protestant eighth graders as they learn the importance of tolerance by erecting a monument to the 6 million victims of the Holocaust.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paradise', 22, 'Paradise rounds up an impressive array of talent on either side of the camera -- all of whom would presumably prefer that audiences forget their involvement in this misfire.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the parallax view', 90, 'The Parallax View blends deft direction from Alan J. Pakula and a charismatic Warren Beatty performance to create a paranoid political thriller that stands with the genre''s best.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paranoid park', 77, 'Director Gus Van Sant once again superbly captures the ins and outs of teenage life in Paranoid Park, a quietly devastating portrait of a young man living with guilt and anxiety.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paranormal activity 3', 66, 'While the jolts and thrills are undeniably subject to the diminishing returns that plague most horror sequels, Paranormal Activity 3 is a surprisingly spine-tingling treat.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paranormal activity 4', 23, 'While it does manage to wring a few more screams out of the franchise''s surprisingly durable premise, Paranormal Activity 4 provides fans of the series with dismayingly diminishing returns.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paranormal activity the marked ones', 39, 'A change of setting breathes some new life into the franchise, but Paranormal Activity: The Marked Ones fails to provide enough consistent thrills to justify a fifth film in the series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pariah', 95, 'Pulsing with authenticity and led by a stirring lead performance from Adepero Oduye, Pariah is a powerful coming out/coming-of-age film that signals the arrival of a fresh new talent in writer/director Dee Rees.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('parkland', 50, 'Although its decision to look at John F. Kennedy''s assassination through uncommon perspectives is refreshing, Parkland never achieves the narrative cohesion its subject deserves.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('particle fever', 96, 'The concepts behind its heady subject matter may fly over the heads of most viewers, but Particle Fever presents it in such a way that even the least science-inclined viewers will find themselves enraptured.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a passage to india', 76, 'A Passage to India is a visually striking exploration of colonialism and prejudice, although it doesn''t achieve the thematic breadth of director David Lean''s finest work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('passion', 33, 'For better as well as worse, Passion is vintage De Palma sexploitation -- although with a storyline sillier than most, it fails to generate as much heat as his steamiest work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pat garrett billy the kid', 86, 'Sam Peckinpah tips his hat in mournful salute to the bygone West in this somber showdown, pitting a James Coburn against Kris Kristofferson in a meditative game of cat and mouse.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('path to war', 100, 'Path to War brings Lyndon B. Johnson''s full term to vivid life with terrific performances and a screenplay that provides an intimate look into a president''s psyche along with the far-reaching consequences of his decisions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('patriot games', 73, 'Patriot Games doesn''t win many points for verisimilitude, but some entertaining set pieces -- and Harrison Ford in the central role -- more than compensate for its flaws.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('patton', 94, 'George C. Scott''s sympathetic, unflinching portrayal of the titular general in this sprawling epic is as definitive as any performance in the history of American biopics.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('paul apostle of christ', 46, 'Paul, Apostle of Christ proves a well-intentioned yet disappointingly diffuse interpretation of a Bible story whose flashes of potential never come close to living up to the source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('peaceful warrior', 25, 'Based on a best-selling memoir, Peaceful Warrior loses something in the transition from page to screen. It hits the viewer over the head with philosophical jargon, and ultimately fails to live up to its source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the pelican brief', 53, 'Julia Roberts and Denzel Washington are a compelling team in the overlong Pelican Brief, a pulpy thriller that doesn''t quite justify the intellectual remove of Alan J. Pakula''s direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('people places things', 76, 'People Places Things finds writer-director Jim Strouse in peak form -- and makes the most of talented stars who help breathe fresh life into familiar narrative territory.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the people under the stairs', 66, 'Held aloft by gonzo black comedy and socially conscious subtext, The People Under The Stairs marks a unique -- though wildly uneven -- change of pace for director Wes Craven.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('peoples republic of desire', 97, 'People''s Republic of Desire fascinates and repels in equal measure with a sadly illuminating look at the intersection between technology and our relationship with celebrity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the perfect storm', 47, 'While the special effects are well done and quite impressive, this film suffers from any actual drama or characterization. The end result is a film that offers nifty eye-candy and nothing else.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a perfect world', 79, 'Despite some formulaic touches, Clint Eastwood''s haunting, ambiguous crime drama is smart and gritty, and features a bravura performance from Kevin Costner as a prison escapee on the run.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('performance', 85, 'Performance is an exuberant and grimy ode to the sexual revolution, evoking cultural upheaval and identity crisis with rock ''n'' roll verve and a beguiling turn by Mick Jagger.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('perfume the story of a murderer', 59, 'Perfume is what you''d expect from a Tom Twyker-directed movie glamorizing a serial killer: a kinetic visual feast, with a dark antihero that''s impossible to feel sympathy for.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the pest', 8, 'The Pest aims for zany comedy with social commentary, misses, and lands squarely at offensive misfire thanks to John Leguizamo''s over-caffeinated performance and a script laden with stereotypes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('peter rabbit', 63, 'Peter Rabbit updates Beatrix Potter''s classic characters with colorfully agreeable results that should entertain younger viewers while admittedly risking the wrath of purists.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('petes dragon', 88, 'Pete''s Dragon continues Disney''s current live-action winning streak with an update that gives the original a visual overhaul without overwhelming its sweet, soulful charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('phantom', 25, 'A cast of solid actors do what they can to elevate the material, but Phantom''s script is too clunky and devoid of tension to bear comparison to its thematic predecessors.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the phantom of the opera', 33, 'The music of the night has hit something of a sour note: Critics are calling the screen adaptation of Andrew Lloyd Webber''s popular musical histrionic, boring, and lacking in both romance and danger. Still, some have praised the film for its sheer spectacle.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('phantom of the paradise', 85, 'Brian De Palma''s subversive streak is on full display in Phantom of the Paradise, an ebullient rock opera that rhapsodizes creativity when it isn''t seething with disdain for the music industry.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('phantom thread', 91, 'Phantom Thread''s finely woven narrative is filled out nicely by humor, intoxicating romantic tension, and yet another impressively committed performance from Daniel Day-Lewis.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('philadelphia', 80, 'Philadelphia indulges in some unfortunate clichés in its quest to impart a meaningful message, but its stellar cast and sensitive direction are more than enough to compensate.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('philomena', 90, 'Based on a powerful true story and led by note-perfect performances from Judi Dench and Steve Coogan, Philomena offers a profoundly affecting drama for adult filmgoers of all ages.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ping pong playa', 64, 'A gentle, light, kid friendly comedy about a Chinese-American hoopster turned ping pong pro, Playa is a charming but considerable digression from director Jessica Yu''s previous works.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pinocchio', 100, 'Ambitious, adventurous, and sometimes frightening, Pinocchio arguably represents the pinnacle of Disney''s collected works -- it''s beautifully crafted and emotionally resonant.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pirates of the caribbean dead men tell no tales', 29, 'Pirates of the Caribbean: Dead Men Tell No Tales proves that neither a change in directors nor an undead Javier Bardem is enough to drain this sinking franchise''s murky bilge.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a place in the sun', 77, 'Director George Stevens'' stately treatment of A Place in the Sun buffs out some of the novel''s nuance with blunt moralizing, but riveting performances by Montgomery Clift and company give the drama a bruising punch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('places in the heart', 89, 'Places in the Heart is a quiet character piece with grand ambitions that it more than fulfills, thanks to absorbing work from writer-director Robert Benton and a tremendous cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('plan 9 from outer space', 67, 'The epitome of so-bad-it''s-good cinema, Plan 9 From Outer Space is an unintentionally hilarious sci-fi "thriller" from anti-genius Ed Wood that is justly celebrated for its staggering ineptitude.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('planes', 25, 'Planes has enough bright colors, goofy voices, and slick animation to distract some young viewers for 92 minutes -- and probably sell plenty of toys in the bargain -- but on nearly every other level, it''s a Disney disappointment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('planes trains and automobiles', 91, 'Thanks to the impeccable chemistry between Steve Martin and John Candy, as well as a deft mix of humor and heart, Planes, Trains and Automobiles is a hilarious, heartfelt holiday classic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('platoon', 88, 'Informed by director Oliver Stone''s personal experiences in Vietnam, Platoon forgoes easy sermonizing in favor of a harrowing, ground-level view of war, bolstered by no-holds-barred performances from Charlie Sheen and Willem Dafoe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('playing it cool', 14, 'Playing It Cool pits Chris Evans and Michelle Monaghan''s easy chemistry against a screenplay that tries too hard to be quirky and clever, and the results are disappointingly lukewarm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pleasantville', 85, 'Filled with lighthearted humor, timely social commentary, and dazzling visuals, Pleasantville is an artful blend of subversive satire and well-executed Hollywood formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('point break', 11, 'Loaded with dazzling action but bereft of purpose, the Point Break remake will be remembered as the first film to make audiences pine for the simultaneous presences of Keanu Reeves and Gary Busey.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pokémon 3 the movie', 21, 'Critics say that the third Pokemon movie has a better plot than its two predecessors. This is not enough, however, to recommend it to those not already fans of the franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pokémon detective pikachu', 68, 'Pokémon Detective Pikachu may not take its wonderfully bizarre premise as far as it could have, but this offbeat adaptation should catch most -- if not all -- of the franchise''s fans.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('polar', 19, 'An action thriller starring Mads Mikkelsen as the world''s most dangerous assassin should be terrifically entertaining, but Polar proves it''s possible to ruin anything if you try.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pollock', 81, 'Though Pollock does not really allow audiences a glimpse of the painter as a person, it does powerfully depict the creative process. Harris throws himself into the role and turns in a compelling performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('poltergeist', 31, 'Paying competent homage without adding anything of real value to the original Poltergeist, this remake proves just as ephemeral (but half as haunting) as its titular spirit.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('polyester', 93, 'As proudly tacky as its titular fabric, Polyester finds writer-director John Waters moving ever so slightly into the mainstream without losing any of his subversive charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('possession', 64, 'It''s perhaps a bit tame and uninspiring, considering its subject matter, but Possession manages enough romance and period intrigue to satisfy most fans of its source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('post tenebras lux', 53, 'Post Tenebras Lux conjures striking imagery amidst its formless exploration into darkness and light, but director Carlos Reygadas paints his abstract work with the slowest of brushstrokes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('practical magic', 22, 'Practical Magic''s jarring tonal shifts sink what little potential its offbeat story may have -- though Nicole Kidman and Sandra Bullock''s chemistry makes a strong argument for future collaborations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a prairie home companion', 82, 'The final film by the great Robert Altman, A Prairie Home Companion, the big screen adaptation of Garrison Keillor''s radio broadcast showcases plenty of the director''s strengths: it''s got a gigantic cast and plenty of quirky acting and dialogue.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('prayers for bobby', 73, 'A devastating true story and terrific performance by Sigourney Weaver give Prayers for Bobby palpable power, although some viewers may find this well-intentioned film too calculating in its efforts to wring tears.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('premonition', 8, 'Overdosing on flashbacks, and more portentous than profound, the overly obtuse Premonition weakly echoes such twisty classics as Memento, The Sixth Sense, and Groundhog Day.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('presumed innocent', 87, 'Thanks to an outstanding script, focused direction by Alan Pakula, and a riveting performance from Harrison Ford, Presumed Innocent is the kind of effective courtroom thriller most others aspire to be.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('prince avalanche', 82, 'A step back in the right direction for director David Gordon Green, Prince Avalanche shambles amiably along with a pair of artfully low-key performances from Paul Rudd and Emile Hirsch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('prince of darkness', 58, 'Prince of Darkness has a handful of chillingly clever ideas, but they aren''t enough to put John Carpenter''s return to horror at the same level as his classic earlier outings.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('prince of persia the sands of time', 37, 'It doesn''t offer much in the way of substance, but Prince of Persia is a suitably entertaining swashbuckler -- and a substantial improvement over most video game adaptations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the prince of tides', 69, 'Although the central romance arguably suffocates the heart of the drama, a moving performance by Nick Nolte and Barbra Streisand''s deft direction give The Prince of Tides a soulful edge.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the princess bride', 97, 'A delightfully postmodern fairy tale, The Princess Bride is a deft, intelligent mix of swashbuckling, romance, and comedy that takes an age-old damsel-in-distress story and makes it fresh.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('private benjamin', 82, 'Private Benjamin proves a potent showcase for its Oscar-nominated star, with Hawn making the most of a story that rests almost completely on her daffily irresistible charm.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the private lives of pippa lee', 69, 'Reverential and offbeat, the road trip film Private lives of Pippa Lee takes emotional detours and is elevated by great performances, particularly that of Robin Wright-Penn.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the prize winner of defiance ohio', 60, 'Noteworthy for Julianne Moore''s performance, Prize Winner is nonetheless a largely indistinct and tentative film that fails to convey the true power of its bittersweet tale.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('problem child', 0, 'Mean-spirited and hopelessly short on comic invention, Problem Child is a particularly unpleasant comedy, one that''s loaded with manic scenery chewing and juvenile pranks.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('project nim', 97, 'Equal parts hilarious, poignant, and heartbreaking, Project Nim not only tells a compelling story masterfully, but also raises the flag on the darker side of human nature.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('project x', 28, 'Unoriginal, unfunny, and all-around unattractive, Project X mines the depths of the teen movie and found-footage genres for 87 minutes of predictably mean-spirited debauchery.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('promare', 97, 'Visually dazzling and narratively exhilarating, Promare is a colorful thrill ride that should entertain adult anime enthusiasts as well as the teens in its target audience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('prometheus', 73, 'Ridley Scott''s ambitious quasi-prequel to Alien may not answer all of its big questions, but it''s redeemed by its haunting visual grandeur and compelling performances -- particularly Michael Fassbender as a fastidious android.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the proposition', 85, 'Brutal, unflinching, and violent, but thought-provoking and with excellent performances, this Australian western is the one of the best examples of the genre to come along in recent times.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the protector tom yum goong warrior king', 53, 'Despite some impressive fight scenes, this trimmed-down version of the Thai action pic is an off-putting mix of scant plot, choppy editing, and confusing subtitles and dubbing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('psycho', 96, 'Infamous for its shower scene, but immortal for its contribution to the horror genre. Because Psycho was filmed with tact, grace, and art, Hitchcock didn''t just create modern horror, he validated it.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pulse', 11, 'Another stale American remake of a successful Japanese horror film, Pulse bypasses the emotional substance of the original and overcompensates with pumped-up visuals and every known horror cliche.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('pumping iron', 91, 'In addition to offering an enlightening early look into the world of future star/politician Arnold Schwarzenegger, Pumping Iron provides a witty and insightful overview of competitive bodybuilding.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('punks not dead', 90, 'Susan Dynner''s Punk''s Not Dead is a thrilling and ambitious overview of the history and resilience of punk music, featuring interviews with an array of the genre''s outspoken godfathers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('purple noon plein soleil', 95, 'The talented Tom Ripley is brought to enigmatic life on the screen in Purple Noon, an exquisite thriller wherein the murderous social climber is embodied by an unnerving Alain Delon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('quantum of solace', 65, 'Brutal and breathless, Quantum Of Solace delivers tender emotions along with frenetic action, but coming on the heels of Casino Royale, it''s still a bit of a disappointment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('queen of earth', 93, 'Led by a searing performance from Elisabeth Moss, Queen of Earth is a demanding -- and ultimately rewarding -- addition to writer-director Alex Ross Perry''s impressive filmography.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('queen of the desert', 18, 'Queen of the Desert unites some undeniably talented professionals, but it''s difficult to discern what drew them together -- or understand how its compelling real-life story became such a muddled mess.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('quest for fire', 86, 'Its characters can''t do much more than grunt, but that doesn''t keep Quest for Fire from offering a deeply resonant -- and surprisingly funny -- look at the beginning of the human race.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('quincy', 82, 'Quincy presents an undeniably entertaining overview of its subject''s remarkable life and career, albeit one that may leave some viewers wishing it had dug a little deeper.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('race', 62, 'Race is nowhere near as thrillingly fleet or agile as its subject, but the story -- and a winning central performance from Stephan James -- are enough to carry it over the finish line.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('racing dreams', 100, 'Racing Dreams offers an absorbing peek at the lives of young NASCAR hopefuls that should resonate with racing enthusiasts as well as viewers with no connection to the sport.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('radio flyer', 33, 'Overlaying its whimsical concept onto a gritty story of domestic abuse, Radio Flyer is a family film that is too harrowing for children and too saccharine for their parents.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('railroad tigers', 38, 'Railroad Tigers throws a few sparks hearkening back to Jackie Chan''s glory days as an action comedy star, but they''re smothered by an unfocused story and jarring shifts in tone.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rain man', 89, 'This road-trip movie about an autistic savant and his callow brother is far from seamless, but Barry Levinson''s direction is impressive, and strong performances from Tom Cruise and Dustin Hoffman add to its appeal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ralph breaks the internet', 88, 'Ralph Breaks the Internet levels up on its predecessor with a funny, heartwarming sequel that expands its colorful universe while focusing on core characters and relationships.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rambo first blood part ii', 35, 'First Blood Part II offers enough mayhem to satisfy genre fans, but remains a regressive sequel that turns its once-compelling protagonist into just another muscled action berserker.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rambo iii', 39, 'Rambo III finds its justice-dispensing hero far from the thoughtful drama that marked the franchise''s beginning -- and just as far from quality action thriller entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rango', 88, 'Rango is a smart, giddily creative burst of beautifully animated entertainment, and Johnny Depp gives a colorful vocal performance as a household pet in an unfamiliar world.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rashômon', 98, 'One of legendary director Akira Kurosawa''s most acclaimed films, Rashomon features an innovative narrative structure, brilliant acting, and a thoughtful exploration of reality versus perception.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ratchet clank', 21, 'Ratchet & Clank may satisfy very young viewers, but compared to the many superior options available to families and animation enthusiasts, it offers little to truly recommend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rattlesnake', 28, 'Carmen Ejogo is stranded in a wasteland both figuratively and literally in this disposable thriller, which lacks the cleverness or specificity to give its thin conceit any bite.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('raw', 92, 'Raw''s lurid violence and sexuality live up to its title, but they''re anchored with an immersive atmosphere and deep symbolism that linger long after the provocative visuals fade.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('reach me', 4, 'Featuring a bewildering array of talented actors pummeled by disjointed direction and a dull, hackneyed script, Reach Me is so fundamentally misbegotten that its title reads more like a threat.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('reality bites', 66, 'Reality Bites may be too slick to fulfill its promise as a profound statement on Generation X, but an appealing ensemble and romantic sizzle make for an entertaining dive into the ennui of youth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the reaping', 8, 'It may feature such accomplished actors as Hilary Swank and Stephen Rea, but The Reaping also boasts the apropos tagline "What hath God wrought?" It''s schlocky, spiritually shallow, and scare-free.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rebel in the rye', 30, 'Rebel in the Rye attempts to dramatize J.D. Salinger''s life and creative process, but falters with a lack of dramatic impetus or a cohesive thesis about the reclusive author.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rec 2', 68, 'It lacks the surprising jolt of the first installment, but [REC] 2 almost maintains the original''s chilling momentum -- and proves not all horror sequels were made equal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rec 3 genesis', 40, '[REC] 3 Genesis discards the handheld POV of its predecessors and loses the franchise''s fresh perspective in the bargain, upping the gags and gore to the detriment of the chills that audiences crave.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('red', 72, 'It may not be the killer thrill ride you''d expect from an action movie with a cast of this caliber, but Red still thoroughly outshines most of its big-budget counterparts with its wit and style.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('red 2', 44, 'While it''s still hard to argue with its impeccable cast or the fun they often seem to be having, Red 2 replaces much of the goofy fun of its predecessor with empty, over-the-top bombast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('red hill', 79, 'Though its attempts to rework genre conventions may fall flat with some, Red Hill is a beautifully shot, tightly paced thriller that marks a strong debut for director Patrick Hughes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('red rock west', 95, 'Red Rock West is a hidden neo-noir gem with some delightful cracks in its surface -- and an opportunity to see Lara Flynn Boyle, Nicolas Cage, Dennis Hopper, and J.T. Walsh go toe-to-toe in all their early ''90s glory.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('red sparrow', 45, 'Red Sparrow aims for smart, sexy spy thriller territory, but Jennifer Lawrence''s committed performance isn''t enough to compensate for thin characters and a convoluted story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('reign of fire', 42, 'Reign of Fire gains some altitude with its pyrotechnic action and a smolderingly campy Matthew McConaughey, but the feature''s wings are clipped by a derivative script and visual effects that fizzle out.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('reign over me', 64, 'Reign Over Me is a charming, affecting tale of friendship and loss, with solid performances from Adam Sandler as a broken, grief-stricken man and Don Cheadle as his old friend and savior.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('relic', 91, 'Relic ratchets up its slowly building tension in an expertly crafted atmosphere of dread, adding up to an outstanding feature debut for director/co-writer Natalie Erika James.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('remember', 70, 'Remember risks wandering into exploitative territory, but it''s bolstered by some of Egoyan''s best latter-day directing and a typically stellar performance from Christopher Plummer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('remember the titans', 73, 'An inspirational crowd-pleaser with a healthy dose of social commentary, Remember the Titans may be predictable, but it''s also well-crafted and features terrific performances.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('renaissance man', 12, 'Renaissance Man tries to simultaneously be a literary comedy, an inspirational drama, and a star vehicle that caters to Danny DeVito''s strengths, but proves to be a master of none.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('renoir', 72, 'Appropriately enough, Renoir offers viewers a drama of sumptuous beauty -- which is more than enough to offset its frustratingly slow pace and rather thinly written screenplay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rescue dawn', 90, 'Director Werner Herzog has once again made a compelling tale of man versus nature, and Christian Bale completely immerses himself in the role of fighter pilot (and prisoner of war) Dieter Dengler.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('resident evil retribution', 29, 'Resident Evil: Retribution offers everything one might reasonably expect from the fifth installment in a heavily action-dependent franchise -- which means very little beyond stylishly hollow CGI-enhanced set pieces.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('resident evil the final chapter', 37, 'Resident Evil: The Final Chapter may prove mind-numbingly chaotic for the unconverted, but for fans of the venerable franchise, it offers a fittingly kinetic conclusion to its violent post-apocalyptic saga.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('results', 84, 'Results moves stubbornly at its own deliberate pace, but the well-chosen cast -- and writer-director Andrew Bujalski''s insightful observations -- offer rich rewards for patient viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('return to the blue lagoon', 0, 'Despite its lush tropical scenery and attractive leads, Return to the Blue Lagoon is as ridiculous as its predecessor, and lacks the prurience and unintentional laughs that might make it a guilty pleasure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('revenge of the nerds ii nerds in paradise', 7, 'It reunites most of the original cast and rounds them up for a trip to Fort Lauderdale for spring break, but Revenge of the Nerds II: Nerds in Paradise forgets to pack enough jokes or compelling characters to make it through its 89-minute running time.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ricky gervais humanity', 47, 'Ricky Gervais returns to the stage with his characteristic wit and distinct edginess, but the performance verges on cruel when his mockery seemingly overtakes his own Humanity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ride along 2', 13, 'Ride Along 2 presents a cop-comedy sequel whose well-matched stars can''t break the law of diminishing returns -- or lock up a script that unabashedly steals from the original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('riding in cars with boys', 49, 'Riding in Cars With Boys suffers from mixing grit and pathos with cuteness and comedy. Ironically, many critics found Zahn''s character more compelling and three-dimensional than Barrymore''s.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the ring', 71, 'With little gore and a lot of creepy visuals, The Ring gets under your skin, thanks to director Gore Verbinski''s haunting sense of atmosphere and an impassioned performance from Naomi Watts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the ring two', 20, 'Ring Two serves up horror cliches, and not even Hideo Nakata, the director of the movies from which this one is based, can save the movie from a dull screenplay full of absurdities.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rings', 8, 'Rings may offer ardent fans of the franchise a few threadbare thrills, but for everyone else, it may feel like an endless loop of muddled mythology and rehashed plot points.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rio 2', 48, 'Like most sequels, Rio 2 takes its predecessor''s basic template and tries to make it bigger -- which means it''s even busier, more colorful, and ultimately more exhausting for viewers outside the youthful target demographic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ripd', 13, 'It has its moments -- most of them courtesy of Jeff Bridges'' rootin'' tootin'' performance as an undead Wild West sheriff -- but R.I.P.D. is ultimately too dim-witted and formulaic to satisfy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rise of the planet of the apes', 82, 'Led by Rupert Wyatt''s stylish direction, some impressive special effects, and a mesmerizing performance by Andy Serkis, Rise of the Planet of the Apes breathes unlikely new life into a long-running franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('risen', 53, 'Risen benefits from a lighter tone than many faith-based productions, as well as a unique take on the Greatest Story Ever Told and a terrific turn from star Joseph Fiennes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rivers edge', 87, 'A harrowing tale of aimless youth, River''s Edge generates considerable tension and urgency thanks to strong performances from a stellar cast that includes Crispin Glover, Keanu Reeves, and Ione Skye.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('robert the bruce', 44, 'It''s inspired by epic real-life events, but rich cinematography and the best of intentions aren''t enough to carry Robert the Bruce past its leaden pace and bland storytelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('robin and marian', 73, 'Robin and Marian gives the legendary characters a somber sendoff, finding ample success in the romantic chemistry between Sean Connery and Audrey Hepburn while yielding diminishing returns in its attempts at relevant satire.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('robin hood', 43, 'Ridley Scott''s revisionist take on this oft-told tale offers some fine acting and a few gripping action sequences, but it''s missing the thrill of adventure that made Robin Hood a legend in the first place.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('robin hood', 15, 'Robin Hood robs from rich source material, but is ultimately just another poor attempt to needlessly gussy up a classic tale with amped-up action and modern special effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('robin hood men in tights', 40, 'Undisciplined, scatological, profoundly silly, and often utterly groan-worthy, Robin Hood: Men in Tights still has an amiable, anything-goes goofiness that has made it a cult favorite.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rock dog', 47, 'Rock Dog is amiable enough, but its second-tier animation and uninspired story add up to a movie whose meager charms are likely to escape all but the youngest and least demanding viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rock of ages', 43, 'Its exuberant silliness is almost enough to make up for its utter inconsequentiality, but Rock of Ages is ultimately too bland and overlong to justify its trip to the big screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rock the kasbah', 7, 'The Shareef don''t like Rock the Kasbah, and neither will viewers hoping for a film that manages to make effective use of Bill Murray''s knack for playing lovably anarchic losers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rocket science', 84, 'Though Rocket Science appears to be a typically quirky indie, the well-rounded performances and director Jeffrey Blitz''s clear affection for his characters gives the film its proper human spark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the rocketeer', 65, 'An action-packed, if anachronistic, look back at pulp matinee serials, The Rocketeer may ring hollow with viewers expecting more than simple fun and gee-whiz special effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rocknrolla', 60, 'Mixed reviews for Guy Ritchie''s return to his London-based cockney wideboy gangster movie roots, but most agree, it''s a step in the right direction following two major turkeys.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the rocky horror picture show', 80, 'Rocky Horror Picture Show brings its quirky characters in tight, but it''s the narrative thrust that really drives audiences insane and keeps ''em doing the time warp again.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rocky iv', 40, 'Rocky IV inflates the action to absurd heights, but it ultimately rings hollow thanks to a story that hits the same basic beats as the first three entries in the franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rocky v', 29, 'Rocky V''s attempts to recapture the original''s working-class grit are as transparently phony as each of the thuddingly obvious plot developments in a misguided installment that sent the franchise flailing into longterm limbo.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rolling thunder revue a bob dylan story by martin scorsese', 92, 'Rolling Thunder Revue: A Bob Dylan Story by Martin Scorsese lives up to its unwieldy title with a delightfully unorthodox look at a pivotal period in its subject''s career.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('romancing the stone', 85, 'Romancing the Stone reaches back to the classic Saturday morning serials of old with an action-filled adventure enlivened by the sparkling chemistry between its well-matched leads.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('romeo must die', 32, 'In his second Hollywood movie, Jet Li impresses. Unfortunately, when he''s not on screen, the movie slows to a crawl. Though there''s some spark between Jet and Aaliyah, there isn''t any threat of a fire. And as impressive as the action sequences are, some critics feel they are over-edited.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('romper stomper', 79, 'Relentlessly grim and gripping, Romper Stomper is a disquietingly authentic glimpse into the inner dynamics of a hate group, featuring an electric performance by Russell Crowe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('romy and micheles high school reunion', 73, 'Romy and Michele''s High School Reunion has an admittedly slight premise, but it''s elevated by ample heart, an infectiously playful spirit, and the buoyant chemistry of Lisa Kudrow and Mira Sorvino.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rough night', 44, 'Rough Night''s gifted stars are certainly good for some laughs, but their talents aren''t properly utilized in a scattered comedy that suffers from too many missed opportunities.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('roxanne roxanne', 70, 'Roxanne Roxanne belatedly honors its subject with a gripping character-driven biopic that serves as a primer for a trailblazing career while telling an often tragic story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rudderless', 64, 'Rudderless asks its cast to carry an awful lot of weight for its occasionally manipulative story; fortunately, this talented bunch -- led by Billy Crudup -- is often more than up to the task.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rudo y cursi', 73, 'Despite its fair share of sports movie cliches, Rudo y Cursi marks an auspicious directing debut for Carlos Cuarón, and features strong performances from García Bernal and Luna.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('rumble the indians who rocked the world', 91, 'RUMBLE shines a long overdue spotlight on key contributions to the American musical lexicon, satisfying rock scholars while offering a fascinating -- albeit sobering -- primer on the foundations of a genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('run lola run', 93, 'More fun than a barrel of Jean-Paul Sartre, pic''s energy riffs on an engaging love story and really human performances while offering a series of what-ifs and a blood-stirring soundtrack.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sabans power rangers', 49, 'Power Rangers has neither the campy fun of its TV predecessor nor the blockbuster action of its cinematic superhero competitors, and sadly never quite manages to shift into turbo for some good old-fashioned morphin time.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sabotage', 22, 'Sabotage boasts one of Arnold Schwarzenegger''s finer post-political performances, but it''s wasted in a movie driven by grueling violence that punishes seemingly without purpose.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('safe', 58, 'While hard-hitting and violently inventive, Safe ultimately proves too formulaic to set itself apart from the action thriller pack -- including some of its star''s better films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('salems lot', 88, 'Director Tobe Hooper and a devilishly charismatic James Mason elevate this television adaptation of the Stephen King novel, injecting the vampiric tradition with fresh blood and lingering scares.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('salvador', 88, 'Despite its somewhat disjointed narrative, Oliver Stone''s Salvador is a vivid and powerful political drama that sets an early tone for the director''s similarly provocative future projects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('san andreas', 50, 'San Andreas has a great cast and outstanding special effects, but amidst all the senses-shattering destruction, the movie''s characters and plot prove less than structurally sound.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sanjuro tsubaki sanjûrô', 100, 'Technically impressive and superbly acted, Sanjuro is a funny, action-packed samurai adventure featuring outstanding cinematography and a charismatic performance from Toshiro Mifune.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the santa clause 3 the escape clause', 17, 'Playing Jack Frost as an evil cross between Liza Minnelli and Liberace, Martin Short is a welcome presence, but this tired series continues drawing from its bag of bland gags and dumb slapstick.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('santa sangre', 86, 'Those unfamiliar with Alejandro Jodorowsky''s style may find it overwhelming, but Santa Sangre is a provocative psychedelic journey featuring the director''s signature touches of violence, vulgarity, and an oddly personal moral center.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sausage party', 82, 'Sausage Party is definitely offensive, but backs up its enthusiastic profanity with an impressively high laugh-to-gag ratio -- and a surprisingly thought-provoking storyline.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the savages', 89, 'Thanks to a tender, funny script from director Tamara Jenkins, and fine performances from Philip Seymour Hoffman and Laura Linney, this film delivers a nuanced, beautifully three-dimensional look at the struggles and comforts of family bonds.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('saw', 49, 'Saw ensnares audiences with a deceptively clever plot and a myriad of memorable, nasty set pieces, but its lofty ambitions are undercut by a nihilistic streak that feels more mean than profound.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('say it isnt so', 9, 'Those that haven''t tired from Farrelly brothers'' brand of comedy may still find some laughs here. Otherwise, the slow pacing and unimaginative shock gags will start to wear on the viewer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a scanner darkly', 68, 'A faithful adaptation of Philip K. Dick''s novel, A Scanner Darkly takes the viewer on a visual and mind-blowing journey into the author''s conception of a drug-addled and politically unstable world.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('scarface', 82, 'Director Brian De Palma and star Al Pacino take it to the limit in this stylized, ultra-violent and eminently quotable gangster epic that walks a thin white line between moral drama and celebratory excess.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('score a film music documentary', 91, 'SCORE: A Film Music Documentary offers a long-overdue look at an integral component of cinema whose abbreviated overview of the subject should only leave viewers ready for more.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('scream 2', 81, 'As with the first film, Scream 2 is a gleeful takedown of scary movie conventions that manages to poke fun at terrible horror sequels without falling victim to the same fate.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the sea inside mar adentro the sea within', 84, 'Held aloft by a transfixing performance from Javier Bardem as a terminally ill man who chooses to die, The Sea Inside transcends its melodramatic story with tenderness and grace.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('searching for bobby fischer', 100, 'As sensitive as the young man at its center, Searching for Bobby Fischer uses a prodigy''s struggle to find personal balance as the background for a powerfully moving drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('seconds', 89, 'Featuring dazzling, disorienting cinematography from the great James Wong Howe and a strong lead performance by Rock Hudson, Seconds is a compellingly paranoid take on the legend of Faust.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the secret in their eyes el secreto de sus ojos', 89, 'Unpredictable and rich with symbolism, this Argentinian murder mystery lives up to its Oscar with an engrossing plot, Juan Jose Campanella''s assured direction, and mesmerizing performances from its cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('secret in their eyes', 39, 'Secret in Their Eyes wastes its incredible cast on a remake that fails to improve upon -- or even make a compelling case for its own existence in addition to -- the remarkable original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('secuestro express', 52, 'Despite utilizing a visual whirlwind of cinematic tricks, this socio-political thriller falls short of fulfilling its heavier goals but provides a powerful peek into the class issues of modern Venezuela.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('see spot run', 23, 'See Spot Run has all the elements chidren enjoy in a movie: a lovable dog, bad things happening to stupid adults, and lots of dog poop. For adults, it''s either hit-or-miss.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('see you yesterday', 95, 'See You Yesterday marries a novel sci-fi premise with urgent social relevance and forges something excitedly new from the union -- providing an impressive showcase for star Eden Duncan-Smith and debut writer-director Stefon Bristol.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('selma', 99, 'Fueled by a gripping performance from David Oyelowo, Selma draws inspiration and dramatic power from the life and death of Martin Luther King, Jr. -- but doesn''t ignore how far we remain from the ideals his work embodied.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('séraphine', 88, 'Seraphine is a well-crafted French film that effectively captures one woman''s experience with art, religion, and mental illness, and features a brilliant performance from Yolande Moreau.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the serpent and the rainbow', 65, 'Although it''s occasionally overwhelmed by excessive special effects, The Serpent and the Rainbow draws on a chilling atmosphere to deliver a intelligent, politically informed story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('set it up', 92, 'Set It Up follows the long-established outlines of the rom-com template -- and in the process, proves there''s still substantial pleasure to be wrought from familiar formulas.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('seven brides for seven brothers', 88, 'Buoyed by crowd-pleasing tunes and charming performances, Seven Brides for Seven Brothers makes a successful transition from Broadway to screen that''s sure to please the whole family.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('seven samurai shichinin no samurai', 100, 'Arguably Akira Kurosawa''s masterpiece, The Seven Samurai is an epic adventure classic with an engrossing story, memorable characters, and stunning action sequences that make it one of the most influential films ever made.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sex drugs rock roll', 73, 'Sex & Drugs & Rock & Roll pays appropriately uninhibited tribute to a pioneering artist -- and proves Andy Serkis can be every bit as compelling in a non-motion-capture role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sex lies and videotape', 96, 'In his feature directorial debut, Steven Soderbergh demonstrates a mastery of his craft well beyond his years, pulling together an outstanding cast and an intelligent script for a nuanced, mature film about neurosis and human sexuality.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sexy beast', 87, 'Sexy Beast rises above other movies in the British gangster genre due to its performances -- particularly an electrifying one by Ben Kingsley -- and the script''s attention to character development.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sgt peppers lonely hearts club band', 12, 'I thought you might like to know that the Beatles (aka the act you''ve known for all these years) are ill-served by this kitschy, aggressively whimsical fantasy film that''s most certainly not a thrill.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shadow conspiracy', 0, 'Rather than exciting audiences with a thrilling race against time, Shadow Conspiracy suggests there may be a secret cabal duping talented actors into selecting woefully deficient scripts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shadowlands', 97, 'Thanks to brilliant performances from Debra Winger and especially Anthony Hopkins, Shadowlands is a deeply moving portrait of British scholar C.S. Lewis''s romance with American poet Joy Gresham.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shadows and fog', 52, 'Shadows and Fog recreates the chiaroscuro aesthetic of German Expressionism, but Woody Allen''s rambling screenplay retreads the director''s neurotic obsessions with derivative results.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shanghai noon', 79, 'Although the plot is really nothing to brag about, Jackie Chan and Owen Wilson work well together. The cinematography looks great, and Jackie delivers a hilarious performance. This is an old-fashioned crowd-pleaser.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shaolin soccer', 90, 'The plot is utterly ridiculous, and the soccer in the movie is unlike any ever played anywhere on Earth, but watching Shaolin Soccer, you will probably find it impossible to care.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sherlock holmes', 69, 'Guy Ritchie''s directorial style might not be quite the best fit for an update on the legendary detective, but Sherlock Holmes benefits from the elementary appeal of a strong performance by Robert Downey, Jr.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shes funny that way', 44, 'She''s Funny That Way is an affectionate, talent-filled throwback to screwball comedies of old -- which makes it even more frustrating that the laughs are disappointingly few and far between.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shes having a baby', 40, 'Kevin Bacon and Elizabeth McGovern struggle to sustain a spark in She''s Having a Baby, a blasé adult romance that lacks the specificity and style of writer-director John Hughes'' more successful forays into teenage angst.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the shining', 84, 'Though it deviates from Stephen King''s novel, Stanley Kubrick''s The Shining is a chilling, often baroque journey into madness -- exemplified by an unforgettable turn from Jack Nicholson.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shirkers', 100, 'Shirkers uses one woman''s interrogation of a pivotal personal disappointment to offer affecting observations on creativity, lost opportunity, and coming to terms with the past.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shirley', 88, 'Elevated by outstanding work from Elisabeth Moss, Shirley pays tribute to its subject''s pioneering legacy with a biopic that ignores the commonly accepted boundaries of the form.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shock and awe', 30, 'Shock and Awe has a worthy story to tell and some fine actors trying to bring it to life; unfortunately, the end results are still as derivative as they are dramatically inert.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('shrek', 88, 'While simultaneously embracing and subverting fairy tales, the irreverent Shrek also manages to tweak Disney''s nose, provide a moral message to children, and offer viewers a funny, fast-paced ride.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('side by side', 93, 'Keanu Reeves proves a groovy guide through this informative exploration of how technology is transforming cinema, with an even-handed defense for both the old and the new.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('silence', 83, 'Silence ends Martin Scorsese''s decades-long creative quest with a thoughtful, emotionally resonant look at spirituality and human nature that stands among the director''s finest works.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the silence of the lambs', 96, 'Director Jonathan Demme''s smart, taut thriller teeters on the edge between psychological study and all-out horror, and benefits greatly from stellar performances by Anthony Hopkins and Jodie Foster.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('silent hill revelation', 10, 'Mediocre effort even by the standards of video game adaptations, Silent Hill: Revelation 3D features weak characters and an incomprehensible plot with a shortage of scares.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('silent running', 68, 'It doesn''t fulfill the potential of its ambitious themes, butSilent Running stands as a decidedly unique type of sci-fi journey marked by intimate character work and a melancholic mood.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the simpsons movie', 88, 'The Simpsons Movie contains the hearty laughs, biting satire, and honest portrayal of an American family that makes the show so popular. And it boasts slicker animation and polished writing that hearkens back to the show''s glory days.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sin noticias de dios dont tempt me', 38, 'More Hellish than it is Heavenly, Agustín Díaz Yanes'' black comedy about the Earthly duel between two angels doesn''t have enough genuine laughs to support its far-fetched premise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sing', 72, 'Sing delivers colorfully animated, cheerfully undemanding entertainment with a solid voice cast and a warm-hearted -- albeit familiar -- storyline that lives up to its title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('single white female', 54, 'Single White Female benefits from a pair of outstanding leads, neither of whom are well served by a storyline that wavers between thrillingly tense and utterly ridiculous.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sinister', 63, 'Its plot hinges on typically implausible horror-movie behavior and recycles countless genre cliches, but Sinister delivers a surprising number of fresh, diabolical twists.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sister act 2 back in the habit', 17, 'Sister Act is off-key in this reprise, fatally shifting the spotlight from Whoopi Goldberg to a less compelling ensemble of pupils and trading its predecessor''s sharp comedy for unconvincing sentiment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the sisterhood of the traveling pants', 77, 'This adaptation of a beloved novel charms with its heartwarming tale of friendship and young adulthood; realistic portrayals of the lives of teenage girls lend the comedy-drama sincerity, and may capture hearts outside the female-centric demographic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sisters', 60, 'Sisters'' sharp blend of pathos and vulgarity, along with Tina Fey and Amy Poehler''s effervescent chemistry, are more than enough to make up for the handful of laughs this coming-of-age comedy leaves on the table.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('six degrees of separation', 88, 'Though it betrays its theatrical roots, Six Degrees of Separation largely succeeds thanks to astute direction and fine performances -- particularly from an against-type Will Smith.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sixteen candles', 84, 'Significantly more mature than the teen raunch comedies that defined the era, Sixteen Candles is shot with compassion and clear respect for its characters and their hang-ups.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('skyscraper', 48, 'Well-cast yet derivative, Skyscraper isn''t exactly a towering action thriller feat, but it''s solidly constructed enough to stand among the genre''s more mildly diverting features.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('slacker', 85, 'Slacker rests its shiftless thumb on the pulse of a generation with fresh filmmaking that captures the tenor of its time while establishing a benchmark for 1990s indie cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('slc punk', 63, 'Merging anarchic spirit with straightforward melodrama, SLC Punk is a hit-and-miss odyssey of youthful rebellion elevated by Matthew Lillard''s dramatically potent star turn.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sleepwalk with me', 84, 'Laugh-out-loud funny and endearingly messy, Sleepwalk with Me overcomes its tonal inconsistencies to deliver a sweetly melancholic, amiably reassuring indie crowd-pleaser.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('small time crooks', 66, 'Woody Allen rises from his recent slump with Small Time Crooks. A simple, funny movie, Crooks proves Allen still has the touch that made his name synonymous with off-beat comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('smashed', 83, 'Smashed resists the temptation to play up its serious subject matter for high theatrics, opting instead to let its gentle tone and Mary Elizabeth Winstead''s marvelous performance carry the day.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('smiley face', 67, 'Although many of the jokes have been done before, Anna Faris''s bright performance and Gregg Araki''s sharp direction make Smiley Face more than your average stoner comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('smurfs the lost village', 40, 'Smurfs: The Lost Village may satisfy very young viewers and hardcore Smurfaholics, but its predictable story and bland animation continue the franchise''s recent mediocre streak.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('snitch', 57, 'Though it features one of Dwayne Johnson''s more thoughtful performances, the presentation of Snitch''s underlying message is muddled by lackluster storytelling and some tonal inconsistencies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('snow white and the huntsman', 49, 'While it offers an appropriately dark take on the fairy tale that inspired it, Snow White and the Huntsman is undone by uneven acting, problematic pacing, and a confused script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('snowden', 61, 'Snowden boasts a thrilling fact-based tale and a solid lead performance from Joseph Gordon-Levitt, even if director Oliver Stone saps the story of some of its impact by playing it safe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sob', 82, 'A sustained blast of unbridled vitriol from writer-director Blake Edwards, S.O.B. is one of the blackest -- and most consistently funny -- Hollywood satires ever put to film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a soldiers story', 90, 'A meticulously-crafted murder mystery with incisive observations about race in America, A Soldier''s Story benefits from a roundly excellent ensemble and Charles Fuller''s politically urgent screenplay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('solo a star wars story', 70, 'A flawed yet fun and fast-paced space adventure, Solo: A Star Wars Story should satisfy newcomers to the saga as well as longtime fans who check their expectations at the theater door.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('solomon kane', 67, 'Solomon Kane''s formulaic and bleak narrative is overcome by an entertaining, straightforward adherence to its genre, exciting gore, and a gratifying lead performance by James Purefoy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('some velvet morning', 54, 'Some Velvet Morning marks writer-director Neil LaBute''s welcome return to the mode of challenging chamber piece, but this misanthropic two-hander is too slight to produce the same bite as the filmmakers'' best works.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('somers town', 96, 'Shane Meadows hits the spot with this short but sweet slice of good natured comedy, surprisingly, as it''s essentially an extended black & white advert for a train station.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('something wild', 91, 'Boasting loads of quirky charm, a pair of likable leads, and confident direction from Jonathan Demme, Something Wild navigates its unpredictable tonal twists with room to spare.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('somethings gotta give', 72, 'Though it occasionally stumbles into sitcom territory, Something''s Gotta Give is mostly a smart, funny romantic comedy, with sharp performances from Jack Nicholson, Diane Keaton, and Keanu Reeves.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('somewhere', 71, 'It covers familiar territory for Sofia Coppola, but Somewhere remains a hypnotic, seductively pensive meditation on the nature of celebrity, anchored by charming performances from Stephen Dorff and Elle Fanning.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('songs my brothers taught me', 91, 'A naturalistic drama that quietly earns its emotional resonance, Songs My Brothers Taught Me further establishes writer-director Chloé Zhao as a gifted filmmaker and empathetic storyteller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sonic the hedgehog', 63, 'Fittingly fleet and frequently fun, Sonic the Hedgehog is a video game-inspired adventure the whole family can enjoy -- and a fine excuse for Jim Carrey to tap into the manic energy that launched his career.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sorry to bother you', 93, 'Fearlessly ambitious, scathingly funny, and thoroughly original, Sorry to Bother You loudly heralds the arrival of a fresh filmmaking talent in writer-director Boots Riley.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sound and fury', 96, 'This documentary presents its opposing views in an even-handed yet emotionally engaging manner. Critics say it will provoke much thought, as well as emotions, in the audience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('southbound', 81, 'Southbound doesn''t entirely avoid the jarring shifts common to anthology films, but thanks to some thrilling twists and turns, this horror road movie is a surprisingly smooth ride.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('southside with you', 92, 'Southside With You looks back on a fateful real-life date with strong performances and engaging dialogue, adding up to a romance that makes for a pretty good date movie in its own right.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('space cowboys', 78, 'While the plot is overly cliched, the suberb acting by the stars (especially the tense interactions between Clint Eastwood and Tommy Lee Jones) and the spectacular special effects make this a movie worth seeing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('space jam', 43, 'While it''s no slam dunk, Space Jam''s silly, Looney Toons-laden slapstick and vivid animation will leave younger viewers satisfied -- though accompanying adults may be more annoyed than entertained.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('spaceship earth', 87, 'Spaceship Earth achieves liftoff as an engaging behind-the-scenes record of an audacious experiment -- and settles into orbit as poignant proof of the power of a shared dream.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the spanish prisoner', 89, 'The Spanish Prisoner delivers just what fans of writer-director David Mamet expect: a smart, solidly constructed drama that keeps viewers guessing... and entertained along the way.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sparkle', 56, 'While undeniably melodramatic and old-fashioned, Sparkle transcends its formulaic trappings thanks to Salim Akil''s empathetic direction and strong performances from a committed cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('species', 43, 'Species shows flashes of the potential to blend exploitation and sci-fi horror in ingenious ways, but is ultimately mainly interested in flashing star Natasha Henstridge''s skin.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('spectre', 63, 'Spectre nudges Daniel Craig''s rebooted Bond closer to the glorious, action-driven spectacle of earlier entries, although it''s admittedly reliant on established 007 formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('speed 2 cruise control', 4, 'Speed 2 falls far short of its predecessor, thanks to laughable dialogue, thin characterization, unsurprisingly familiar plot devices, and action sequences that fail to generate any excitement.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('speed sisters', 92, 'Speed Sisters honors its incredible subjects with an absorbing stranger-than-fiction look at a real-life story that''s equal parts thought-provoking and purely entertaining.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('spice world', 34, 'Spice World''s lack of cohesive plot will likely lose most viewers, but for fans of the titular girl group there''s more than enough fun to be had in their wacky -- albeit superficial -- whirlwind of an adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('spiderman homecoming', 92, 'Spider-Man: Homecoming does whatever a second reboot can, delivering a colorful, fun adventure that fits snugly in the sprawling MCU without getting bogged down in franchise-building.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('spotlight', 97, 'Spotlight gracefully handles the lurid details of its fact-based story while resisting the temptation to lionize its heroes, resulting in a drama that honors the audience as well as its real-life subjects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('spread', 21, 'Despite occasional detours into surprisingly dark territory, Spread overall is an ineffectual celebration of vacuous Los Angeles high life rather than a deconstruction of it.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('spy', 95, 'Simultaneously broad and progressive, Spy offers further proof that Melissa McCarthy and writer-director Paul Feig bring out the best in one another -- and delivers scores of belly laughs along the way.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the spy who loved me', 80, 'Though it hints at the absurdity to come in later installments, The Spy Who Loved Me''s sleek style, menacing villains, and sly wit make it the best of the Roger Moore era.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stake land', 74, 'Though the genre is well worn at this point, director Jim Mickle focuses on strong characterization and eerie atmosphere to craft an effective apocalyptic vampire chiller that also manages to pack a mean punch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stalingrad', 50, 'There''s no arguing with its impressive production values, but Stalingrad should have devoted more attention to the screenplay and spent less on special effects-enhanced spectacle.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stand and deliver', 82, 'Stand and Deliver pulls off the unlikely feat of making math class the stuff of underdog drama -- and pays rousing tribute to a real-life inspirational figure in the bargain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star trek beyond', 86, 'Star Trek Beyond continues the franchise''s post-reboot hot streak with an epic sci-fi adventure that honors the series'' sci-fi roots without skimping on the blockbuster action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star trek generations', 48, 'Generations stands as a mediocre changing of the guard for crews of the Enterprise, with a dull plot that sometimes seems like an expanded episode of the television series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star trek ii the wrath of khan', 88, 'Considered by many fans to be the best of the Star Trek movies, Khan features a strong plot, increased tension, and a sharp supporting performance from Ricardo Montalban.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star trek into darkness', 84, 'Visually spectacular and suitably action packed, Star Trek Into Darkness is a rock-solid installment in the venerable sci-fi franchise, even if it''s not as fresh as its predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star trek iv the voyage home', 81, 'Star Trek IV: The Voyage Home is perhaps the lightest and most purely enjoyable entry of the long-running series, emphasizing the eccentricities of the Enterprise''s crew.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star trek the motion picture', 41, 'Featuring a patchwork script and a dialogue-heavy storyline whose biggest villain is a cloud, Star Trek: The Motion Picture is a less-than-auspicious debut for the franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star wars episode iv a new hope', 92, 'A legendarily expansive and ambitious start to the sci-fi saga, George Lucas opened our eyes to the possibilities of blockbuster filmmaking and things have never been the same.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star wars episode ii attack of the clones', 65, 'Star Wars Episode II: Attack of the Clones benefits from an increased emphasis on thrilling action, although they''re once again undercut by ponderous plot points and underdeveloped characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star wars episode iii revenge of the sith', 80, 'With Episode III: Revenge of the Sith, George Lucas brings his second Star Wars trilogy to a suitably thrilling and often poignant -- if still a bit uneven -- conclusion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('star wars episode vii the force awakens', 92, 'Packed with action and populated by both familiar faces and fresh blood, The Force Awakens successfully recalls the series'' former glory while injecting it with renewed energy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stardust', 76, 'A faithful interpretation that captures the spirit of whimsy, action, and off-kilter humor of Neil Gaiman, Stardust juggles multiple genres and tones to create a fantastical experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stardust memories', 68, 'Woody Allen throws himself a pity party with all the surrealistic trimmings of Federico Fellini in Stardust Memories, a scabrous self-portrait that rankles as often as it impresses stylistically.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('starter for 10', 90, 'Starter For 10 is a spirited coming-of-age tale that remains charming and witty even as it veers into darker teritory. The unique setting of a quiz show makes the film wittier than your average romantic comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('startupcom', 93, 'Startup.com is more than just a look at the rise and fall of the new economy. At its center is a friendship being tested to the limit, and that''s what makes it worth viewing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('steve martin and martin short an evening you will forget for the rest of your life', 100, 'Brimming with sidesplitting laughs and off the wall energy, Steve Martin And Martin Short: An Evening You Will Forget For the Rest of Your Life is a nostalgic celebration of two comedy legends.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stoker', 70, 'Its script doesn''t quite carry the dramatic heft of his earlier work, but Park Chan-wook''s Stoker showcases his eye for sumptuous imagery and his affection for dark, atmospheric narratives populated by mysterious characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stone', 50, 'Stone boasts a cast that includes Robert De Niro, Edward Norton, and Milla Jovovich, and it features strong dialogue, but it''s ultimately undone by its heavy-handed symbolism and overabundant plot twists.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the stoning of soraya m', 59, 'The Stoning of Soraya M. nearly transcends its deficiencies through the sheer strength of its subject material, but ultimately drowns out its message with an inappropriately heavy-handed approach.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stories we tell', 94, 'In Stories We Tell, Sarah Polley plays with the documentary format to explore the nature of memory and storytelling, crafting a thoughtful, compelling narrative that unfolds like a mystery.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('storks', 66, 'Colorful animation and a charming cast help Storks achieve a limited liftoff, but scattershot gags and a confused, hyperactively unspooled plot keep it from truly soaring.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('storytelling', 53, 'Todd Solondz''s Storytelling boasts an audacious narrative structure, but fails to deliver on the mechanics of its namesake, yielding a creative exercise that is more interested in satisfying the author''s interests than the audience''s investment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stranger than fiction', 73, 'A fun, whimsical tale about an office drone trying to save his life from his narrator, Stranger Than Fiction features a subdued performances from Will Ferrell that contributes mightily to its quirky, mind-bending affect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('streets of fire', 67, 'Streets of Fire may sometimes buckle under the strain of its ambitious fusion of disparate genres, but Walter Hill''s bravura style gives this motorcycle musical fuel to burn.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stuber', 41, 'Though it makes a strong case for future collaborations between Kumail Nanjiani and Dave Bautista, Stuber fails to mesh its contrasting genres, settling for an overtly violent, mildly entertaining diversion that''s far from a five-star ride.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('stuck in love', 57, 'It struggles to enliven its uneven script, but Stuck in Love boasts enough winning performances from its solid veteran cast to offer an appealing diversion for rom-com enthusiasts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('submergence', 23, 'A slow-moving misfire, Submergence isn''t as deep as it thinks it is -- but still manages to drown its stars in a drama whose admirable ambitions remain almost entirely unfulfilled.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('suburbicon', 28, 'A disappointing misfire for director George Clooney, Suburbicon attempts to juggle social satire, racial commentary, and murder mystery -- and ends up making a mess of all three.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sudden impact', 56, 'Sudden Impact delivers all the firepower -- and the most enduring catchphrase -- fans associate with the Dirty Harry franchise, but it''s far from the best film in the series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sugar spice', 28, 'Though this cheerleader comedy has an intriguing premise, it''s too empty-headed and saddled with too many lame jokes to live up to it. Also, some critics say the movie is irresponsible in its depiction of teens and guns.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('suicide squad', 26, 'Suicide Squad boasts a talented cast and a little more humor than previous DCEU efforts, but they aren''t enough to save the disappointing end result from a muddled plot, thinly written characters, and choppy directing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sully', 85, 'As comfortingly workmanlike as its protagonist, Sully makes solid use of typically superlative work from its star and director to deliver a quietly stirring tribute to an everyday hero.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sunlight jr', 63, 'It doesn''t offer much in the way of uplift, but Sunlight Jr.''s grim storyline is offset by Laurie Collyer''s empathetic screenplay and strong performances from Naomi Watts and Matt Dillon.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sunrise a song of two humans', 98, 'Boasting masterful cinematography to match its well-acted, wonderfully romantic storyline, Sunrise is perhaps the final -- and arguably definitive -- statement of the silent era.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sunset boulevard', 99, 'Arguably the greatest movie about Hollywood, Billy Wilder''s masterpiece Sunset Boulevard is a tremendously entertaining combination of noir, black comedy, and character study.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sunshine', 76, 'Danny Boyle continues his descent into mind-twisting sci-fi madness, taking us along for the ride. Sunshine fulfills the dual requisite necessary to become classic sci-fi: dazzling visuals with intelligent action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('superbad', 88, 'Deftly balancing vulgarity and sincerity while placing its protagonists in excessive situations, Superbad is an authentic take on friendship and the overarching awkwardness of the high school experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('superfly', 50, 'Superfly updates the blaxploitation original with a stylish remake that''s exciting and visually arresting enough to offer its own slickly staged action rewards, but disappointingly short on social subtext.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('surfs up', 79, 'Surf''s Up is a laid back, visually stunning animated movie that brings a fresh twist to some familiar conventions. Its witty mockumentary format is fun and inventive, and the CGI is breathtakingly realistic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sweeney todd the demon barber of fleet street', 86, 'Full of pith and Grand Guignol grossness, this macabre musical is perfectly helmed and highly entertaining. Tim Burton masterfully stages the musical in a way that will make you think he has done this many times before.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sweet bean an', 84, 'Sweet Bean''s deliberate pace demands patience, but the satisfying simplicity of its story -- and Kirin Kiki''s absorbing performance -- yield an array of riches well worth the wait.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sweet land', 85, 'Finding the right balance between subtle and sentimental, Sweet Land moves beyond other similarly-themed dramas with evocative cinematography that plays an equal role to the talented cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('sweet smell of success', 98, 'Sweet Smell of Success boasts a top-notch cast, sharp direction, atmospheric cinematography, and an appropriately jazzy score, making it one of the best noir crime thrillers ever made.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('swimming with sharks', 78, 'Swimming With Sharks is a smart, merciless Hollywood satire that''s darkly hilarious and observant, thanks to Kevin Spacey''s performance as ruthless studio mogul Buddy Ackerman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('system crasher systemsprenger', 94, 'While it may test viewers'' patience, System Crasher is a thoughtful and compassionate portrait of one child''s trauma and anger, featuring an enigmatic Helena Zengel in the lead role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('t2 trainspotting', 81, 'T2 Trainspotting adds an intoxicating, emotionally resonant postscript to its classic predecessor, even without fully recapturing the original''s fresh, subversive thrill.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('table 19', 26, 'Table 19 is marginally more entertaining than actually sitting with a table full of strangers at a wedding -- although most screenings won''t come with an open bar, which makes it a wash.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tadpole', 78, 'Presenting a sexual awakening with surprising candor, Tadpole is a spiky coming of age tale that benefits from a deeply felt performance by Aaron Stanford and a script that is unafraid to wade into morally choppy waters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('taken 3', 13, 'Hampered by toothless PG-13 action sequences, incoherent direction, and a hackneyed plot, Taken 3 serves as a clear signal that it''s well past time to retire this franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('takers', 28, 'Takers boasts some gripping set pieces and keeps things moving quickly, but its two-dimensional characters, clichéd script, and brazenly derivative plot make it hard to recommend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the talented mr ripley', 83, 'With Matt Damon''s unsettling performance offering a darkly twisted counterpoint to Anthony Minghella''s glossy direction, The Talented Mr. Ripley is a suspense thriller that lingers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tales from the script', 75, 'Tales from the Script can be frustratingly preoccupied with the pitfalls of screenwriting at the expense of loving the craft, but this documentary overall offers a wealth of professional pointers for aspiring storytellers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('talk radio', 82, 'The gripping union of a director and star at the peak of their respective powers, Talk Radio offers the viewer a singularly unlikable character and dares you to look away.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tallulah', 85, 'Tallulah''s narrative insight, thoughtfully written characters, and talented cast add up to an absorbing family drama that transcends genre tropes and capably overcomes its flirtations with melodrama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tampopo', 100, 'Thanks to director Juzo Itami''s offbeat humor and sharp satirical edge, Tampopo is a funny, sexy, affectionate celebration of food and its broad influence on Japanese culture.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tangerine', 96, 'Tangerine shatters casting conventions and its filmmaking techniques are up-to-the-minute, but it''s an old-fashioned comedy at heart -- and a pretty wonderful one at that.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('targets', 89, 'A startling directorial debut by Peter Bogdanovich mixes an homage to Boris Karloff horror films with a timely sniper story to create a thriller with modern baggage and old school shock and awe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tea with the dames nothing like a dame', 98, 'Tea with the Dames proves there''s plenty of entertainment value to be found in rounding up a quartet of screen legends for a chat -- and is likely to leave audiences wishing these stars would keep brewing up pots for an ongoing series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('ted 2', 45, 'Ted 2 reunites Mark Wahlberg and Seth MacFarlane for another round of sophomoric, scatological humor -- and just as before, your enjoyment will depend on your tolerance for all of the above.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('teen spirit', 71, 'Teen Spirit tells a story we know by heart, but writer-director Max Minghella''s connection to the material and Elle Fanning''s remarkable performance add an effective hook.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('teen titans go to the movies', 91, 'Teen Titans Go! To the Movies distills the enduring appeal of its colorful characters into a charmingly light-hearted adventure whose wacky humor fuels its infectious fun -- and belies a surprising level of intelligence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('teenage mutant ninja turtles', 21, 'Neither entertaining enough to recommend nor remarkably awful, Teenage Mutant Ninja Turtles may bear the distinction of being the dullest movie ever made about talking bipedal reptiles.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('teenage mutant ninja turtles out of the shadows', 37, 'Teenage Mutant Ninja Turtles: Out of the Shadows is a slight improvement over its predecessor, but still lacks the wit or anarchic energy of the comics that birthed the franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tehran taboo', 97, 'Tehran Taboo is a marvelous chronicle of a country through the prism of rotoscope, with the overlay of striking animation giving writer-director Ali Soozandeh''s acutely observed characters an extra dimension.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tequila sunrise', 52, 'Tequila Sunrise unites three of its decade''s most in-demand stars for a slickly packaged crime drama that looks great without ever going anywhere particularly interesting.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the terminator', 100, 'With its impressive action sequences, taut economic direction, and relentlessly fast pace, it''s clear why The Terminator continues to be an influence on sci-fi and action flicks.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('terminator 2 judgment day', 93, 'T2 features thrilling action sequences and eye-popping visual effects, but what takes this sci-fi/ action landmark to the next level is the depth of the human (and cyborg) characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('terminator genisys', 27, 'Mired in its muddled mythology, Terminator: Genisys is a lurching retread that lacks the thematic depth, conceptual intelligence, or visual thrills that launched this once-mighty franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('terms of endearment', 78, 'A classic tearjerker, Terms of Endearment isn''t shy about reaching for the heartstrings -- but is so well-acted and smartly scripted that it''s almost impossible to resist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('texas chainsaw massacre the next generation', 14, 'The Next Generation has the fortune of starring early-career Matthew McConaughey and Renée Zellweger, but it services neither headliner well in a convoluted and cheap-looking slasher that doesn''t live up to the Texas Chainsaw Massacre legacy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thank you for smoking', 86, 'Loaded with delightfully unscrupulous characters and and a witty, cynical script, Thank You For Smoking is a sharp satire with a brilliantly smarmy lead performance from Aaron Eckhart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('that evening sun', 82, 'Powered by a formidable leading turn from Hal Holbrook, That Evening Sun is a prime cut of southern gothic that offers plenty of meditative atmosphere for audiences to brood over.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thats my boy', 20, 'While it does represent a new foray into raunch for the normally PG-13 Sandler, That''s My Boy finds him repeating himself to diminishing effect - and dragging Andy Samberg down with him.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the company men', 67, 'It might be hard for most viewers to identify with The Company Men''s well-heeled protagonists, but writer/director John Wells uses their plight to make universally resonant points -- and gets the most out of his excellent cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the croods', 71, 'While it may not be as (ahem) evolved as the best modern animated fare, The Croods will prove solidly entertaining for families seeking a fast-paced, funny cartoon adventure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the eagle', 39, 'The Eagle has a pleasantly traditional action-adventure appeal, but it''s drowned out by Kevin Macdonald''s stolid direction and Channing Tatum''s uninspired work in the central role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the family that preys', 53, 'Tyler Perry''s The Family that Preys treads the filmmaker''s established terrain of family loyalty and moral uprightness, though the occasionally predictable plot slides forward, aided by an excess of soapy melodrama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man', 12, 'Despite the steely presence of Samuel L. Jackson and the comic timing of Eugene Levy, The Man''s plot is pointless and its jokes rehashed, as it ends up playing out like the Odd Couple with gas.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the romantics', 14, 'The Romantics is visually accomplished, but director Galt Niederhoffer''s adaptation of her own novel never finds the passion on the page or offers audiences a reason to invest in these limp love affairs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the warriors way', 31, 'Perfectly, thoroughly divisive, The Warrior''s Way will either be delightful or unbearable, depending on your tolerance for surreal, shamelessly over the top collisions of eastern and western clichés.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the 100yearold man who climbed out the window and disappeared', 68, 'Its efforts to earn laughs can be as ungainly as its title, but for viewers in tune with its absurdist humor, The 100-Year-Old Man Who Climbed Out the Window and Disappeared offers much to recommend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the 1517 to paris', 23, 'The 15:17 to Paris pays clumsily well-intentioned tribute to an act of heroism, but by casting the real-life individuals involved, director Clint Eastwood fatally derails his own efforts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the 33', 48, 'The 33 offers an appropriately inspirational account of real-life heroism, but its stirring story and solid performances are undermined by a flawed focus and an overreliance on formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the adderall diaries', 23, 'Stylistically overwrought and tedious, The Adderal Diaries aspires for profundity but instead feels like a shambolic class project thrown together right before it was due.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the african queen', 98, 'Perfectly cast, smartly written, and beautifully filmed, The African Queen remains thrilling, funny, and effortlessly absorbing even after more than half a century''s worth of adventure movies borrowing liberally from its creative DNA.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the amazing spiderman 2', 51, 'While the cast is outstanding and the special effects are top-notch, the latest installment of the Spidey saga suffers from an unfocused narrative and an overabundance of characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the american', 65, 'As beautifully shot as it is emotionally restrained, The American is an unusually divisive spy thriller -- and one that rests on an unusually subdued performance from George Clooney.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the apparition', 3, 'The Apparition fails to offer anything original, isn''t particularly scary, and offers so little in the way of dramatic momentum that it''s more likely to put you to sleep than thrill you.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the armstrong lie', 82, 'Smartly constructed and scathingly sharp, The Armstrong Lie presents an effective indictment of its unscrupulous subject -- as well as the sports culture that spawned him.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the art of the steal', 44, 'It boasts a terrific cast led by the always-watchable Kurt Russell and Terence Stamp, but The Art of the Steal wastes its stars on a formulaic plot that borrows too obviously from superior heist pictures.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the autopsy of jane doe', 87, 'The Autopsy of Jane Doe subverts the gruesome expectations triggered by its title to deliver a smart, suggestively creepy thriller that bolsters director André Ovredal''s growing reputation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the beach bum', 56, 'The role of a lifetime for Matthew McConaughey, The Beach Bum is set apart by Harmony Korine''s distinctive style, but that isn''t always enough to offset the unfocused story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the beguiled', 79, 'The Beguiled adds just enough extra depth to its source material to set itself apart, and director Sofia Coppola''s restrained touch is enlivened by strong performances from the cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the benefactor', 26, 'The Benefactor has Richard Gere and Dakota Fanning, but no clear idea of what to do with either of them, resulting in a drama that never comes anywhere near its intriguing potential.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the big short', 88, 'The Big Short approaches a serious, complicated subject with an impressive attention to detail -- and manages to deliver a well-acted, scathingly funny indictment of its real-life villains in the bargain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the big sick', 98, 'Funny, heartfelt, and intelligent, The Big Sick uses its appealing leads and cross-cultural themes to prove the standard romcom formula still has some fresh angles left to explore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the birth of a nation', 72, 'The Birth of a Nation overpowers its narrative flaws and uneven execution through sheer conviction, rising on Nate Parker''s assured direction and the strength of its vital message.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the black panthers vanguard of the revolution', 92, 'The Black Panthers: Vanguard Of The Revolution offers a fascinating -- if somewhat rudimentary -- introduction to a movement, and an era, that remains soberingly relevant today.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the blackcoats daughter february', 72, 'Slow-building and atmospheric, The Blackcoat''s Daughter resists girls-in-peril clichés in a supernatural thriller that serves as a strong calling card for debuting writer-director Oz Perkins.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the bling ring', 59, 'While it''s certainly timely and beautifully filmed, The Bling Ring suffers from director Sofia Coppola''s failure to delve beneath the surface of its shallow protagonists'' real-life crimes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the book of eli', 47, 'It''s certainly uneven, and many viewers will find that its reach exceeds its grasp, but The Book of Eli finds the Hughes brothers injecting some fresh stylish fun into the kind of post-apocalyptic wasteland filmgoers have seen more than enough of lately.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the book of henry', 22, 'The Book of Henry deserves a few points for ambition, but its tonal juggling act -- and a deeply maudlin twist -- may leave viewers gaping in disbelief rather than choking back tears.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the boss', 21, 'Melissa McCarthy remains as fiercely talented as ever, but her efforts aren''t enough to prop up the baggy mess of inconsistent gags and tissue-thin writing that brings down The Boss.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the boss baby', 53, 'The Boss Baby''s talented cast, glimmers of wit, and flashes of visual inventiveness can''t make up for a thin premise and a disappointing willingness to settle for doody jokes.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the bourne legacy', 55, 'It isn''t quite as compelling as the earlier trilogy, but The Bourne Legacy proves the franchise has stories left to tell -- and benefits from Jeremy Renner''s magnetic work in the starring role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the breaker upperers', 87, 'The Breaker Upperers brings the laughs early and often, thanks to the dry wit -- and effervescent chemistry -- of writer-director-star duo Jackie van Beek and Madeleine Sami.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the broken circle breakdown', 82, 'The Broken Circle Breakdown''s reach occasionally exceeds its grasp, but overall, it''s an intoxicating, finely wrought romance -- and one with a terrific soundtrack to boot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the brothers grimsby', 37, 'The Brothers Grimsby showers viewers with a steady stream of Sacha Baron Cohen''s edgy humor, but too many gags hit the wrong side of the line between audacious and desperate.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the bye bye man', 19, 'The Bye Bye Man clumsily mashes together elements from better horror films, adding up to a derivative effort as short on originality as it is on narrative coherency or satisfying scares.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the cabinet of dr caligari das cabinet des dr caligari', 98, 'Arguably the first true horror film, The Cabinet of Dr. Caligari set a brilliantly high bar for the genre -- and remains terrifying nearly a century after it first stalked the screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the campaign', 66, 'Its crude brand of political satire isn''t quite as smart or sharp as one might hope in an election year, but The Campaign manages to generate a sufficient number of laughs thanks to its well-matched leads.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the canyons', 21, 'Oppressively misanthropic and ineptly made, The Canyons serves as a sour footnote in Paul Schrader''s career -- but it does feature some decent late-period work from Lindsay Lohan.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the changeup', 25, 'There''s a certain amount of fun to be had from watching Bateman and Reynolds play against type, but it isn''t enough to carry The Change-Up through its crude humor and formulaic plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the choice', 11, 'Like the 10 Nicholas Sparks movies before it, The Choice finds tragedy striking star-crossed lovers in the sun-dappled South -- yet even for those who loved its predecessors, this gauzy melodrama may feel painfully formulaic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the christmas chronicles', 67, 'Viewers seeking a fresh holiday viewing option -- or those simply in the mood for Santa Kurt Russell -- should find The Christmas Chronicles well worth a yuletide stream.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the class', 95, 'Energetic and bright, this hybrid of documentary style and dramatic plotting looks at the present and future of France through the interactions of a teacher and his students in an inner city high school.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the cobbler', 10, 'The Cobbler represents a slight step up from Adam Sandler''s recent comedies, but while its cloying sentiment proves a more palatable substitute for his usual crass humor, it still isn''t terribly compelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the comedy', 47, 'Tim Heidecker''s misanthropic role proves him capable as a dramatic performer, yet The Comedy''s study of privilege unchecked is never as illuminating nor engaging as it should be.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the commuter', 56, 'The Commuter''s cast is better than its workmanlike script - which helps make this reasonably diverting Liam Neeson action thriller worth the price of a matinee ticket or rental, if not a full-price ticket.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the congress', 73, 'The Congress rises on the strength of Robin Wright''s powerful performance, with enough ambitious storytelling and technical thrills to overcome its somewhat messy structure.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the conjuring 2', 80, 'The Conjuring 2 can''t help but lose a bit of its predecessor''s chilly sting through familiarity, but what remains is still a superior ghost story told with spine-tingling skill.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the conquest', 77, 'The Conquest commendably dramatizes French President Nicholas Sarkozy''s rise to power, with a persuasive ensemble and a politically astute script handsomely compensating for a generic visual presentation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the counselor', 33, 'The Counselor raises expectations with its talented cast and creative crew -- then subverts them with a wordy and clumsy suspense thriller that''s mercilessly short on suspense or thrills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the crash reel', 96, 'Smart, compassionate, and moving, The Crash Reel uses the familiar sport-doc formula to subvert expectations and ask challenging questions about ambition and achievement.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the dead lands', 69, 'The Dead Lands doesn''t add anything new to the primeval quest genre, but its battle scenes boast enough visceral thrills to carry viewers through the more mundane moments.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the deal', 21, 'Dense with detail but light on entertainment value, The Deal turns a potentially riveting subject into a sloppily assembled -- and progressively more implausible -- misfire.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the death and life of marsha p johnson', 96, 'The Death and Life of Marsha P. Johnson uses its belated investigation into an activist''s murder as the framework for a sobering look at the ongoing battle for equal rights.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the death of stalin', 95, 'The Death of Stalin finds director/co-writer Arnando Iannucci in riotous form, bringing his scabrous political humor to bear on a chapter in history with painfully timely parallels.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the deer hunter', 93, 'Its greatness is blunted by its length and one-sided point of view, but the film''s weaknesses are overpowered by Michael Cimino''s sympathetic direction and a series of heartbreaking performances from Robert De Niro, Meryl Streep, and Christopher Walken.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the descent 2', 55, 'The Descent 2 goes spelunking for its predecessors'' unnerving power but never digs beyond surface chills, although this efficient splatterfest contains enough nasty set pieces to sate the gore-prone.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the devil wears prada', 75, 'A rare film that surpasses the quality of its source novel, this Devil is a witty expose of New York''s fashion scene, with Meryl Streep in top form and Anne Hathaway more than holding her own.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the devils double', 54, 'The Devil''s Double has plenty of gangster spectacle and Dominic Cooper ably playing off his dual roles, but this crime epic struggles to balance the fun of bad behavior with the dead serious crimes of its subject.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the diary of a teenage girl', 95, 'Boldly unconventional and refreshingly honest, Diary of a Teenage Girl is a frank coming-of-age story that addresses its themes -- and its protagonist -- without judgment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the dilemma', 25, 'It boasts a likable cast and an interesting premise, but The Dilemma can''t decide what to do with them; the result is an uneven blend of cheesy slapstick and surprisingly dark comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the disappointments room', 0, 'The Disappointments Room lives down to its title with a thrill-free thriller that presumably left its stars filled with regret - and threatens to do the same for audiences.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the divergent series allegiant', 11, 'Allegiant improves on previous entries in The Divergent Series on a few superficial levels, but they aren''t enough to counteract a sense of growing boredom with a franchise that''s gone on too long.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the double', 83, 'Hauntingly bleak and thrillingly ambitious, The Double offers Jesse Eisenberg a pair of compelling roles while reaffirming writer-director Richard Ayoade''s remarkable talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the dresser', 100, 'The Dresser brilliantly showcases two of the most gifted actors of their generation within a thoughtful, well-executed production offering intelligent commentary on the human condition.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the dressmaker', 57, 'The Dressmaker boasts a strong central performance by Kate Winslet and a captivating array of narrative weirdness -- all of which may or may not be a comfortable fit with viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the duff', 73, 'The DUFF doesn''t achieve teen-movie greatness, but offers enough of a postmodern twist on the genre to recommend -- and boasts typically great work from star Mae Whitman.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the eagle huntress', 94, 'Effectively stirring and bolstered by thrilling visuals, The Eagle Huntress uses its heartwarming message to fill up a feature that might have made for an even more powerful short film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the edge of democracy', 97, 'Assembled with absorbing insight and passion by director Petra Costa, The Edge of Democracy is a disturbing and expansive overview of how a democratic nation can teeter into autocracy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the end of the tour', 92, 'Brilliantly performed and smartly unconventional, The End of the Tour pays fitting tribute to a singular talent while offering profoundly poignant observations on the human condition.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the exception the kaisers last kiss', 73, 'The Exception (The Kaiser''s Last Kiss) elegantly blends well-dressed period romance and war drama into a solidly crafted story further elevated by Christopher Plummer''s excellent work and the efforts of a talented supporting cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the expendables 2', 68, 'Taut, violent, and suitably self-deprecating, The Expendables 2 gives classic action fans everything they can reasonably expect from a star-studded shoot-''em-up -- for better and for worse.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the expendables 3', 32, 'Like its predecessors, Expendables 3 offers a modicum of all-star thrills for old-school action thriller aficionados -- but given all the talent assembled, it should have been a lot more fun.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the face of love', 42, 'Perhaps worth checking out if only for the opportunity to see reliably powerful work from Annette Bening and Ed Harris, The Face of Love undermines its leads'' performances with a scattershot script and aimless direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the fearless vampire killers', 69, 'This uneven but amiable 1967 vampire picture is part horror spoof, part central European epic, and 100 percent Roman Polanski, whose signature sensibility colors every frame.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the fifth estate', 36, 'Heavy on detail and melodrama but missing the spark from its remarkable real-life inspiration, The Fifth Estate mostly serves as a middling showcase for Benedict Cumberbatch''s remarkable talent.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the 5th wave', 15, 'With unimpressive effects and plot points seemingly pieced together from previous dystopian YA sci-fi films, The 5th Wave ends up feeling like more of a limp, derivative wriggle.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the fighter', 90, 'Led by a trio of captivating performances from Mark Wahlberg, Christian Bale, and Amy Adams, The Fighter is a solidly entertaining, albeit predictable, entry in the boxing drama genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the flintstones', 22, 'The Flintstones wastes beloved source material and imaginative production design on a tepid script that plunks Bedrock''s favorite family into a cynical story awash with lame puns.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the florida project', 96, 'The Florida Project offers a colorfully empathetic look at an underrepresented part of the population that proves absorbing even as it raises sobering questions about modern America.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the flower of my secret la flor de mi secreto', 83, 'The Flower of My Secret finds Almodóvar revisiting old themes in a new, more subdued key, yielding a slight but vivacious work that delivers the pleasure of a punchy novella.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the flowers of war', 41, 'Zhang Yimou''s stylistic flair is in full bloom during The Flowers of War, but his colorful treatment of a historical genocide ultimately does a disservice to the horrifying events'' inherent drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the forbidden room', 96, 'The Forbidden Room may frustrate viewers looking for a linear experience, but those seeking a challenge -- or already familiar with director Guy Maddin''s work -- will be rewarded.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the forest', 10, 'The Forest offers Natalie Dormer a few chances to showcase her range in a dual role, but they aren''t enough to offset the fact that the movie''s simply not all that scary.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the founder', 80, 'The Founder puts Michael Keaton''s magnetic performance at the center of a smart, satisfying biopic that traces the rise of one of America''s most influential businessmen -- and the birth of one of its most far-reaching industries.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the fountain', 52, 'The Fountain -- a movie about metaphysics, universal patterns, Biblical symbolism, and boundless love spread across one thousand years -- is visually rich but suffers from its own unfocused ambitions.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the frisco kid', 50, 'Not even a genial Gene Wilder or a dashing Harrison Ford can rescue The Frisco Kid from a monotonous procession of gently comedic sketches that never cohere into a memorable yarn.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('hemingways garden of eden', 4, 'Garden of Eden dramatizes Ernest Hemingway''s clipped storytelling without carrying over the intelligence that undergirded the author''s writing, yielding a thin drama full of artifice and no feeling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the gatekeepers', 94, 'Strikingly stark, brutally honest, and rivetingly assembled, The Gatekeepers offers essential perspective on a seemingly intractable war from some of the men who fought it.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the ghost of peter sellers', 95, 'A soul-searching act of therapy for its director, The Ghost of Peter Sellers offers absorbing insight into how some decisions -- and people -- can haunt us long after they''re gone.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the girl', 70, 'The Girl may be too prosaic to properly evoke its subject, but sterling performances by Toby Jones and Sienna Miller bring to life one of cinematic history''s most horrific abuses of power.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the girl who kicked the hornets nest', 54, 'Slow and mostly devoid of the stellar chemistry between its two leads, The Girl Who Kicked The Hornet''s Nest is a disappointingly uneven conclusion to the Millennium trilogy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the girl with all the gifts', 86, 'The Girl with All the Gifts grapples with thought-provoking questions without skimping on the scares -- and finds a few fresh wrinkles in the well-worn zombie horror genre along the way.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the girl with the dragon tattoo', 85, 'Its graphic violence and sprawling length will prove too much for some viewers to take, but Noomi Rapace''s gripping performance makes The Girl with the Dragon Tattoo an unforgettable viewing experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the glass castle', 52, 'The Glass Castle has an affecting real-life story and a hard-working cast in its corner, but they aren''t enough to outweigh a fundamentally misguided approach to the material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the good dinosaur', 76, 'The Good Dinosaur delivers thrillingly beautiful animation in service of a worthy story that, even if it doesn''t quite live up to the lofty standards set by Pixar, still adds up to charming, family-friendly entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the good lie', 88, 'The Good Lie sacrifices real-life nuance in order to turn its true story into a Hollywood production, but the results still add up to a compelling, well-acted, and deeply moving drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the gospel of john', 37, 'The Gospel of John takes a reverent approach to its story without ever bringing it to life, proving that cribbing from the Good Book isn''t enough to guarantee a good movie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the grandmaster', 78, 'Though its storytelling is a tad muddled, Wong Kar Wai''s The Grandmaster still exhibits the auteur''s stylistic flourishes in gorgeous cinematography and explosive action set pieces.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the great gatsby', 48, 'While certainly ambitious -- and every bit as visually dazzling as one might expect -- Baz Luhrmann''s The Great Gatsby emphasizes visual splendor at the expense of its source material''s vibrant heart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the great train robbery', 73, 'Laboriously paced and overly talky, The Great Train Robbery nevertheless pulls off a thrillingly staged finale anchored by winning performances from Donald Sutherland and Sean Connery.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the great wall', 36, 'For a Yimou Zhang film featuring Matt Damon and Willem Dafoe battling ancient monsters, The Great Wall is neither as exciting nor as entertainingly bonkers as one might hope.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the greatest showman', 56, 'The Greatest Showman tries hard to dazzle the audience with a Barnum-style sense of wonder -- but at the expense of its complex subject''s far more intriguing real-life story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the grinch', 60, 'The Grinch gives the classic Seuss source material a brightly animated update that''s solidly suitable for younger viewers without adding substantially to the story''s legacy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the guardian', 37, 'The Coast Guard gets its chance for a heroic movie tribute, but The Guardian does it no justice, borrowing cliche after cliche from other (and better) military branch movies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the guardians les gardiennes', 93, 'The Guardians proves that the oft-unraveled canvas of World War I still has fresh stories to tell -- and adds another gorgeously filmed entry to Xavier Beauvois'' filmography.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the guilt trip', 37, 'Seth Rogen and Barbra Streisand have enough chemistry to drive a solidly assembled comedy; unfortunately, The Guilt Trip has a lemon of a script and is perilously low on comedic fuel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the gunman', 16, 'With an uninspired plot and rote set pieces that are overshadowed by its star''s physique, The Gunman proves a muddled misfire in the rapidly aging Over-50 Action Hero genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hangover part ii', 33, 'A crueler, darker, raunchier carbon copy of the first installment, The Hangover Part II lacks the element of surprise -- and most of the joy -- that helped make the original a hit.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hateful eight', 75, 'The Hateful Eight offers another well-aimed round from Quentin Tarantino''s signature blend of action, humor, and over-the-top violence -- all while demonstrating an even stronger grip on his filmmaking craft.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the help', 76, 'Though it fails to fully engage with its racial themes, The Help rises on the strength of its cast -- particularly Viola Davis, whose performance is powerful enough to carry the film on its own.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hero', 78, 'The Hero rests on Sam Elliott''s understated performance, which proves more than capable of carrying the film through the less inspired moments of its somewhat clichéd story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the high note', 70, 'The High Note doesn''t quite soar above rom-com formula, but audiences seeking some comfort viewing should find themselves solidly in harmony with this well-acted genre entry.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hobbit the battle of the five armies', 59, 'Though somewhat overwhelmed by its own spectacle, The Hobbit: The Battle of the Five Armies ends Peter Jackson''s second Middle-earth trilogy on a reasonably satisfying note.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hobbit the desolation of smaug', 74, 'While still slightly hamstrung by "middle chapter" narrative problems and its formidable length, The Desolation of Smaug represents a more confident, exciting second chapter for the Hobbit series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hollars', 47, 'The Hollars gathers an impressive assortment of talented stars; unfortunately, it''s all in service of a story that''s been played out more effectively in countless other indie dramedies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the house of the devil', 85, 'Though its underlying themes are familiar, House of the Devil effectively sheds the loud and gory cliches of contemporary horror to deliver a tense, slowly building throwback to the fright flicks of decades past.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the human centipede ii full sequence', 29, 'The Human Centipede II (Full Sequence) attempts to weave in social commentary but as the movie wears on, it loses its ability to repulse and shock and ends up obnoxious and annoying.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the human centipede iii final sequence', 17, 'Human Centipede fans may find enough extreme body horror in the third installment to satisfy, but filmgoers of every other persuasion are strongly advised to stay far, far away from Final Sequence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hundredfoot journey', 67, 'Director Lasse Hallström does lovely work and Helen Mirren is always worth watching, but The Hundred-Foot Journey travels predictable ground already covered by countless feel-good dramedies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hunger games catching fire', 90, 'Smart, smoothly directed, and enriched with a deeper exploration of the franchise''s thought-provoking themes, Catching Fire proves a thoroughly compelling second installment in the Hunger Games series.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the hunger games mockingjay part 1', 69, 'The Hunger Games: Mockingjay - Part 1 sets up the franchise finale with a penultimate chapter loaded with solid performances and smart political subtext, though it comes up short on the action front.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the iceman', 66, 'While it deserved stronger direction and a more fully realized script, Michael Shannon''s riveting performance in the title role is more than enough to make The Iceman recommended viewing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the imaginarium of doctor parnassus', 64, 'Terry Gilliam remains as indulgent as ever, but The Imaginarium of Doctor Parnassus represents a return to the intoxicatingly imaginative, darkly beautiful power of his earlier work, with fine performances to match all the visual spectacle.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the imitation game', 89, 'With an outstanding starring performance from Benedict Cumberbatch illuminating its fact-based story, The Imitation Game serves as an eminently well-made entry in the "prestige biopic" genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the impossible', 81, 'The screenplay isn''t quite as powerful as the direction or the acting, but with such an astonishing real-life story at its center, The Impossible is never less than compelling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the inbetweeners', 53, 'It arguably plays most strongly to fans of the British series, but even viewers who have never seen The Inbetweeners on TV may find themselves won over by the film''s surprisingly tender ribaldry.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the incredible hulk', 67, 'The Incredible Hulk may not be quite the smashing success that fans of Marvel''s raging behemoth might hope for, but it offers more than enough big green action to make up for its occasionally puny narrative.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the incredible jessica james', 88, 'The Incredible Jessica James makes its standard storyline feel new, almost purely on the strength of a captivating, potentially star-making performance from Jessica Williams.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the inevitable defeat of mister pete', 86, 'The Inevitable Defeat of Mister & Pete uses its compelling streetwise setting -- and powerful performances from its young leads -- to offer a refreshing twist on the coming-of-age formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the infiltrator', 72, 'The Infiltrator''s compelling fact-based story and tremendously talented cast are often just enough to balance out its derivative narrative and occasionally clunky execution.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the insult linsulte', 87, 'The Insult uses its familiar courtroom drama framework to deliver a hard-hitting statement on modern Middle Eastern politics that''s as gripping as it is thought-provoking.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the internship', 35, 'The Internship weighs down Vince Vaughn and Owen Wilson''s comic charisma with a formulaic script and padded running time that leans heavily on its stars'' easygoing interplay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the intruder', 33, 'The Intruder might appeal to fans of shout-at-the-screen cinema, but this thriller''s ludicrous plot robs it of suspense -- and undermines Dennis Quaid''s suitably over-the-top performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the inventor out for blood in silicon valley', 78, 'Alex Gibey''s The Inventor declines to outright condemn the actions by Theranos founder Elizabeth Holmes, but instead provides a comprehensive overview of the scandal that allows viewers to mull over its implications towards the broader Silicon Valley.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the invisible woman', 75, 'Its deliberate pace will frustrate some viewers, but for fans of handsomely mounted period drama, The Invisible Woman offers visual as well as emotional cinematic nourishment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the ivory game', 81, 'Hard-hitting and ambitious to a fault, The Ivory Game serves as a fittingly urgent call to action against a looming threat against vulnerable wildlife and a fragile ecosystem.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the jungle book', 94, 'As lovely to behold as it is engrossing to watch, The Jungle Book is the rare remake that actually improves upon its predecessors -- all while setting a new standard for CGI.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the karate kid part iii', 15, 'Inspiration is in short supply in this third Karate Kid film, which recycles the basic narrative from its predecessors but adds scenery-chewing performances and a surprising amount of violence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the killer inside me', 55, 'The Killer Inside Me is stylish and beautifully shot, but Michael Winterbottom''s distance from his characters robs this often brutally violent film of crucial emotional context.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the kindergarten teacher haganenet', 77, 'The Kindergarten Teacher''s crypticness can needlessly feel like homework, but Nadav Lapid''s provocative direction and committed performances give this tale of mentorship and possession a disquieting sting.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the king of staten island', 74, 'The King of Staten Island''s uncertain tone and indulgent length blunt this coming-of-age dramedy''s ability to find itself, but Pete Davidson''s soulful performance holds it together.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lady', 36, 'Even as The Lady focuses on Aung San Suu Kyi''s romantic life parallel to her political ascendancy, Luc Besson''s saccharine direction is too concerned with deifying the Nobel Prize-winner for her humanity to actually shine through.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last 5 years', 60, 'The Last Five Years hits a few awkward notes in its transition from stage to screen, but its freshness and sincere charm -- and well-matched stars -- offer their own rewards.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last days on mars', 18, 'Neither intelligent enough to work as thought-provoking sci-fi nor trashy enough to provide B-movie thrills, The Last Days on Mars proves as cinematically barren as the titular planet.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last dragon', 58, 'The Last Dragon is a flamboyant genre mashup brimming with style, romance, and an infectious fondness for kung fu, but audiences may find the tonal whiplash more goofy than endearing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last laugh', 53, 'Chevy Chase and Richard Dreyfuss are a sight for sore eyes, but they unfortunately do not get The Last Laugh in a generic buddy comedy that never musters any jokes worthy of their comedic chops.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last man on the moon', 94, 'The Last Man on the Moon takes a justifiably reverent look at a largely unexplored chapter in the history of American space exploration -- and a side of astronaut''s lives that''s rarely considered.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last movie star', 59, 'The Last Movie Star has a few poignant moments thanks to Burt Reynolds and Ariel Winter, but their performances are stranded in a middling drama unworthy of their efforts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last of the unjust', 96, 'Documentarian Claude Lanzmann brings the ghosts of the Holocaust back to vivid life once again The Last of the Unjust, a dense and haunting investigation into complicity and moral quandary.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the last witch hunter', 18, 'Grim, plodding, and an overall ill fit for Vin Diesel''s particular charms, The Last Witch Hunter will bore and/or confuse all but the least demanding action-fantasy fans.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the legacy of a whitetail deer hunter', 30, 'The Legacy of a Whitetail Deer Hunter wastes a promising premise and talented cast on a frustratingly uneven comedy that lacks enough laughs to forgive its narrative flaws.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the legend of cocaine island', 78, 'Rodney Hyden''s quixotic quest for riches makes The Legend of Cocaine Island a mirthful adventure, although director Theo Love''s stylistic flourishes are often counterproductive in conveying the inherent interest of this true story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the letters', 29, 'The Letters tries to honor Mother Teresa with an unstintingly positive portrayal of her life and works, but ends up smothering a fascinating real-life story under a bland hagiography.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the light between oceans', 61, 'The Light Between Oceans presents a well-acted and handsomely mounted adaptation of its bestselling source material, but ultimately tugs on the heartstrings too often to be effective.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lion king', 52, 'While it can take pride in its visual achievements,The Lion King is a by-the-numbers retelling that lacks the energy and heart that made the original so beloved--though for some fans that may just be enough.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lives of others', 93, 'Unlike more traditional spy films, The Lives of Others doesn''t sacrifice character for cloak and dagger chases, and the performances (notably that by the late Ulrich Muhe) stay with you.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lobster', 87, 'As strange as it is thrillingly ambitious, The Lobster is definitely an acquired taste -- but for viewers with the fortitude to crack through Yorgos Lanthimos'' offbeat sensibilities, it should prove a savory cinematic treat.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lone ranger', 30, 'Armie Hammer and Johnny Depp make for an appealing pair of leads, but they''re not enough to make up for The Lone Ranger''s bland script, bloated length, and blaring action overkill.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the loneliest planet', 74, 'The source material that inspired The Loneliest Planet may be brief, but this adaptation of a Tom Bissell short story compensates with studious, finely detailed filmmaking, haunting visuals, and thought-provoking subtext.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the longest ride', 31, 'The Longest Ride is less manipulative than the average Nicholas Sparks film, but it''s still saccharine and hopelessly contrived -- not that it''ll matter to the target audience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the look of love', 54, 'While it may not add up to the definitive Paul Raymond biopic -- or take full advantage of Steve Coogan''s many gifts -- The Look of Love still proves an entertainingly old-fashioned look at the Swinging London of the 1960s.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lost city of z', 87, 'The Lost City of Z''s stately pace and visual grandeur hearken back to classic exploration epics, and Charlie Hunnam turns in a masterful performance as its complex protagonist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the love punch', 29, 'In spite of a pair of extremely talented leads and a premise that should lend itself to entertaining action and comedy, The Love Punch manages to waste it all on a bungled attempt at classic caper cinema.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lovers and the despot', 79, 'The Lovers and the Despot offers a compelling -- albeit by no means comprehensive -- look at one of the more bizarrely stranger-than-fiction episodes in cinematic history.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the lucky one', 20, 'While it provides the requisite amount of escapist melodrama, The Lucky One ultimately relies on too many schmaltzy clichés to appeal to anyone not already familiar with the Nicholas Sparks formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the magic of belle isle', 29, 'Neither Rob Reiner nor Morgan Freeman are able to conjure up their old magic in this dull trifle, with both director and star appearing content to tread through the paces of the saccharine script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the magnificent seven', 64, 'The Magnificent Seven never really lives up to the superlative in its title -- or the classics from which it draws inspiration -- but remains a moderately diverting action thriller on its own merits.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man from uncle', 67, 'The Man from U.N.C.L.E. tries to distract from an unremarkable story with charismatic stars and fizzy set pieces, adding up to an uneven action thriller with just enough style to overcome its lack of substance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man who killed hitler and then the bigfoot', 75, 'The Man Who Killed Hitler and Then the Bigfoot just about lives up to the wild promise of its title, due in no small part to Sam Elliott''s world-weary work in the title role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man who knew infinity', 63, 'The Man Who Knew Infinity might be a tad too conventional to truly do its subject justice, but Dev Patel and Jeremy Irons elevate the end result beyond mere biopic formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the man who knew too much', 87, 'Remaking his own 1934 film, Hitchcock imbues The Man Who Knew Too Much with picturesque locales and international intrigue, and is helped by a brilliantly befuddled performance from James Stewart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the marriage of maria braun die ehe der maria braun', 92, 'Hanna Schygulla is a knockout in The Marriage of Maria Braun, an intimate epic that reaffirms Rainer Werner Fassbinder''s mastery of examining multifaceted people and a complicated nation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the martian', 91, 'Smart, thrilling, and surprisingly funny, The Martian offers a faithful adaptation of the bestselling book that brings out the best in leading man Matt Damon and director Ridley Scott.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the maze runner', 65, 'With strong acting, a solid premise, and a refreshingly dark approach to its dystopian setting, The Maze Runner stands out from the crowded field of YA sci-fi adventures.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the meyerowitz stories new and selected', 92, 'The Meyerowitz Stories (New and Selected) observes the family dynamic through writer-director Noah Baumbach''s bittersweet lens and the impressive efforts of a remarkable cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the monster', 81, 'The Monster uses its effectively simple setup and a powerful lead performance from Zoe Kazan to deliver a traditional yet subtly subversive -- and thoroughly entertaining -- horror story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the mortal instruments city of bones', 13, 'The Mortal Instruments: City of Bones borrows ingredients from seemingly every fantasy franchise of the last 30 years -- but can''t seem to figure out what to do with them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the mummy', 16, 'Lacking the campy fun of the franchise''s most recent entries and failing to deliver many monster-movie thrills, The Mummy suggests a speedy unraveling for the Dark Universe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the naked gun 33 13 the final insult', 54, 'Naked Gun 33 1/3: The Final Insult can''t help but be sporadically funny thanks to Leslie Nielsen''s dependably solid work, but it''s still a steep comedown from the original.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the new romantic', 62, 'The New Romantic doesn''t quite achieve the level of storytelling sophistication it aspires to, but Jessica Barden''s performance elevates this enjoyable rom-com with a twist.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the night before', 68, 'The Night Before provokes enough belly laughs to qualify as a worthwhile addition to the list of Christmas comedies worth revisiting, even if it isn''t quite as consistent as the classics.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the night listener', 40, 'This psychological thriller compels by blurring the line between truth and fiction; unfortunately, the film itself gets muddled in a hazy account of Maupin''s original novel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the nines', 65, 'Though The Nines doesn''t solidify as well as writer/director John August would hope for, Ryan Reynolds''s strong performance makes each of the film''s intriguing segments worth watching.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the normal heart', 94, 'Thanks to Emmy-worthy performances from a reputable cast, The Normal Heart is not only a powerful, heartbreaking drama, but also a vital document of events leading up to and through the early AIDS crisis.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the november man', 35, 'The November Man has a few of the ingredients necessary for a better-than-average spy thriller, making it all the more disappointing that it falls back on dull genre clichés.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the number 23', 8, 'Jim Carrey has been sharp in a number of non-comedic roles, but this lurid, overheated, and self-serious potboiler is not one of them. The Number 23 is clumsy, unengaging, and mostly confusing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the nut job', 13, 'Hampered by an unlikable central character and source material stretched too thin to cover its brief running time, The Nut Job will provoke an allergic reaction in all but the least demanding moviegoers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the nut job 2 nutty by nature', 14, 'The Nut Job 2: Nutty by Nature may be a slight improvement over its predecessor, but its frantic animated antics still offer minimal entertainment to all but the least discriminating viewers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the nutcracker and the four realms', 32, 'Lacking a transporting yuletide story or dazzling dance routines, The Nutcracker and the Four Realms is a hollow holiday confection that''s lovely to look at -- and easy to forget.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the old man the gun', 93, 'A well-told story brought to life by a beautifully matched cast, The Old Man & the Gun is pure, easygoing entertainment for film fans - and a fitting farewell to a legend.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the one', 14, 'The One plays more like a video game than a movie and borrows freely from other, better sci-fi actioners, burying Jet Li''s spectacular talents under heaps of editing and special effects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the oogieloves in the big balloon adventure', 30, 'Although it may serve as a passing diversion for very young viewers, The Oogieloves fails to offer much more than several brightly colored examples of the worst stereotypes of modern children''s entertainment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the oranges', 31, 'Despite the efforts of its accomplished cast, The Oranges suffers from a mediocre script that fails to deliver well-rounded characters, dramatic tension, or sufficient laughs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the order of myths', 100, 'More than a documentary about the oldest Mardi Gras celebration in the south, Order of Myths encompasses the eccentric characters of Mobile and the still-lingering racial tensions that surround them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the other woman', 25, 'The Other Woman definitely boasts a talented pedigree, but all that skill is never fully brought to bear on a story that settles for cheap laughs instead of reaching its empowering potential.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the outsider', 17, 'Starring a disengaged Jared Leto and stuffed with gangster cliches, The Outsider never distinguishes itself enough to gain admittance into the inner circle of good yakuza pictures.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the patience stone', 85, 'It may prove frustratingly slow for some viewers, but more contemplative filmgoers will find themselves rewarded by The Patience Stone''s quietly fierce storytelling, as well as a searing starring turn from Golshifteh Farahani.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the peanuts movie', 87, 'The Peanuts Movie offers a colorful gateway into the world of its classic characters and a sweetly nostalgic -- if relatively unambitious -- treat for the adults who grew up with them.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the pirates band of misfits', 86, 'It may not quite scale Aardman''s customary delirious heights, but The Pirates! still represents some of the smartest, most skillfully animated fare that modern cinema has to offer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the place beyond the pines', 78, 'Ambitious to a fault, The Place Beyond the Pines finds writer/director Derek Cianfrance reaching for -- and often grasping -- thorny themes of family, fatherhood, and fate.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the possession', 39, 'It may be based on a true story, but that doesn''t excuse the way The Possession repeatedly falls back on hoary ghost movie clichés -- or the uninentional laughs it provides.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the possession of hannah grace', 18, 'The Possession of Hannah Grace feints at real horror just often enough to offer hints of the movie it should have been -- and further frustrate viewers seeking a good scare.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the predator', 32, 'The Predator has violence and quips to spare, but its chaotically hollow action adds up to another missed opportunity for a franchise increasingly defined by disappointment.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the program', 62, 'Ben Foster''s impressive efforts to channel Lance Armstrong are often enough to power The Program past director Stephen Frears'' frustrating unwillingness to delve deeper into its real-life story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the purge anarchy', 57, 'Gritty, grisly, and uncommonly ambitious, The Purge: Anarchy represents a slight improvement over its predecessor, but it''s still never as smart or resonant as it tries to be.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the raid 2', 81, 'Although its high-energy plot and over-the-top violence may play better with genre aficionados, The Raid 2 definitely delivers more of everything audiences loved about its predecessor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the red turtle la tortue rouge', 93, 'The Red Turtle adds to Studio Ghibli''s estimable legacy with a beautifully animated effort whose deceptively simple story boasts narrative layers as richly absorbing as its lovely visuals.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the reluctant fundamentalist', 57, 'The Reluctant Fundamentalist is technically proficient, with solid acting and cinematography, but its message is so ambitious and heavy-handed that some of its power is robbed.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the rescuers', 81, 'Featuring superlative animation, off-kilter characters, and affectionate voice work by Bob Newhart and Eva Gabor, The Rescuers represents a bright spot in Disney''s post-golden age.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the revenant', 78, 'As starkly beautiful as it is harshly uncompromising, The Revenant uses Leonardo DiCaprio''s committed performance as fuel for an absorbing drama that offers punishing challenges -- and rich rewards.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the rite', 21, 'Anthony Hopkins is as excellent as ever, but he''s no match for The Rite''s dawdling pace and lack of chills -- or Colin O''Donoghue''s tentative performance in the leading role.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the river', 92, 'Jean Renoir''s first film shot in color takes full advantage of its broadened palette, yielding a visually virtuosic coming of age tale filled with moving performances and vibrant hues.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the rocky horror picture show lets do the time warp again', 28, 'Laverne Cox''s fabulous portrayal of Frank N. Furter leads a strong ensemble effort, but the stars can''t infuse this reimagining with enough energy, creativity, and quirk to make TRHPS: Let''s Do the Time Warp Again a worthwhile endeavor.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the runaways', 69, 'Viewers expecting an in-depth biopic will be disappointed, but The Runaways is as electric as the band''s music, largely thanks to strong performances from Michael Shannon, Dakota Fanning, and Kristen Stewart.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the rundown', 69, 'The Rundown doesn''t break any new ground, but it''s a smart, funny buddy action picture with terrific comic chemistry between Dwayne "The Rock" Johnson and Seann William Scott.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the salesman forushande', 96, 'The Salesman takes an ambitiously complex look at thought-provoking themes, and the well-acted results prove another consistently absorbing entry in writer-director Asghar Farhadi''s distinguished filmography.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the salt of the earth', 95, 'While the work it honors may pose thorny ethical questions that Salt of the Earth neglects to answer, it remains a shattering, thought-provoking testament to Sebastião Salgado''s career.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the salvation', 72, 'It''s all but impossible to add anything new or fresh to the traditional Western, but -- thanks in no small part to Mads Mikkelson''s performance -- The Salvation comes close.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the sea of trees', 17, 'Dull, maudlin, and fundamentally empty, The Sea of Trees extinguishes the contributions of a talented cast and marks a depressing low point in director Gus Van Sant''s career.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the secret scripture', 36, 'The Secret Scripture has acclaimed source material and a well-chosen cast in its corner, but despite its stars'' valiant efforts, this adaptation was better left on the page.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the selfish giant', 98, 'Starkly emotional and beautifully directed, The Selfish Giant uses a lovely script and some powerful performances to present some of the best that modern British cinema has to offer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the sense of an ending', 75, 'Anchored by a strong starring performance by Jim Broadbent, The Sense of an Ending proves consistently gripping even as it skims the narrative surface of its literary source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the sessions', 91, 'Tender, funny, and touching, The Sessions provides an acting showcase for its talented stars and proves it''s possible for Hollywood to produce a grown-up movie about sex.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the shape of water', 92, 'The Shape of Water finds Guillermo del Toro at his visually distinctive best -- and matched by an emotionally absorbing story brought to life by a stellar Sally Hawkins performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the silence', 30, 'The Silence has nothing new to say with a derivative premise and placid pacing -- even a wasted Stanley Tucci is unable to elevate the stodgy material a decibel above dreadful.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the single moms club', 18, 'The Single Moms'' Club finds Tyler Perry avoiding some of the pitfalls of his earlier work, but continuing to rely on heavy-handed melodrama at the expense of sensible characters or absorbing storylines.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the smurfs', 21, 'The Smurfs assembles an undeniably talented cast of voice actors and live-action stars -- then crushes them beneath a blue mound of lowest-common-denominator kiddie fare.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the snowtown murders', 83, 'It''s a bleak and brutal endurance test, but for viewers with the strength and patience to make it to the end, Snowtown will prove an uncommonly powerful viewing experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the space between us', 16, 'The Space Between Us strands its star-crossed young lovers in a mind-numbingly vast expanse of shameless cheese that will send all but the most forgiving viewers eye-rolling for the exits.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the square', 85, 'The Square finds writer-director Ruben Östlund as ambitious as ever -- and delivering an unforgettably unusual work whose challenging themes pay thought-provoking dividends.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the strangers prey at night', 39, 'The Strangers: Prey at Night may appeal to fans of the original who''ve been jonesing for a sequel, but its thin story and ironic embrace of genre tropes add up to a bloody step back.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the sugarland express', 85, 'Its plot may ape the countercultural road movies of its era, but Steven Spielberg''s feature debut displays many of the crowd-pleasing elements he''d refine in subsequent films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the sunset limited', 68, 'The Sunset Limited''s ambition is undercut by arch dialogue and a claustrophobic setting, but Tommy Lee Jones and Samuel L. Jackson''s dueling performances bring heft to this battle of wills.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the thorn in the heart', 52, 'Michel Gondry''s directorial style is as bewitching as ever, but his intensely personal subject matter may leave viewers wondering why The Thorn in the Heart didn''t stay in the family.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the three musketeers', 26, 'It plays admirably fast and loose with Alexandre Dumas'' classic tale, but in every other respect, The Three Musketeers offers nothing to recommend -- or to set it apart from the many other film adaptations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the to do list', 55, 'The To Do List may play things disappointingly safe given its rather daring premise, but writer-director Maggie Carey''s sure hand -- and Aubrey Plaza''s performance -- keep the laughs coming.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the transporter refueled', 16, 'The Transporter Refueled has little to offer beyond a handful of decent action sequences, leaving this reboot''s title feeling more like wishful thinking than a restatement of purpose.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the trials of muhammad ali', 89, 'Director Bill Siegel doesn''t explore any new boundaries of the documentary with The Trials of Muhammad Ali, but his subject is so inherently fascinating that the movie proves gripping in spite of its familiar beats.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the trip', 89, 'Amiable, funny and sometimes insightful, The Trip works as both a showcase for the enduring chemistry between stars Steve Coogan and Rob Brydon and an unexpected perusal of men entering mid-life crises.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the trip to spain', 83, 'The Trip to Spain offers more of the same scenery, food, and conversation that filled Steve Coogan and Rob Brydon''s first two Trips -- which is to say, more of a good thing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the trust', 63, 'The Trust may not be an all-time heist classic, but its solidly workmanlike plot -- and the chemistry between Nicolas Cage and Elijah Wood -- should satisfy genre enthusiasts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the twilight saga breaking dawn part 2', 49, 'It''s the most entertaining Twilight, but that''s not enough to make Breaking Dawn Part 2 worth watching for filmgoers who don''t already count themselves among the franchise converts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the unknown known', 82, 'Viewers hoping to see Donald Rumsfeld admit making mistakes in public office (or hoping Errol Morris will force him to give straight answers) may find The Unknown Known frustrating -- but no less fascinating.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the war of the worlds', 89, 'Though it''s dated in spots, The War of the Worlds retains an unnerving power, updating H.G. Wells'' classic sci-fi tale to the Cold War era and featuring some of the best special effects of any 1950s film.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the way way back', 84, 'Despite its familiar themes, The Way Way Back makes use of its talented cast, finely tuned script, and an abundance of charm to deliver a funny and satisfying coming-of-age story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the wedding guest', 44, 'The Wedding Guest makes a compelling argument for Dev Patel as an actor worthy of diverse leading roles, even if the movie''s less than the sum of its action thriller parts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the white crow', 66, 'The White Crow lacks the nimble grace of its subject, but as a reasonably diverting primer on a pivotal period in the life of a brilliant artist, it just about sticks the landing.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the wild life', 17, 'The Wild Life uses its classic source material as a half-hearted springboard into a colorfully animated but essentially empty experience that only the youngest of viewers will find at all entertaining.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the witch', 90, 'As thought-provoking as it is visually compelling, The Witch delivers a deeply unsettling exercise in slow-building horror that suggests great things for debuting writer-director Robert Eggers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the witches', 93, 'With a deliciously wicked performance from Angelica Huston and imaginative puppetry by Jim Henson''s creature shop, Nicolas Roeg''s dark and witty movie captures the spirit of Roald Dahl''s writing like few other adaptations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the wolverine', 71, 'Although its final act succumbs to the usual cartoonish antics, The Wolverine is one superhero movie that manages to stay true to the comics while keeping casual viewers entertained.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the words', 24, 'Neither as clever nor as interesting as it appears to think it is, The Words maroons its talented stars in an overly complex, dramatically inert literary thriller that''s ultimately a poor substitute for a good book.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the world before your feet', 100, 'The World Before Your Feet offers a perspective on New York City that might be entrancingly unfamiliar even to residents -- and beckons viewers toward a more attentive way of life.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the worlds end', 89, 'Madcap and heartfelt, Edgar Wright''s apocalypse comedy The World''s End benefits from the typically hilarious Simon Pegg and Nick Frost, with a plethora of supporting players.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the wretched', 74, 'The Wretched stirs up a savory blend of witch-in-the-woods horror ingredients that should leave genre fans hungry for a second helping from writer-directors Brett and Drew T. Pierce.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the zero theorem', 49, 'Fans of director Terry Gilliam''s trademark visual aesthetic will find everything they''ve bargained for, but for the unconverted, The Zero Theorem may prove too muddled to enjoy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thelma louise', 84, 'Simultaneously funny, heartbreaking, and peppered with action, Ridley Scott''s Thelma & Louise is a potent, well-acted road movie that transcends the feminist message at its core.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('there will be blood', 92, 'Widely touted as a masterpiece, this sparse and sprawling epic about the underhanded "heroes" of capitalism boasts incredible performances by leads Daniel Day-Lewis and Paul Dano, and is director Paul Thomas Anderson''s best work to date.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('these final hours', 84, 'Writer-director Zak Hilditch''s thought-provoking screenplay -- and a stellar performance from young Angourie Rice -- make These Final Hours worth watching, even if its end-of-the-world premise is overly familiar.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('they came together', 68, 'They Came Together is surprisingly messy and perhaps too smart for its own good, but Amy Poehler and Paul Rudd''s chemistry is enough to overcome many of the movie''s flaws.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('things to come lavenir', 99, 'A union to cherish between a writer-director and star working at peak power, Things to Come offers quietly profound observations on life, love, and the irrevocable passage of time.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('third person', 25, 'Third Person finds writer-director Paul Haggis working with a stellar cast and a worthy premise; unfortunately, he fails to fashion a consistently compelling movie out of the intriguing ingredients at his disposal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('this boys life', 76, 'A harrowing, moving drama about a young boy, his single mother, and his abusive stepfather, This Boy''s Life benefits from its terrific cast, and features a breakout performance from a young Leonardo DiCaprio.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('one direction this is us', 63, 'It''s mostly for the converted, but One Direction: This Is Us will be fun for fans -- and it offers just enough slickly edited concert footage to entertain the casual viewer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('this must be the place', 67, 'This Must Be the Place may feature too many wayward detours to satisfy some passengers, but Sean Penn''s beguiling performance and Paolo Sorrentino''s scenic visuals make this a road trip worth following.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('this sporting life', 95, 'Appropriately hard-hitting on narrative as well as physical levels, The Sporting Life remains a British "kitchen sink" classic that''s beautiful to look at and leaves a lingering mark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thomas and the magic railroad', 21, 'Kids these days demand cutting edge special effects or at least a clever plot with cute charectors. This movie has neither, having lost in its Americanization what the British original did so right.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thor ragnarok', 93, 'Exciting, funny, and above all fun, Thor: Ragnarok is a colorful cosmic adventure that sets a new standard for its franchise -- and the rest of the Marvel Cinematic Universe.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thor the dark world', 66, 'It may not be the finest film to come from the Marvel Universe, but Thor: The Dark World still offers plenty of the humor and high-stakes action that fans have come to expect.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('three colors blue trois couleurs bleu', 98, 'Three Colors: Blue contains some of director/co-writer Krzysztof Kieslowski''s most visually arresting, emotionally resonant work -- and boasts an outstanding performance from Juliette Binoche in the bargain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('three colors white trois couleurs blanc', 87, 'Taking a lighter tone than the other films of the Three Colors trilogy, White is a witty, bittersweet comedy with heavier themes on its mind than one might at first realize.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('three days of the condor', 87, 'This post-Watergate thriller captures the paranoid tenor of the times, thanks to Syndey Pollack''s taut direction and excellent performances from Robert Redford and Faye Dunaway.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('three men and a baby 3 men and a baby', 75, 'The American remake of the popular French comedy mostly works a charm under the combined talents of the three leads, who play nicely against type -- although forced plot elements and sentimentality at times dampen the fun.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('throw momma from the train', 63, 'Danny DeVito''s direction is too broad to offer the kind of nastiness that would have made Throw Momma from the Train truly special, but DeVito''s on-screen chemistry with co-star Billy Crystal makes this a smoothly entertaining comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thunderball', 86, 'Lavishly rendered set pieces and Sean Connery''s enduring charm make Thunderball a big, fun adventure, even if it doesn''t quite measure up to the series'' previous heights.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('thunderbolt and lightfoot', 90, 'This likable buddy/road picture deftly mixes action and comedy, and features excellent work from stars Clint Eastwood and Jeff Bridges and first-time director Michael Cimino.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('la tigre e la neve the tiger and the snow', 20, 'The Tiger and the Snow proves Roberto Benigni''s antics are bizarrely ill-suited for a film seeking to strike the unwieldy balance between romance, comedy, and wartime drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('time share tiempo compartido', 86, 'Sharp, funny, and delightfully dark, Time Share (Tiempo Compartido) offers genre fans a complex thriller that sinks its hooks in fast and doesn''t let go until the closing credits.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('to all the boys ps i still love you', 75, 'To All the Boys: P.S. I Still Love You may feel like little more than an amiable postscript to its predecessor, but fans of the original should still find this a swoonworthy sequel.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('to catch a thief', 96, 'It may occasionally be guilty of coasting on pure charm, but To Catch a Thief has it in spades -- as well as a pair of perfectly matched stars in Cary Grant and Grace Kelly.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('to have and have not', 97, 'With Howard Hawks directing and Bogey and Bacall in front of the cameras, To Have and Have Not benefits from several levels of fine-tuned chemistry -- all of which ignite on screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('to kill a mockingbird', 92, 'To Kill a Mockingbird is a textbook example of a message movie done right -- sober-minded and earnest, but never letting its social conscience get in the way of gripping drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('to sir with love', 89, 'While it''s a bit dated and overly schmaltzy, To Sir, With Love remains compelling because of Sidney Poitier''s outstanding performance -- and the catchy theme song is a classic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tokyo sonata tokyo sonata', 94, 'J-Horror director Kiyoshi Kurosawa turns successfully to dramedy and gives a unique (and specifically national) perspective to the universal subjects of family and identity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tomb raider', 51, 'Tomb Raider reboots the franchise with a more grounded approach and a star who''s clearly more than up to the task -- neither of which are well served by an uninspired origin story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tomorrow never dies', 57, 'A competent, if sometimes by-the-numbers entry to the 007 franchise, Tomorrow Never Dies may not boast the most original plot but its action sequences are genuinely thrilling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('too big to fail', 77, 'Too Big to Fail has too sharp a script and superlative a cast to ever feel disposable, even when it teeters toward being an efficient explainer of recent history instead of a fully-realized drama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('top five', 85, 'As smart, funny, and trenchant as writer-director-star Chris Rock''s best standup work, Top Five is a career highlight for its creator -- and one of the comedy standouts of 2014.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('top gun', 54, 'Though it features some of the most memorable and electrifying aereial footage shot with an expert eye for action, Top Gun offers too little for non-adolescent viewers to chew on when its characters aren''t in the air.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('top hat', 100, 'A glamorous and enthralling Depression-era diversion, Top Hat is nearly flawless, with acrobatics by Fred Astaire and Ginger Rogers that make the hardest physical stunts seem light as air.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tora tora tora', 55, 'Tora! Tora! Tora! is scrupulously accurate and lays out of the tragedy of Pearl Harbor with intricate detail, but the film''s clinical approach to the sound and fury signifies little feeling.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('total recall', 31, 'While it boasts some impressive action sequences, Total Recall lacks the intricate plotting, wry humor, and fleshed out characters that made the original a sci-fi classic.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the tourist', 20, 'The scenery and the stars are undeniably beautiful, but they can''t make up for The Tourist''s slow, muddled plot, or the lack of chemistry between Johnny Depp and Angelina Jolie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('towelhead', 49, 'This story of politics, race and, sexual awakening has moments that pack a punch, but overall, Towelhead never quite achieves the nuance of helmer Alan Ball''s television work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the towering inferno', 69, 'Although it is not consistently engaging enough to fully justify its towering runtime, The Towering Inferno is a blustery spectacle that executes its disaster premise with flair.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('town country', 13, 'Afflicted with extensive re-editing and re-writing, this sex comedy feels confusingly choppy. Also, the main characters are so wealthy and privileged that it''s difficult to feel sympathy for their problems.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('toy story 2', 100, 'The rare sequel that arguably improves on its predecessor, Toy Story 2 uses inventive storytelling, gorgeous animation, and a talented cast to deliver another rich moviegoing experience for all ages.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('train to busan busanhaeng', 94, 'Train to Busan delivers a thrillingly unique -- and purely entertaining -- take on the zombie genre, with fully realized characters and plenty of social commentary to underscore the bursts of skillfully staged action.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('trainspotting', 91, 'A brutal, often times funny, other times terrifying portrayal of drug addiction in Edinburgh. Not for the faint of heart, but well worth viewing as a realistic and entertaining reminder of the horrors of drug use.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('trance', 68, 'As stylish as ever, director Danny Boyle seems to be treading water with the surprisingly thinly written Trance -- but for fans of Boyle''s work, it should still prove a trippily entertaining distraction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('transcendence', 19, 'In his directorial debut, ace cinematographer Wally Pfister remains a distinctive visual stylist, but Transcendence''s thought-provoking themes exceed the movie''s narrative grasp.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('transformers age of extinction', 18, 'With the fourth installment in Michael Bay''s blockbuster Transformers franchise, nothing is in disguise: Fans of loud, effects-driven action will find satisfaction, and all others need not apply.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('transformers the last knight', 15, 'Cacophonous, thinly plotted, and boasting state-of-the-art special effects, The Last Knight is pretty much what you''d expect from the fifth installment of the Transformers franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('trespass against us', 57, 'Trespass Against Us benefits from Michael Fassbender and Brendan Gleeson''s typically strong performances, even when they aren''t quite enough to balance the story''s narrative drift and awkward tonal shifts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('triple 9', 54, 'Triple 9''s pulpy potboiler thrills don''t quite live up to the ferocious talents of its cast, but the film''s efficient, solidly crafted genre fun is often enough to balance its troublesome flaws.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('triple frontier', 70, 'An outstanding cast and ambitious story help Triple Frontier overcome an uneven narrative -- and elevate the end result above a crowded field of grim and gritty heist thrillers.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('trolls', 76, 'Trolls brings its instantly recognizable characters to the big screen in a colorful adventure that, while geared toward the younger set, isn''t without rewards for parents.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tron', 72, 'Though perhaps not as strong dramatically as it is technologically, TRON is an original and visually stunning piece of science fiction that represents a landmark work in the history of computer animation.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('trouble with the curve', 51, 'Though predictable and somewhat dramatically underwhelming, Trouble with the Curve benefits from Clint Eastwood''s grizzled charisma and his easy chemistry with a charming Amy Adams.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('trucker', 59, 'Excellent performances by Michelle Monaghan and Nathan Fillion and keenly-observed details of small town life elevate this otherwise predictable and inconsistent melodrama.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('true grit', 96, 'Girded by strong performances from Jeff Bridges, Matt Damon, and newcomer Hailee Steinfeld, and lifted by some of the Coens'' most finely tuned, unaffected work, True Grit is a worthy companion to the Charles Portis book.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('true story', 45, 'James Franco and Jonah Hill make a watchable pair, but True Story loses their performances -- and the viewer''s interest -- in a muddled movie that bungles its fact-based tale.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the truman show', 95, 'A funny, tender, and thought-provoking film, The Truman Show is all the more noteworthy for its remarkably prescient vision of runaway celebrity culture and a nation with an insatiable thirst for the private details of ordinary lives.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('trumbo', 74, 'Trumbo serves as an honorable and well-acted tribute to a brilliant writer''s principled stand, even if it doesn''t quite achieve the greatness of its subject''s own classic screenplays.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tucker the man and his dream', 83, 'Though it may not be as comprehensive as some would like, Francis Ford Coppola''s cheerful biopic of the failed automotive designer features sparkling direction and a strong central performance from Jeff Bridges.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('tully', 87, 'Tully delves into the modern parenthood experience with an admirably deft blend of humor and raw honesty, brought to life by an outstanding performance by Charlize Theron.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('turbo', 66, 'It''s nowhere near as inventive as its off-the-wall premise might suggest, but Turbo boasts just enough colorful visual thrills and sharp voice acting to recommend as undemanding family-friendly fare.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('twelfth night', 76, 'Director Trevor Nunn makes some questionable choices, but his stellar cast -- which includes Helena Bonham-Carter, Ben Kingsley, and Nigel Hawthorne -- more than rises to the material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the twilight saga new moon', 28, 'The Twilight Saga''s second installment may satisfy hardcore fans of the series, but outsiders are likely to be turned off by its slow pace, relentlessly downcast tone, and excessive length.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('two can play that game', 41, 'As a romantic comedy, Two Can Play That Game is more mean-spirited than romantic. Also, some critics say the movie is misogynistic in its attitudes and has too many blatant product placements.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('two thousand maniacs', 41, 'It didn''t take much to thrill early splatter fans, and Two Thousand Maniacs! proves it with its shrill soundtrack, basement-level theatrics, and goofy flesh-tearing gore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('umberto d', 97, 'Anchored by Carlo Battisti''s moving performance as Umberto D, Vittorio de Sica''s deeply empathetic character study is a bracing glimpse into the lives of the downtrodden.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('una', 76, 'Una''s well-matched leads bring an uncomfortable story fearlessly to life, keeping the movie consistently gripping as it navigates the tricky journey from stage to screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('unbreakable', 70, 'With a weaker ending, Unbreakable is not as a good as The Sixth Sense. However, it is a quietly suspenseful film that intrigues and engages, taking the audience through unpredictable twists and turns along the way.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('undead', 32, 'This low-budget homage to the zombie genre borrows heavily from superior predecessors and revels in a pile of its own campiness -- neither original nor watchable enough to entertain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('under the silver lake', 59, 'Under the Silver Lake hits its stride slightly more often than it stumbles, but it''s hard not to admire - or be drawn in by - writer-director David Robert Mitchell''s ambition.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('under the skin', 85, 'Its message may prove elusive for some, but with absorbing imagery and a mesmerizing performance from Scarlett Johansson, Under the Skin is a haunting viewing experience.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('underworld blood wars', 21, 'Underworld: Blood Wars delivers another round of the stylized violence that the series is known for, but -- like many fifth franchise installments -- offers precious little of interest to the unconverted.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('unfinished business', 10, 'Unfocused and unfunny, Unfinished Business lives down to its title with a slipshod screenplay and poorly directed performances that would have been better left unreleased.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('unforgettable', 28, 'Unforgettable''s talented cast makes this domestic thriller consistently watchable, even if its failure to fully embrace its premise''s campy possibilities prevents it from living up to its title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('unfriended dark web', 59, 'Unfriended: Dark Web is more interested in chills than an exploration of its timely themes, but horror fans should still find this sequel to be steadily, undeniably effective.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('unicorn store', 64, 'It''ll be best enjoyed by audiences with a high tolerance for colorful whimsy, but Unicorn Store is easy to like -- and it suggests Brie Larson has a future behind the camera.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('universal soldier day of reckoning', 57, 'The mooted final installment in the long-running series is a hyper-violent, often grim throwback to action movies of yore -- which will appeal to some audiences just as emphatically as it deters others.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('unlocked', 26, 'Unlocked strands an all-star cast in a spy thriller whose embrace of old-school formula might be refreshing if it weren''t bogged down in genre clichés and a predictable plot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('client 9 the rise and fall of eliot spitzer', 90, 'Client 9: The Rise and Fall of Eliot Spitzer finds director Alex Gibney once again probing the dark corners of politics with thought-provoking insights and hard-hitting evidence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the untouchables', 82, 'Slick on the surface but loaded with artful touches, Brian DePalma''s classical gangster thriller is a sharp look at period Chicago crime, featuring excellent performances from a top-notch cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('upstream color', 86, 'As technically brilliant as it is narratively abstract, Upstream Color represents experimental American cinema at its finest -- and reaffirms Shane Carruth as a talent to watch.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the us vs john lennon', 77, 'Though it glosses over anything negative about Lennon, this documentary offers a lot of fascinating archival footage, plus its political issues still have relevance for today.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the usual suspects', 89, 'Expertly shot and edited, The Usual Suspects gives the audience a simple plot and then piles on layers of deceit, twists, and violence before pulling out the rug from underneath.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('vacation', 27, 'Borrowing a basic storyline from the film that inspired it but forgetting the charm, wit, and heart, Vacation is yet another nostalgia-driven retread that misses the mark.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('valentine', 12, 'Valentine is basically a formulaic throwback to conventional pre-Scream slasher flicks. Critics say it doesn''t offer enough suspense or scares to justify its addition to the genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('valerian and the city of a thousand planets', 48, 'Valerian and the City of a Thousand Planets uses sheer kinetic energy and visual thrills to overcome narrative obstacles and offer a viewing experience whose surreal pleasures often outweigh its flaws.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('vampire academy', 16, 'Though it may appeal to its built-in fanbase, Vampire Academy''s Twilight-meets-Mean Girls conceit borrows lazily from its predecessors and offers few laughs or thrills to complement its overstuffed backstory.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('vanilla sky', 42, 'An ambitious mix of genres, Vanilla Sky collapses into an incoherent jumble. Cruise''s performance lacks depth, and it''s hard to feel sympathy for his narcissistic character.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('vehicle 19', 23, 'It starts with an interesting premise and Paul Walker is as handsomely brooding as ever, but Vehicle 19''s incoherently shot action sequences make it a poor substitute for his work in the Fast & Furious movies.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('venom', 30, 'Venom''s first standalone movie turns out to be like the comics character in all the wrong ways - chaotic, noisy, and in desperate need of a stronger attachment to Spider-Man.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('venus', 88, 'Audiences may attend to witness Peter O''Toole''s Oscar-worthy performance, but they''ll also be treated to a humane, tender exploration of maturing with both dignity and irreverence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the verdict', 88, 'Paul Newman is at the peak of his powers as an attorney who never lived up to his potential in The Verdict, supported by David Mamet''s crackling script and Sidney Lumet''s confident direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('verdict on auschwitz the frankfurt trial 19631965', 100, 'Using audiotapes from the Auschwitz Trail, intermixed with archival footage and photographs, Verdict on Auschwitz is an illuminating historical document and a damning indictment of the people who perpetuated those horrors.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('veronica mars', 79, 'It might be a more entertaining watch for diehard fans of the show, but Veronica Mars offers enough sharp writing and solid performances to entertain viewers in the mood for a character-driven thriller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('vertical limit', 48, 'The plot in Vertical Limit is ludicrously contrived and cliched. Meanwhile, the action sequences are so over-the-top and piled one on top of another, they lessen the impact on the viewer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('very good girls', 19, 'Resting on a love triangle played out by poorly drawn characters, Very Good Girls succeeds mainly in making viewers want a better project for Dakota Fanning and Elizabeth Olsen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('victor frankenstein', 26, 'A re-imagining without the imagining, Victor Frankenstein plays at providing a fresh perspective on an oft-told tale, but ultimately offers little of interest that viewers haven''t already seen in superior Frankenstein films.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('victoria', 82, 'Victoria''s single-take production is undeniably impressive, but it''s also an effective drama in its own right -- and one that juggles its tonal shifts as deftly as its technical complexities.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('vincere', 92, 'Part political treatise, part melodrama, Marco Bellocchio''s Mussolini biopic forsakes historical details in favor of absorbing emotion -- and provides a showcase for a stunning performance from Giovanna Mezzogiorno.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the virgin suicides', 77, 'The Virgin Suicides drifts with a dreamlike melancholy that may strike some audiences as tedious, but Sofia Coppola''s feature debut is a mature meditation on disaffected youth.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('w kamau bell private school negro', 82, 'W. Kamau Bell''s affable charisma makes Private School Negro a mirthful dissection of modern America, although although seasoned fans may find the material a bit familiar.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wagons east', 0, 'Wagons East! is a witless, toothless satire of Westerns that falls far below the standard set by Blazing Saddles, and is notable only for being John Candy''s final screen performance.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('waiting for superman', 90, 'Gripping, heartbreaking, and ultimately hopeful, Waiting for Superman is an impassioned indictment of the American school system from An Inconvenient Truth director Davis Guggenheim.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('waking life', 81, 'Waking Life''s inventive animated aesthetic adds a distinctive visual component to a film that could easily have rested on its smart screenplay and talented ensemble cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('waking sleeping beauty', 71, 'It doesn''t probe as deep -- or tell as many hard truths -- as it could have, but Don Hahn''s look at Disney''s rebirth offers a fascinating and surprisingly candorous glimpse into the studio''s past.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('walle', 95, 'Wall-E''s stellar visuals testify once again to Pixar''s ingenuity, while its charming star will captivate younger viewers -- and its timely story offers thought-provoking subtext.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wall street money never sleeps', 55, 'It''s more entertaining than many sequels, but with Oliver Stone directing, a terrific cast, and a timely storyline that picks up where the original left off, Wall Street: Money Never Sleeps should be better.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('waltz with bashir', 96, 'A wholly innovative, original, and vital history lesson, with pioneering animation, Waltz With Bashir delivers its message about the Middle East in a mesmerizing fashion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wanderlust', 59, 'It isn''t always as funny as it should be, but Wanderlust benefits from an extremely talented cast and some of David Wain''s most confident, assured work behind the camera.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('war for the planet of the apes', 94, 'War for the Planet of the Apes combines breathtaking special effects and a powerful, poignant narrative to conclude this rebooted trilogy on a powerful -- and truly blockbuster -- note.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('war of the worlds', 75, 'Steven Spielberg''s adaptation of War of the Worlds delivers on the thrill and paranoia of H.G. Wells'' classic novel while impressively updating the action and effects for modern audiences.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('war on everyone', 61, 'War on Everyone boasts just enough dark humor and infectious energy to make this somewhat middling entry from writer-director John Michael McDonagh an entertaining diversion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('warcraft', 28, 'Warcraft has visual thrills to spare, but they -- and director Duncan Jones'' distinctive gifts -- are wasted on a sluggish and derivative adaptation of a bestselling game with little evident cinematic value.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wargames war games', 93, 'Part delightfully tense techno-thriller, part refreshingly unpatronizing teen drama, WarGames is one of the more inventive -- and genuinely suspenseful -- Cold War movies of the 1980s.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('watchers of the sky', 86, 'Watchers of the Sky offers a consistently gripping look at one man''s incredible legacy, even if it can''t hope to offer a comprehensive overview of a huge, complicated subject.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('watchmen', 65, 'Gritty and visually striking, Watchmen is a faithful adaptation of Alan Moore''s graphic novel, but its complex narrative structure may make it difficult for it to appeal to viewers not already familiar with the source material.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('waterworld', 46, 'Though it suffered from toxic buzz at the time of its release, Waterworld is ultimately an ambitious misfire: an extravagant sci-fi flick with some decent moments and a lot of silly ones.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the way of the gun', 45, 'Christopher McQuarrie may exhibit a way behind the camera in the stylish The Way of the Gun, but his script falters with dull characterization and a plot so needlessly twisty that most viewers will be ready to tune out before the final reveal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the way we were', 63, 'The Way We Were is not politically confrontational enough for its story of ideological opposites falling in love to feel authentic, but Barbra Streisand and Robert Redford''s beaming star power gives this melodrama romantic lift.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('we are marshall', 48, 'Matthew McConaughey almost runs We Are Marshall to the end zone, but can''t stop it from taking the easy, feel-good route in memorializing this historic event in American sports.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('we are still here', 95, 'Smart, powerfully acted, and devilishly clever, We Are Still Here offers some novel twists on familiar territory -- and heralds the arrival of a major talent in writer-director Ted Geoghegan.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('we need to talk about kevin', 75, 'We Need to Talk About Kevin is a masterful blend of drama and horror, with fantastic performances across the board (Tilda Swinton especially, delivering one of her very best).');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('we steal secrets the story of wikileaks', 92, 'As fascinating as it is provocative, We Steal Secrets: The Story of Wikileaks presents another documentary triumph for director Alex Gibney, as well as a troubling look at one of the more meaningful issues of our time.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('welcome to the punch', 48, 'Welcome to the Punch is a little deeper and more thoughtful than most police dramas -- but not quite enough to surmount its thinly written characters and numbing violence.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('west of memphis', 95, 'Both a sobering look at a true crime story and a scathing indictment of the American justice system, West of Memphis is a real-life horror story told with fury and compassion.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('west side story', 92, 'Buoyed by Robert Wise''s dazzling direction, Leonard Bernstein''s score, and Stephen Sondheim''s lyrics, West Side Story remains perhaps the most iconic of all the Shakespeare adaptations to visit the big screen.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('what if', 74, 'Its narrative framework may be familiar, but What If transcends its derivative elements with sharp dialogue and the effervescent chemistry of stars Daniel Radcliffe and Zoe Kazan.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('what maisie knew', 87, 'It''s undeniably difficult to watch at times, but What Maisie Knew ultimately rises on the strength of its solidly sourced script, powerful performances, and empathetic direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('what they had', 86, 'What They Had finds laughter and tears in its portrait of a family at a crossroads, with writer-director Elizabeth Chomko getting outstanding performances out of a talented cast.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('what to expect when youre expecting', 22, 'The cast is stocked with likable performers, but What to Expect When You''re Expecting is too disjointed -- and too reliant on stock rom-com cliches -- to live up to its distinguished literary namesake.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('whats cooking', 52, 'What''s Cooking? is well-acted, but the scenes sometimes sink into melodrama as characters scream at each other, and the movie as a whole is too lightweight and forgettable.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('whats eating gilbert grape', 90, 'It''s sentimental and somewhat predictable, but those are small complaints, given the tender atmosphere and moving performances at the heart of What''s Eating Gilbert Grape.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('when the game stands tall', 20, 'An uneasy blend of solid game sequences and threadbare inspirational sports drama clichés, When the Game Stands Tall is overshadowed by better players in a crowded field.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('when we first met', 43, 'Much like its protagonist, When We First Met struggles in the cinematic "friend zone" -- and will face a slew of viewer breakups before finding much in the way of true love.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('where the wild things are', 73, 'Some may find its dark tone and slender narrative off-putting, but Spike Jonze''s heartfelt adaptation of the classic children''s book is as beautiful as it is uncompromising.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('whered you go bernadette', 49, 'Where''d You Go, Bernadette offers dispiriting proof that a talented director, bestselling source material, and terrific cast can add up to far less than the sum of their parts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('while were young', 84, 'Poignant and piercingly honest, While We''re Young finds writer-director Noah Baumbach delivering some of his funniest lines through some of his most relatable characters.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('while you were sleeping', 80, 'While You Were Sleeping is built wholly from familiar ingredients, but assembled with such skill -- and with such a charming performance from Sandra Bullock -- that it gives formula a good name.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('whiplash', 94, 'Intense, inspiring, and well-acted, Whiplash is a brilliant sophomore effort from director Damien Chazelle and a riveting vehicle for stars J.K. Simmons and Miles Teller.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('white bird in a blizzard', 54, 'Part suburban thriller, part sexual awakening drama -- and fully convincing as neither -- White Bird in a Blizzard rests a little too heavily on Shailene Woodley''s typically superlative work.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('white heat', 97, 'Raoul Walsh''s crime drama goes further into the psychology of a gangster than most fear to tread and James Cagney''s portrayal of the tragic anti-hero is constantly volatile.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('white material', 86, 'Isabelle Huppert is an immoveable object surrounded by unstoppable forces in White Material, an incendiary character study and political thriller that showcases director Claire Denis'' expertise in ratcheting tension.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('white squall', 58, 'Though it gets occasionally bogged down by touchy-feely sentiment, White Squall benefits greatly from Jeff Bridges'' assured lead performance and Ridley Scott''s visceral, exciting direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('whitey united states of america v james j bulger', 80, 'An admirable yet incomplete effort to cover a sprawling subject, Whitey: United States of America v. James J. Bulger will leave viewers wanting more -- in good ways as well as bad.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('who framed roger rabbit', 97, 'Who Framed Roger Rabbit is an innovative and entertaining film that features a groundbreaking mix of live action and animation, with a touching and original story to boot.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('whos afraid of virginia woolf', 95, 'Led by a volcanic performance from Elizabeth Taylor, Who''s Afraid of Virginia Woolf? is a scathing adaptation of the Edward Albee play that serves as a brilliant calling card for debuting director Mike Nichols.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('why did i get married too', 27, 'It''s bolstered by a strong performance from Janet Jackson, but ultimately, Tyler Perry''s Why Did I Get Married Too? doesn''t add anything new to Perry''s melodramatic formula.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wild rose', 92, 'There''s no shortage of star-is-born stories, but Wild Rose proves they can still be thoroughly entertaining -- and marks its own transcendent moment for lead Jessie Buckley.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wildlife', 93, 'Wildlife''s portrait of a family in crisis is beautifully composed by director Paul Dano -- and brought brilliantly to life by a career-best performance from Carey Mulligan.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('willow creek', 81, 'Writer-director Bobcat Goldthwait''s first foray into horror doesn''t break any new ground, but it does wring fresh terror from a well-worn genre formula -- and offers a few nasty laughs in the bargain.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wilson', 47, 'Woody Harrelson delivers a solid performance as Wilson''s titular grump, but the movie surrounding him can''t quite manage to make the character''s sour outlook consistently relatable.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wind river', 88, 'Wind River lures viewers into a character-driven mystery with smart writing, a strong cast, and a skillfully rendered setting that delivers the bitter chill promised by its title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wings', 93, 'Subsequent war epics may have borrowed heavily from the original Best Picture winner, but they''ve all lacked Clara Bow''s luminous screen presence and William Wellman''s deft direction.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('winnebago man', 90, 'Though it doesn''t quite answer all of the questions it raises, Winnebago Man is nevertheless a fascinating, hilarious, and surprisingly poignant look at a geniunely colorful internet celebrity.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wish you were here', 71, 'Smart, slick, and thrilling, Wish You Were Here benefits from a compelling mystery at the center of its tightly wound plot, as well as strong performances from a cast that includes Joel Edgerton.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('withnail and i', 94, 'Richard E. Grant and Paul McGann prove irresistibly hilarious as two misanthropic slackers in Withnail and I, a biting examination of artists living on the fringes of prosperity and good taste.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('without limits', 79, 'This drama about American track star and hero Steve Prefontaine intelligently looks at the character of this oft mythologized athlete and features a fantastic performance by Donald Sutherland as Prefontaine''s trainer.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the wiz', 42, 'This workmanlike movie musical lacks the electricity of the stage version (and its cinematic inspiration), but it''s bolstered by strong performances by Diana Ross and Michael Jackson.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('woman in gold', 57, 'Woman in Gold benefits from its talented leads, but strong work from Helen Mirren and Ryan Reynolds isn''t enough to overpower a disappointingly dull treatment of a fascinating true story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('woman on top', 35, 'Despite Penelope Cruz''s beauty and charm, the movie is too tepid to be a romance and too silly to be believable. And the movie is too eager to please with an ending that seems more like a cop out.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('a woman under the influence', 90, 'Electrified by searing performances from Gena Rowlands and Peter Falk, A Woman Under the Influence finds pioneering independent filmmaker John Cassavetes working at his artistic peak.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('woman walks ahead', 53, 'Woman Walks Ahead gets some extra mileage out of watchable work from Jessica Chastain and Michael Greyeyes, but uneven pacing and two-dimensional characters undermine their efforts.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('women in trouble', 29, 'Sebastian Gutierrez certainly has an eye for the beauty of the female form, but Women in Trouble lacks a compelling script or point of view to go with its curvaceous visual appeal.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wonder wheel', 31, 'Wonder Wheel gathers a charming cast in an inviting period setting, but they aren''t enough to consistently breathe life into a Woody Allen project that never quite comes together.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wonderstruck', 68, 'Wonderstruck''s efforts to juggle timelines and tonal shifts aren''t always smooth, but the end result still adds up to an emotional journey whose visual thrills live up to its title.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the woodsman', 88, 'Kevin Bacon''s performance as a pedophile who is trying to start fresh has drawn raves from critics, who have praised the Woodsman as compelling, creepy, complex and well-crafted.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('woodstock 3 days of peace music', 100, 'By documenting arguably the most renowned music festival in history, Woodstock: 3 Days of Peace & Music achieves the rare feat of capturing the unique spirit of its time.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wordplay', 94, 'You see them hunched over with their brows furrowed, folded newspaper in hand as they attempt to complete the crossword puzzle. This may even describe you. This ingeniously edited documentary introduces viewers to some of the more dedicated fans of this solitary pastime, none more well-known the puzzle editor for the New York Times, Will Shortz. This underground world provides a surprising amount of crowd-pleasing entertainment and suspense, especially at the annual crossword tournament. Didn''t know there was one, did you?');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('words and pictures', 43, 'While both talented performers in their own right, Juliette Binoche and Clive Owen are decidedly mismatched in Words and Pictures, and they aren''t done many favors by the movie''s awkwardly constructed screenplay.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the world is not enough', 52, 'Plagued by mediocre writing, uneven acting, and a fairly by-the-numbers plot, The World Is Not Enough is partially saved by some entertaining and truly Bond-worthy action sequences.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wreckit ralph', 87, 'Equally entertaining for both kids and parents old enough to catch the references, Wreck-It Ralph is a clever, colorful adventure built on familiar themes and joyful nostalgia.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wrestling ernest hemingway', 57, 'Predictable but moving, Wrestling Ernest Hemingway is an understated and melancholic drama that gets plenty of mileage out of an outstanding cast that includes Robert Duvall, Richard Harris, Shirley MacLaine, and Sandra Bullock.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wristcutters a love story', 67, 'Wristcutters: A Love Story sounds like a normal enough indie flick. Boy meets girl. Boy gets separated from girl. Boy goes on a road trip with friends to find girl and gains a new perspective on life. Except everybody''s dead.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wrongfully accused', 21, 'Wrongfully Accused of being a comedy worthy of Leslie Nielsen''s involvement, this misbegotten spoof might have fewer laughs than the straight-faced thriller that inspired it.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('wuthering heights', 68, 'Director Andrea Arnold''s gritty, naturalistic re-imagining of the Emily Bronte classic stays true to the book''s spirit while utilizing an unconventional approach to explore the romantic yearning at the heart of the story.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the xfiles i want to believe the x files 2', 31, 'The chemistry between leads David Duchovny and Gillian Anderson do live up to The X-Files'' televised legacy, but the roving plot and droning routines make it hard to identify just what we''re meant to believe in.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('xmen apocalypse', 47, 'Overloaded action and a cliched villain take the focus away from otherwise strong performers and resonant themes, making X-Men: Apocalypse a middling chapter of the venerable superhero franchise.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('xmen', 81, 'Faithful to the comics and filled with action, X-Men brings a crowded slate of classic Marvel characters to the screen with a talented ensemble cast and surprisingly sharp narrative focus.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('xx', 70, 'XX''s array of distinct female filmmaking voices -- and the empowerment their collection represents -- offer enough thrills to make up for the overall uneven quality that plagues most anthology projects.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('xxx', 48, 'It has an endearing lack of seriousness, and Vin Diesel has more than enough muscle for the starring role, but ultimately, XXX is a missed opportunity to breathe new life into the spy thriller genre.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('xxx return of xander cage', 45, 'xXx: Return of Xander Cage should satisfy fans of the first two installments, but its preponderance of set pieces can''t quite make up for a tired storyline that fails to take the franchise -- or action fans -- anywhere new.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('the year of living dangerously', 88, 'Both a smart, suspenseful tale of intrigue and a sweeping romance, The Year of Living Dangerously features excellent performances from Mel Gibson and Sigourney Weaver as a pair of journalists covering political unrest in Indonesia.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('year of the fish', 58, 'This modernized and rotoscope-animated update on the Cinderella story is charming at times and visually impressive, but audiences may find it to be too coarse for children and too superficial for adults.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('you can count on me', 95, 'You Can Count On Me may look like it belongs on the small screen, but the movie surprises with its simple yet affecting story. Beautifully acted and crafted, the movie will simply draw you in.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('you cant take it with you', 93, 'It''s predictably uplifting fare from Frank Capra, perhaps the most consciously uplifting of all great American directors -- but thanks to immensely appealing performances and a nimble script, You Can''t Take It With You is hard not to love.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('you only live twice', 73, 'With exotic locales, impressive special effects, and a worthy central villain, You Only Live Twice overcomes a messy and implausible story to deliver another memorable early Bond flick.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('you were never really here', 89, 'Bracingly elevated by a typically committed lead performance from Joaquin Phoenix, You Were Never Really Here confirms writer-director Lynne Ramsay as one of modern cinema''s most unique -- and uncompromising -- voices.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('young adult', 80, 'Despite its somewhat dour approach, Young Adult is a funny and ultimately powerful no-holds-barred examination of prolonged adolescence, thanks largely to a convincing performance by Charlize Theron.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('young beautiful jeune et jolie', 73, 'Ozon may not explore his themes as fully as he should, but Young & Beautiful poses enough intriguing questions -- and features a strong enough performance from Marine Vacth -- to compensate for its frustrations.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('young mr lincoln', 100, 'Young Mr. Lincoln smartly sidesteps the grandeur of the 16th president''s historical significance and instead hones in on his modest decency, powerfully embodied by Henry Fonda.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('your friends neighbors', 77, 'Though it may strike some viewers as cold and unpleasant, Neil LaBute''s Your Friends & Neighbors is an incisive critique of sexual politics wrapped up in a scathing black comedy.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('your highness', 28, 'Big budgets and costumes in service of scatalogical jokes may seem funny on paper, but in execution this is a highly monotonous romp that registers only occasional laughs.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('youth', 72, 'Gorgeously filmed and beautifully acted, Youth offers an enticing -- albeit flawed -- opportunity to witness an impressive array of seasoned veterans combining their cinematic might.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('youth in revolt', 66, 'It may not entirely do its source material justice, but Miguel Arteta''s Youth in Revolt is a fun, funny comic romp that lets Michael Cera stretch a little and introduces filmgoers to a major find in Portia Doubleday.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zaytoun', 46, 'It has a lot on its mind, including a timely storyline with real-world significance; unfortunately, Zaytoun''s reach exceeds its grasp, partly due to the presence of a miscast Stephen Dorff.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zero days', 92, 'Factors beyond Gibney''s control prevent Zero Days from offering a comprehensive look at its subject, but the partial picture that emerges remains as frightening as it is impossible to ignore.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zero motivation', 88, 'Darkly funny and understatedly absurd, Zero Motivation is a refreshing addition to the canon of irreverent war comedies -- and an intriguing calling card for writer-director Talya Lavie.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zipper', 20, 'Patrick Wilson tries his best to elevate tawdry material, but Zipper is a morality tale that makes its points so clumsily that they inspire more unintentional laughter than thought.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zodiac', 89, 'A quiet, dialogue-driven thriller that delivers with scene after scene of gut-wrenching anxiety. David Fincher also spends more time illustrating nuances of his characters and recreating the mood of the 70s than he does on gory details of murder.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zoolander 2', 22, 'Zoolander No. 2 has more celebrity cameos than laughs -- and its meager handful of memorable gags outnumbers the few worthwhile ideas discernible in its scattershot rehash of a script.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zootopia', 98, 'The brilliantly well-rounded Zootopia offers a thoughtful, inclusive message that''s as rich and timely as its sumptuously state-of-the-art animation -- all while remaining fast and funny enough to keep younger viewers entertained.');
INSERT INTO rt_reviews (norm_title, tomatometer_rating, critics_consensus) 
                VALUES ('zulu', 96, 'Zulu patiently establishes a cast of colorful characters and insurmountable stakes before unleashing its white-knuckle spectacle, delivering an unforgettable war epic in the bargain.');
COMMIT;